          counter.labels("calculateProductScore_upload", "failed");
        })
        .doOnComplete(() -> {
          log.info("client upload complete");
          downloadStream.onComplete();
        })
        .subscribe();

    return new RxStreamObserver<>(uploadStream);

  }

