    try {
      BufferedInputStream imageStream = new BufferedInputStream(
          productImageSeeker.seekProductImage(request.getProductId())
      );
      int bufferSize = 256 * 1024;// 256k
      byte[] buffer = new byte[bufferSize];
      int length;
      while ((length = imageStream.read(buffer, 0, bufferSize)) != -1) {
        responseObserver.onNext(
            DataChunk.newBuilder().setData(ByteString.copyFrom(buffer, 0, length)).build()
        );
      }
      responseObserver.onCompleted();
      imageStream.close();
      counter.labels("downloadProductImage", "success");
    } catch (Exception e) {
      counter.labels("downloadProductImage", "failed");
      log.error("error on read product image", e);
      responseObserver.onError(e);
    }

  }

@Test
  public void downloadProductImage() throws Exception {
    when(productImageSeeker.seekProductImage(anyLong()))
        .thenReturn(Resources.getResource("Large_Scaled_Forest_Lizard.jpg").openStream());

    AtomicBoolean completed = new AtomicBoolean(false);
    AtomicBoolean error = new AtomicBoolean(false);
    File imageFile = File.createTempFile("image", ".jpg");
    imageFile.deleteOnExit();
    Files.touch(imageFile);
    ByteSink byteSink = Files.asByteSink(imageFile, FileWriteMode.APPEND);
    StreamObserver<DataChunk> streamObserver = new StreamObserver<DataChunk>() {
      @Override
      public void onNext(DataChunk dataChunk) {
        try {
          byteSink.write(dataChunk.getData().toByteArray());
        } catch (IOException e) {
          log.error("error on write files", e);
          onError(e);
        }
      }

      @Override
      public void onError(Throwable t) {
        error.compareAndSet(false, true);
      }

      @Override
      public void onCompleted() {
        log.info("write image to {}", imageFile.getAbsoluteFile());
        completed.compareAndSet(false, true);
      }
    };
    stub.downloadProductImage(DownloadProductImageRequest.getDefaultInstance(), streamObserver);

    while (!completed.get() && !error.get()) {
      Thread.sleep(500);
    }

    assertThat(completed.get()).isTrue();
    assertThat(error.get()).isFalse();

    try (InputStream destImageStream = new FileInputStream(imageFile);
         InputStream origImageStream = Resources.getResource("Large_Scaled_Forest_Lizard.jpg").openStream()) {
      assertThat(DigestUtils.md5Hex(destImageStream)).isEqualTo(
          DigestUtils.md5Hex(origImageStream)
      );
    }
  }

public SearchProductsResponse searchProducts(SearchProductsRequest request) throws InvalidProtocolBufferException {
    QueryBuilder queryBuilder = QueryBuilders.boolQuery()
        .must(QueryBuilders.matchQuery("productName", request.getKeyWord()));
    SearchResponse response = esClient.prepareSearch(INDEX)
        .setTypes(TYPE)
        .setQuery(queryBuilder)
        .setSize(request.getLimit())
        .execute()
        .actionGet();
    SearchHits hits = response.getHits();
    SearchProductsResponse.Builder responseBuilder = SearchProductsResponse.newBuilder();
    for (SearchHit hit : hits) {
      Product.Builder builder = Product.newBuilder();
      jsonParser.merge(hit.getSourceAsString(), builder);
      responseBuilder.addProducts(builder.build());
    }
    return responseBuilder.build();
  }

