public String generate() {

    final StringBuilder sb = new StringBuilder();

    this.j.types()
        .filter(t -> !t.typeName().startsWith("__"))
        .forEach(nt -> {

          switch (nt.logicalKind()) {
            case OUTPUT:
              this.generate((ExecutableOutputType) nt, sb);
              break;
            case SCALAR:
              this.generate((ExecutableScalarType) nt, sb);
              break;
            case ENUM:
              this.generate((ExecutableEnumType) nt, sb);
              break;
            case INPUT:
            case INTERFACE:
            case UNION:
            default:
              break;
          }

        });

    if (!this.j.operationTypes().isEmpty()) {
      sb.append("schema {\n");

      this.j.operationTypes()
          .forEach((op, type) -> {
            sb.append("  ");
            sb.append(op);
            sb.append(": ");
            sb.append(type.typeName());
            sb.append("\n");
          });

      sb.append("}\n\n");
    }

    return sb.toString();

  }

