public static Property extractProperty(String propertyDefinition) {
        Property property = null;
        if (propertyDefinition != null) {
            String[] propertyAttributes = propertyDefinition.split(PIPE_REGEX, 2);

            String name = propertyAttributes[NAME_INDEX].trim();
            // Valeurs par défaut
            boolean isRequired = false;
            String comment = "";
            String defaultValue = "";
            String pattern = "";
            boolean isPassword = false;

            if (propertyAttributes.length > 1) {
                comment = null;

                String propertyAnnotations = propertyAttributes[ANNOTATIONS_INDEX];
                if (!startsWithKnownAnnotation(propertyAnnotations)) {
                    // Si la valeur des annotations ne commence pas avec une annotation connue,
                    // on considère que le début de la chaîne est le commentaire,
                    comment = extractValueBeforeFirstKnownAnnotation(propertyAnnotations);
                }

                String[] splitAnnotations = splitAnnotationsButKeepDelimiters(propertyAnnotations);
                for (String annotationDefinition : splitAnnotations) {

                    if (annotationDefinitionStartsWith(annotationDefinition, AnnotationType.IS_REQUIRED, propertyAnnotations)) {
                        // #318
                        if (annotationIsFollowedBySpace(AnnotationType.IS_REQUIRED, propertyAnnotations)) {
                            validateIsBlank(extractAnnotationValueLegacyStyle(annotationDefinition),
                                    String.format("Property '%s' has a @required annotation that should not be followed by a value", name));
                            isRequired = true;
                        }

                    } else if (annotationDefinitionStartsWith(annotationDefinition, AnnotationType.COMMENT, propertyAnnotations)) {
                        validateIsBlank(comment, String.format("Property '%s' has more than one comment", name));
                        // #311
                        if (onlyStartsWithQuotes(extractValueAfterFirstSpace(annotationDefinition))) {
                            // #324
                            String valueBetweenQuotes = extractCommentThatStartsWithQuotes(propertyAnnotations);
                            if (valueBetweenQuotes != null) {
                                comment = valueBetweenQuotes;
                            }
                            break;
                        } else {
                            comment = extractAnnotationValueLegacyStyle(annotationDefinition);
                        }
                        // #317
                        if (comment != null) {
                            comment = comment.trim();
                        }

                    } else if (annotationDefinitionStartsWith(annotationDefinition, AnnotationType.DEFAULT_VALUE, propertyAnnotations)) {
                        validateIsBlank(defaultValue, String.format("Property '%s' has more than one default value", name));
                        defaultValue = extractAnnotationValueLegacyStyle(annotationDefinition);
                        validateIsNotBlank(defaultValue, String.format("Property '%s' has an empty or invalid default value", name));
                        validateDoesntStartWithArobase(defaultValue, name);

                    } else if (annotationDefinitionStartsWith(annotationDefinition, AnnotationType.PATTERN, propertyAnnotations)) {
                        validateIsBlank(pattern, String.format("Property '%s' has more than one pattern", name));
                        pattern = extractAnnotationValueLegacyStyle(annotationDefinition);
                        validateIsNotBlank(pattern, String.format("Property '%s' has an empty or invalid pattern", name));
                        validateDoesntStartWithArobase(pattern, name);

                    } else if (annotationDefinitionStartsWith(annotationDefinition, AnnotationType.IS_PASSWORD, propertyAnnotations)) {
                        // #318
                        if (annotationIsFollowedBySpace(AnnotationType.IS_PASSWORD, propertyAnnotations)) {
                            validateIsBlank(extractAnnotationValueLegacyStyle(annotationDefinition),
                                    String.format("Property '%s' has a @password annotation that should not be followed by a value", name));
                            isPassword = true;
                        }
                    }
                }
            }

            validateRequiredOrDefaultValue(name, isRequired, defaultValue);

            property = new Property(propertyDefinition, name, isRequired, comment, defaultValue, pattern, isPassword);
        }
        return property;
    }

@Test
    public void testExtractProperty() {

        //Cas nominaux

        assertProperty(new Property(" named property ", "named property", false, "", "", "", false),
                Property.extractProperty(" named property "));

        assertProperty(new Property("required property| @required ", "required property", true, null, "", "", false),
                Property.extractProperty("required property| @required "));

        assertProperty(new Property("comment without quotes| @comment comment", "comment without quotes", false, "comment", "", "", false),
                Property.extractProperty("comment without quotes| @comment comment"));

        assertProperty(new Property("comment with double quotes| @comment \"a comment\"", "comment with double quotes", false, "a comment", "", "", false),
                Property.extractProperty("comment with double quotes| @comment \"a comment\""));

        assertProperty(new Property("comment with simple quotes| @comment 'a comment'", "comment with simple quotes", false, "a comment", "", "", false),
                Property.extractProperty("comment with simple quotes| @comment 'a comment'"));

        assertProperty(new Property("default value| @default 12", "default value", false, null, "12", "", false),
                Property.extractProperty("default value| @default 12"));

        assertProperty(new Property(" with pattern | @pattern \"*\"", "with pattern", false, null, "", "*", false),
                Property.extractProperty(" with pattern | @pattern \"*\""));

        assertProperty(new Property(" is password | @password ", "is password", false, null, "", "", true),
                Property.extractProperty(" is password | @password "));

        assertProperty(new Property(" full without default value | @required @comment 'a comment' @pattern * @password ", "full without default value", true, "a comment", "", "*", true),
                Property.extractProperty(" full without default value | @required @comment 'a comment' @pattern * @password "));

        assertProperty(new Property(" full not required | @comment 'a comment' @default 12 @pattern * @password ", "full not required", false, "a comment", "12", "*", true),
                Property.extractProperty(" full not required | @comment 'a comment' @default 12 @pattern * @password "));

        // Valeur d'annotation contenant un ou plusieurs pipes, typiquement un pattern

        assertProperty(new Property("pattern with pipe| @pattern (a|b|c)", "pattern with pipe", false, null, "", "(a|b|c)", false),
                Property.extractProperty("pattern with pipe| @pattern (a|b|c)"));

        assertProperty(new Property("pattern with pipe| @pattern '(a|b|c)'", "pattern with pipe", false, null, "", "(a|b|c)", false),
                Property.extractProperty("pattern with pipe| @pattern '(a|b|c)'"));

        // Annotations séparées par des pipes

        assertProperty(new Property("pipe separated annotations | @comment comment | @default 12", "pipe separated annotations", false, "comment", "12", "", false),
                Property.extractProperty("pipe separated annotations | @comment comment | @default 12"));

        // Commentaire vide ou absent

        assertProperty(new Property("missing comment| @comment ", "missing comment", false, null, "", "", false),
                Property.extractProperty("missing comment| @comment "));

        assertProperty(new Property("empty comment| @comment \"\"", "empty comment", false, null, "", "", false),
                Property.extractProperty("empty comment| @comment \"\""));

        assertProperty(new Property("empty comment| @comment ''", "empty comment", false, null, "", "", false),
                Property.extractProperty("empty comment| @comment ''"));

        assertProperty(new Property("blank comment|                   ", "blank comment", false, null, "", "", false),
                Property.extractProperty("blank comment|                   "));

        assertProperty(new Property("no comment|", "no comment", false, null, "", "", false),
                Property.extractProperty("no comment|"));

        // Commentaire avant annotation

        assertProperty(new Property("comment before annotation| comment @required ", "comment before annotation", true, "comment", "", "", false),
                Property.extractProperty("comment before annotation| comment @required "));

        // Autres commentaires

        assertProperty(new Property("comment without annotation | a comment ", "comment without annotation", false, "a comment", "", "", false),
                Property.extractProperty("comment without annotation | a comment "));

        assertProperty(new Property("comment without annotation but with double quotes | \"a comment\"", "comment without annotation but with double quotes", false, "\"a comment\"", "", "", false),
                Property.extractProperty("comment without annotation but with double quotes | \"a comment\""));

        assertProperty(new Property("comment without annotation but with simple quotes | 'a comment'", "comment without annotation but with simple quotes", false, "'a comment'", "", "", false),
                Property.extractProperty("comment without annotation but with simple quotes | 'a comment'"));

        assertProperty(new Property("comment with annotation and arobase| @comment '@admin and @user'", "comment with annotation and arobase", false, "@admin and @user", "", "", false),
                Property.extractProperty("comment with annotation and arobase| @comment '@admin and @user'"));

        assertProperty(new Property("comment with annotation and arobase| @comment @admin", "comment with annotation and arobase", false, "@admin", "", "", false),
                Property.extractProperty("comment with annotation and arobase| @comment @admin"));

        assertProperty(new Property("comment that is an email address| name@email.com ", "comment that is an email address", false, "name", "", "", false),
                Property.extractProperty("comment that is an email address| name@email.com "));

        assertProperty(new Property("comment that is an email address| @comment name@email.com ", "comment that is an email address", false, "name@email.com", "", "", false),
                Property.extractProperty("comment that is an email address| @comment name@email.com "));

        assertProperty(new Property("comment that is an email address| @comment 'name@email.com' ", "comment that is an email address", false, "name@email.com", "", "", false),
                Property.extractProperty("comment that is an email address| @comment 'name@email.com' "));

        assertProperty(new Property("comment without annotation but with 2 arobases| @admin and @user", "comment without annotation but with 2 arobases", false, "@admin and @user", "", "", false),
                Property.extractProperty("comment without annotation but with 2 arobases| @admin and @user"));

        // Annotations avec et sans majuscules

        assertProperty(new Property("REQUIRED|@REQUIRED", "REQUIRED", true, null, "", "", false),
                Property.extractProperty("REQUIRED|@REQUIRED"));

        assertProperty(new Property("Required|@Required", "Required", true, null, "", "", false),
                Property.extractProperty("Required|@Required"));

        // Multiple required et password autorisés

        assertProperty(new Property("multiple required and password|@required @required @password @password", "multiple required and password", true, null, "", "", true),
                Property.extractProperty("multiple required and password|@required @required @password @password"));

        // #313
        assertProperty(new Property("quoted comment containing escaped quotes| @comment 'Login pour l\\'authentification à l\\'api'", "quoted comment containing escaped quotes", false, "Login pour l'authentification à l'api", "", "", false),
                Property.extractProperty("quoted comment containing escaped quotes| @comment 'Login pour l\\'authentification à l\\'api'"));

        // #317
        assertProperty(new Property("quoted values that begins and ends with space| @comment \" a comment \" @default \" a default \" @pattern \" a pattern \" ", "quoted values that begins and ends with space", false, "a comment", " a default ", " a pattern ", false),
                Property.extractProperty("quoted values that begins and ends with space| @comment \" a comment \" @default \" a default \" @pattern \" a pattern \" "));

        // #320
        assertProperty(new Property("comment wrapped with simple quotes but containing double quotes|@comment 'exemple: \"Bonjour\"'", "comment wrapped with simple quotes but containing double quotes", false, "exemple: \"Bonjour\"", "", "", false),
                Property.extractProperty("comment wrapped with simple quotes but containing double quotes|@comment 'exemple: \"Bonjour\"'"));

        assertProperty(new Property("comment wrapped with double quotes but containing simple quotes|@comment \"exemple: 'Bonjour'\"", "comment wrapped with double quotes but containing simple quotes", false, "exemple: 'Bonjour'", "", "", false),
                Property.extractProperty("comment wrapped with double quotes but containing simple quotes|@comment \"exemple: 'Bonjour'\""));

        // #326
        assertProperty(new Property("prop|@comment Foo\tbar", "prop", false, "Foo", "", "", false),
                Property.extractProperty("prop|@comment Foo\tbar"));

        // #327
        assertProperty(new Property("passengerType.companion.list|@Default \"GG99AD\" @Comment \"Comma-separated list of passenger type (paxtype) to be considered as companion passengers.\"", "passengerType.companion.list", false, "Comma-separated list of passenger type (paxtype) to be considered as companion passengers.", "GG99AD", "", false),
                Property.extractProperty("passengerType.companion.list|@Default \"GG99AD\" @Comment \"Comma-separated list of passenger type (paxtype) to be considered as companion passengers.\""));
