static String extractValueBetweenQuotes(String value) {
        String result = null;
        if (value != null) {
            if (value.startsWith("\"")) {
                result = extractBetweenFirstAndNextUnescapedQuotes(value, "\"");
            } else if (value.startsWith("'")) {
                result = extractBetweenFirstAndNextUnescapedQuotes(value, "'");
                if (result != null) {
                    // #320
                    result = result.replaceAll("\\\"", "\\\\\"");
                }
            }
            if (result != null) {
                result = legacyEscape(result);
            }
        }
        return result;
    }

