static Predicate<TargetInfo> createTargetFilterPredicate(Set<Integer> mmsis, Set<Area> baseAreas, Set<Area> areas) {
        Predicate<TargetInfo> mmsiPredicate = null;
        if (mmsis != null && mmsis.size() > 0) {
            mmsiPredicate =  targetInfo -> mmsis.contains(targetInfo.getMmsi());
        }

        Predicate<TargetInfo> baseAreaPredicate = null;
        if (baseAreas != null && baseAreas.size() > 0) {
            baseAreaPredicate =  targetInfo -> baseAreas.stream().anyMatch(area -> targetInfo.getPosition() != null && area.contains(targetInfo.getPosition()));
        }

        Predicate<TargetInfo> areaPredicate = null;
        if (areas != null && areas.size() > 0) {
            areaPredicate =  targetInfo -> areas.stream().anyMatch(area -> targetInfo.getPosition() != null && area.contains(targetInfo.getPosition()));
        }

        Predicate<TargetInfo> resultingAreaPredicate = null;
        if(baseAreaPredicate != null && areaPredicate == null){
            resultingAreaPredicate = baseAreaPredicate;
        }else if (baseAreaPredicate != null && areaPredicate != null){
            resultingAreaPredicate = baseAreaPredicate.and(areaPredicate);
        }else{
            resultingAreaPredicate = areaPredicate;
        }

        if (mmsiPredicate == null && resultingAreaPredicate == null)
            return t -> true;
        else if (mmsiPredicate != null && resultingAreaPredicate == null)
            return mmsiPredicate;
        else if (mmsiPredicate == null && resultingAreaPredicate != null)
            return resultingAreaPredicate;
        else
            return mmsiPredicate.or(resultingAreaPredicate);
    }

@Test
    public void testCreateTargetFilterPredicate_baseAreaOnly() throws Exception {
        Predicate<TargetInfo> predicate = TrackResource.createTargetFilterPredicate(
                null,
                Sets.newHashSet(
                        BoundingBox.create(Position.create(55.0, 10.0), Position.create(56.2, 12), CoordinateSystem.CARTESIAN)
                ),
                null
        );

        // Test a target not matching any mmsi or area
        TargetInfo targetInfo = Mockito.mock(TargetInfo.class);
        when(targetInfo.getPosition()).thenReturn(Position.create(54.9, 9.9));
        assertFalse(predicate.test(targetInfo));

        // Test a target matching an mmsi but not an area
        targetInfo = Mockito.mock(TargetInfo.class);
        when(targetInfo.getPosition()).thenReturn(Position.create(55.9, 10.9));
        assertTrue(predicate.test(targetInfo));
   }

public static String getCommand(String string){
    	int index = string.indexOf("invocabot");

    	// If "invocabot" is not in string.
    	if (index == -1) return null;

    	// If "invocabot" is last word in string.
    	String words[] = string.split(" ");
    	if (words[words.length - 1].equals("invocabot"))
    		return "";

    	// If string is just "invocabot".
    	if (string.equalsIgnoreCase("invocabot")) return "";

    	String output;
    	// Check if "invocabot" exists twice.
    	int endIndex = string.indexOf("invocabot", index + 1);
    	int truncationIndex = index + "invocabot".length() + 1;

    	// If "invocabot" exists once, truncate until end of string.
    	if (endIndex == -1) {
    		output = string.substring(truncationIndex);
    	} 
    	// If "invocabot" exists more than once, truncate at the last word before the next "invocabot".
    	else {
    		output = string.substring(truncationIndex, endIndex - 1);
    	}

    	return output;
    }

