@Override
    public Collection<InetAddress> resolve(String host) {
        readLock.lock();
        try {
            // attempt to resolve the host using all resolvers. returns the results from the first successful resolution.
            return resolvers.stream()
                    .map(resolver -> resolver.resolve(host))
                    .filter(results -> !results.isEmpty())
                    .findFirst()
                    .orElse(emptyList());

            // no resolvers returned results
        } finally {
            readLock.unlock();
        }
    }

@Test
    public void testResolveReturnsFirstResults() {
        AdvancedHostResolver firstResolver = mock(AdvancedHostResolver.class);
        AdvancedHostResolver secondResolver = mock(AdvancedHostResolver.class);
        ChainedHostResolver chainResolver = new ChainedHostResolver(ImmutableList.of(firstResolver, secondResolver));

        when(firstResolver.resolve("1.1.1.1")).thenReturn(TestConstants.addressOnesList);
        when(secondResolver.resolve("1.1.1.1")).thenReturn(Collections.<InetAddress>emptyList());

        Collection<InetAddress> results = chainResolver.resolve("1.1.1.1");
        assertNotNull("Resolver should not return null results", results);
        assertThat("Expected resolver to return a result", results, not(empty()));
        Assert.assertEquals("Resolver returned unexpected result", TestConstants.addressOnes, Iterables.get(results, 0));

        verify(secondResolver, never()).resolve("1.1.1.1");

        reset(firstResolver);
        reset(secondResolver);

        when(firstResolver.resolve("2.2.2.2")).thenReturn(Collections.<InetAddress>emptyList());
        when(secondResolver.resolve("2.2.2.2")).thenReturn(TestConstants.addressTwosList);

        results = chainResolver.resolve("2.2.2.2");
        assertNotNull("Resolver should not return null results", results);
        assertThat("Expected resolver to return a result", results, not(empty()));
        Assert.assertEquals("Resolver returned unexpected result", TestConstants.addressTwos, Iterables.get(results, 0));

        verify(firstResolver).resolve("2.2.2.2");
        verify(secondResolver).resolve("2.2.2.2");
    }

@Override
	public OrgData process(OrgData input) throws Exception {
		ServiceContext context = getServiceContext();
		List<ValidationError> errors = Lists.newArrayList();
		if (StringUtils.isBlank(input.getOrg().getOrgTypeCode())) {
			ValidationError error = new ValidationError("orgTypeCode", "Organization Type",
					"The organization type is required.");
			errors.add(error);
		}
		if (StringUtils.isBlank(input.getOrg().getParentOrgCode())) {
			ValidationError error = new ValidationError("parentOrgCode", "Parent Organization",
					"The parent organization is required.");
			errors.add(error);
		}

		if (!errors.isEmpty()) {
			ValidationServiceException e = new ValidationServiceException(new FaultInfo());
			e.getFaultInfo().getAttributeErrors().addAll(errors);
			throw e;
		}

		Org match = organizationService.getMatch(context, input.getOrg());

		if (match != null) {
			if (!match.getParentOrgLocalCode().equals(input.getOrg().getParentOrgLocalCode())) {
				String msg = messageSource.getMessage("validation.org.parent.not.same", new Object[] {
						input.getOrg().getParentOrgLocalCode(), match.getParentOrgLocalCode() }, Locale.getDefault());
				errors.add(new ValidationError("parentOrgCode", "Parent Organization", msg));
				ValidationServiceException e = new ValidationServiceException(new FaultInfo());
