		assertThat(wrapper.hasFeature(AnimatorWrapper.START | AnimatorWrapper.PAUSE | AnimatorWrapper.RESUME | AnimatorWrapper.CANCEL), is(false));
		wrapper.requestFeatures(AnimatorWrapper.CANCEL);
