public void insert(final RelayVertex relayVertex, final IREdge edgeToStreamize) {
    assertNonExistence(relayVertex);
    assertNonControlEdge(edgeToStreamize);

    // Create a completely new DAG with the vertex inserted.
    final DAGBuilder<IRVertex, IREdge> builder = new DAGBuilder<>();

    // Integrity check
    if (edgeToStreamize.getPropertyValue(MessageIdEdgeProperty.class).isPresent()
      && !edgeToStreamize.getPropertyValue(MessageIdEdgeProperty.class).get().isEmpty()) {
      throw new CompileTimeOptimizationException(edgeToStreamize.getId() + " has a MessageId, and cannot be removed");
    }

    // RelayVertex should not be inserted before SplitterVertex.
    if (edgeToStreamize.getDst() instanceof TaskSizeSplitterVertex) {
      return;
    }

    // Insert the vertex.
    final IRVertex vertexToInsert = wrapSamplingVertexIfNeeded(relayVertex, edgeToStreamize.getSrc());
    builder.addVertex(vertexToInsert);
    edgeToStreamize.getSrc().getPropertyValue(ParallelismProperty.class)
      .ifPresent(p -> vertexToInsert.setProperty(ParallelismProperty.of(p)));

    // Build the new DAG to reflect the new topology.
    modifiedDAG.topologicalDo(v -> {
      builder.addVertex(v); // None of the existing vertices are deleted.

      for (final IREdge edge : modifiedDAG.getIncomingEdgesOf(v)) {
        if (edge.equals(edgeToStreamize)) {
          // MATCH!

          // Edge to the relayVertex
          final IREdge toSV = new IREdge(
            edgeToStreamize.getPropertyValue(CommunicationPatternProperty.class).get(),
            edgeToStreamize.getSrc(),
            vertexToInsert);
          edgeToStreamize.copyExecutionPropertiesTo(toSV);

          // Edge from the relayVertex.
          final IREdge fromSV = new IREdge(CommunicationPatternProperty.Value.ONE_TO_ONE, vertexToInsert, v);
          fromSV.setProperty(EncoderProperty.of(edgeToStreamize.getPropertyValue(EncoderProperty.class).get()));
          fromSV.setProperty(DecoderProperty.of(edgeToStreamize.getPropertyValue(DecoderProperty.class).get()));

          // Annotations for efficient data transfers - toSV
          toSV.setPropertyPermanently(DecoderProperty.of(BytesDecoderFactory.of()));
          toSV.setPropertyPermanently(CompressionProperty.of(CompressionProperty.Value.LZ4));
          toSV.setPropertyPermanently(DecompressionProperty.of(CompressionProperty.Value.NONE));

          // Annotations for efficient data transfers - fromSV
          fromSV.setPropertyPermanently(EncoderProperty.of(BytesEncoderFactory.of()));
          fromSV.setPropertyPermanently(CompressionProperty.of(CompressionProperty.Value.NONE));
          fromSV.setPropertyPermanently(DecompressionProperty.of(CompressionProperty.Value.LZ4));
          fromSV.setPropertyPermanently(PartitionerProperty.of(PartitionerProperty.Type.DEDICATED_KEY_PER_ELEMENT));

          // Track the new edges.
          builder.connectVertices(toSV);
          builder.connectVertices(fromSV);
        } else {
          // NO MATCH, so simply connect vertices as before.
          builder.connectVertices(edge);
        }
      }
    });

    if (edgeToStreamize.getSrc() instanceof RelayVertex) {
      streamVertexToOriginalEdge.put(relayVertex, streamVertexToOriginalEdge.get(edgeToStreamize.getSrc()));
    } else if (edgeToStreamize.getDst() instanceof RelayVertex) {
      streamVertexToOriginalEdge.put(relayVertex, streamVertexToOriginalEdge.get(edgeToStreamize.getDst()));
    } else {
      streamVertexToOriginalEdge.put(relayVertex, edgeToStreamize);
    }
    modifiedDAG = builder.build(); // update the DAG.
  }

@Test
  public void testThousandRandomConfigurations() {
    // Thousand random configurations (some duplicate configurations possible)
    final int thousandConfigs = 1000;
    for (int i = 0; i < thousandConfigs; i++) {
      //LOG.info("Doing {}", i);
      final int numOfTotalMethods = 13;
      final int methodIndex = random.nextInt(numOfTotalMethods);
      switch (methodIndex) {
        // Annotation methods
        // For simplicity, we test only the EPs for which all possible values are valid.
        case 0:
          selectRandomVertex().setProperty(randomCSP());
          break;
        case 1:
          selectRandomVertex().setProperty(randomRLP());
          break;
        case 2:
          selectRandomVertex().setProperty(randomRPP());
          break;
        case 3:
          selectRandomVertex().setProperty(randomRSP());
          break;
        case 4:
          selectRandomEdge().setProperty(randomDFP());
          break;
        case 5:
          selectRandomEdge().setProperty(randomDPP());
          break;
        case 6:
          selectRandomEdge().setProperty(randomDSP());
          break;

        // Reshaping methods
        case 7:
          final RelayVertex relayVertex = new RelayVertex();
          final IREdge edgeToStreamize = selectRandomEdge();
          if (!(edgeToStreamize.getPropertyValue(MessageIdEdgeProperty.class).isPresent()
            && !edgeToStreamize.getPropertyValue(MessageIdEdgeProperty.class).get().isEmpty())) {
            irdag.insert(relayVertex, edgeToStreamize);
          }
          break;
        case 8:
          insertNewTriggerVertex(irdag, selectRandomEdge());
          break;
        case 9:
          final IRVertex vertexToSample = selectRandomNonUtilityVertex();
          final SamplingVertex samplingVertex = new SamplingVertex(vertexToSample, 0.1f);
          irdag.insert(Sets.newHashSet(samplingVertex), Sets.newHashSet(vertexToSample));
          break;
        case 10:
          insertNewSignalVertex(irdag, selectRandomEdge());
          break;
        case 11:
          insertNewSplitterVertex(irdag, selectRandomEdge());
          break;
        case 12:
          // the last index must be (numOfTotalMethods - 1)
          selectRandomUtilityVertex().ifPresent(irdag::delete);
          break;
        default:
          throw new IllegalStateException(String.valueOf(methodIndex));
      }

      if (i % (thousandConfigs / 10) == 0) {
        // Uncomment to visualize 10 DAG snapshots
        // irdag.storeJSON("test_10_snapshots", String.valueOf(i), "test");
      }

      if (methodIndex >= 7) {
        // Uncomment to visualize DAG snapshots after reshaping (insert, delete)
        //irdag.storeJSON("test_reshaping_snapshots", i + "(methodIndex_" + methodIndex + ")", "test");
      }

      // Must always pass
      mustPass();
    }
  }

public String serializeStatistics(Statistics statistics) {
        JsonObjectBuilder stats = Json.createObjectBuilder();
        stats.add("pipelineName", statistics.getPipelineName());
        final String handlerName = statistics.getRejectedExecutionHandlerName();
        if (handlerName != null) {
            stats.add("rejectedExecutionHandlerName", handlerName);
        }
        stats.add("activeThreadCount", statistics.getActiveThreadCount());
        stats.add("completedTaskCount", statistics.getCompletedTaskCount());
        stats.add("corePoolSize", statistics.getCorePoolSize());
        stats.add("currentThreadPoolSize", statistics.getCurrentThreadPoolSize());
        stats.add("largestThreadPoolSize", statistics.getLargestThreadPoolSize());
        stats.add("maximumPoolSize", statistics.getMaximumPoolSize());
        stats.add("rejectedTasks", statistics.getRejectedTasks());
        stats.add("remainingQueueCapacity", statistics.getRemainingQueueCapacity());
        stats.add("minQueueCapacity", statistics.getMinQueueCapacity());
        stats.add("totalNumberOfTasks", statistics.getTotalNumberOfTasks());
        StringWriter writer = new StringWriter();
        try (JsonWriter outputWriter = Json.createWriter(writer)) {
            outputWriter.writeObject(stats.build());
        }
        return writer.toString();
    }

