public ObjectReader skipValue() {

    if (ARRAY == valueType || OBJECT == valueType) {
      int balance = 0;
      do {
        if (ARRAY == valueType) {
          beginArray();
          balance++;
        } else if (OBJECT == valueType) {
          beginObject();
          balance++;
        }

        while (hasNext()) {
          next();
          skipValue();
        }

        JsonType type = _ctx.peek();
        if (JsonType.ARRAY == type) {
          endArray();
          balance--;
        } else if (JsonType.OBJECT == type) {
          endObject();
          balance--;
        }
      } while (balance > 0);
    }

    return this;
  }

@Test
  public void testSkipValue() throws IOException {
    String src = "{\"a\":[], \"b\":{}, \"c\": [{\"c\":null, \"d\":121212.02}, 4, null], \"e\":1234, \"end\":\"the end\"}";
    JsonReader reader = createReader(src);

    reader.beginObject();

    reader.next();
    reader.skipValue();

    assertTrue(reader.hasNext());
    reader.next();
    assertEquals(reader.name(), "b");
    reader.skipValue();

    assertTrue(reader.hasNext());
    reader.next();
    assertEquals(reader.name(), "c");
    reader.skipValue();

    assertTrue(reader.hasNext());
    reader.next();
    assertEquals(reader.name(), "e");
    reader.skipValue();

    assertTrue(reader.hasNext());
    reader.next();
    assertEquals(reader.name(), "end");

    reader.endObject();
    reader.close();
  }

