public static int kmp(ByteBuffer buf, byte[] sought) {
        if (sought == null || sought.length == 0) {
            return -1;
        }

        if (sought.length == 1) {
            int i = buf.position();
            while (buf.hasRemaining()) {
                if (buf.get(i) == sought[0]) {
                    return i;
                }
                i += 1;
            }
            return -1;
        }

        int i = 0;
        int[] t = kmpTable(sought);

        int m = buf.position();
        while (m + i < buf.limit()) {
            if (sought[i] == buf.get(m + i)) {
                i++;
                if (i == sought.length) return m;
            } else {
                m = m + i - t[i];
                if (i > 0)
                    i = t[i];
            }
        }
        return -1;
    }

