static int nextPowerOfTwo(int value) {
        if (value == 0) {
            return 1;
        }
        value--;
        value |= value >>> 1;
        value |= value >>> 2;
        value |= value >>> 4;
        value |= value >>> 8;
        value |= value >>> 16;
        return value + 1;
    }

@Test
    public void testNextPowerOfTwo() {
        assertEquals(1, Bag.nextPowerOfTwo(0));
        assertEquals(1, Bag.nextPowerOfTwo(1));
        assertEquals(2, Bag.nextPowerOfTwo(2));
        assertEquals(4, Bag.nextPowerOfTwo(3));
        assertEquals(1 << 31, Bag.nextPowerOfTwo((1 << 30) + 1));
    }

@Override
    public void clear() {
        int[] buffer = this.buffer;
        for (int i = 0, n = buffer.length; i < n; ++i)
            buffer[i] = 0;
    }

@Test
    public void testClear() {
        IntBag bag;

        bag = new IntBag();
        bag.set(0, 1);
        bag.set(1, 1);
        bag.set(63, 1);
        bag.clear();
        assertEquals((Integer) 0, (Integer) bag.get(0));
        assertEquals((Integer) 0, (Integer) bag.get(1));
        assertEquals((Integer) 0, (Integer) bag.get(63));
        assertEquals(64, bag.buffer.length);

        Mask mask = new Mask();
        bag = new IntBag();
        bag.set(0, 1);
        bag.set(1, 1);
        bag.set(63, 1);
        mask.set(63);
        mask.set(0);
        bag.clear(mask);
        assertEquals((Integer) 0, (Integer) bag.get(0));
        assertNotEquals((Integer) 0, (Integer) bag.get(1));
        assertEquals((Integer) 0, (Integer) bag.get(63));
        mask.set(1);
        mask.set(457);
        bag.clear(mask);
        assertEquals((Integer) 0, (Integer) bag.get(0));
        assertEquals((Integer) 0, (Integer) bag.get(1));
        assertEquals((Integer) 0, (Integer) bag.get(63));
        assertEquals(64, bag.buffer.length);
    }

