public void deleteSample(Sample sample, Long userIdMakingChange) {
    Database db = dbp.get();

    // Insert the history row first, so it will fail (non-unique sample_id + update_sequence)
    // if someone else modified the row. This is an optimistic locking strategy.
    int newUpdateSequence = sample.getUpdateSequence() + 1;
    Date newUpdateTime = db.nowPerApp();
    db.toInsert("insert into sample_history (sample_id, sample_name, update_sequence, update_time, update_user_id,"
        + " is_deleted) values (?,?,?,?,?,'Y')")
        .argLong(sample.getSampleId())
        .argString(sample.getName())
        .argInteger(newUpdateSequence)
        .argDate(newUpdateTime)
        .argLong(userIdMakingChange)
        .insert(1);

    db.toDelete("delete from sample where sample_id=?")
        .argLong(sample.getSampleId())
        .update(1);

    // Make sure the object in memory matches the database.
    sample.setUpdateSequence(newUpdateSequence);
    sample.setUpdateTime(newUpdateTime);
  }

@Test
  public void testDelete() throws Exception {
    Date before = new Date(now.getTime() - 5000);

    Sample sample = new Sample();
    sample.setSampleId(100L);
    sample.setName("Foo");
    sample.setUpdateSequence(13);
    sample.setUpdateTime(before);
    sampleDao.deleteSample(sample, 23L);

    // Verify object in memory is updated properly
    assertEquals(new Long(100L), sample.getSampleId());
    assertEquals("Foo", sample.getName());
    assertEquals(new Integer(14), sample.getUpdateSequence());
    assertEquals(now, sample.getUpdateTime());

    // Verify database queries against golden copies
    verify(db).update(anyString(), eq("delete from sample where sample_id=100"));
    verify(db).insert(eq("insert into sample_history (sample_id, sample_name, update_sequence, update_time, update_user_id, is_deleted) values (?,?,?,?,?,'Y')"), anyString());
    verifyNoMoreInteractions(db);
  }

@Override
    public MatchingPlatform searchForMatchingPlatform(String applicationInstanceUriId) throws SOAException {
        logger.debug("received applicationInstanceUriId: " + applicationInstanceUriId);

        logger.debug("call applicationProfilesRepository.getApplicationInstance(applicationInstanceUriId)");

        ApplicationInstance applicationInstance;
        try {
            applicationInstance = applicationProfilesRepository.getApplicationInstance(applicationInstanceUriId);
        } catch (RepositoryException ex) {
            throw new SOAException(Response.Status.INTERNAL_SERVER_ERROR, ex.getMessage());
        }

        logger.debug("retrived applicationInstance: " + applicationInstance);

        Map<PaaSInstance,Float> searchResultList = searchAndDiscoveryInterfaces.searchForMatchingPlatform(applicationInstance);

        Map<PaaSInstance,SlaTemplate> slatemplates = new HashMap<PaaSInstance,SlaTemplate>();

        Iterator<PaaSInstance> iterator = searchResultList.keySet().iterator();

        while (iterator.hasNext()) {
            PaaSInstance paasInstance = iterator.next();
            SlaTemplate slaTemplate = slamodule.startNegotiation(applicationInstance, paasInstance);
            slatemplates.put(paasInstance, slaTemplate);
        }

        //To instantiate        
        MatchingPlatform negotiatedSearchResults = new MatchingPlatform();
        negotiatedSearchResults.setRankedListPaaSInstances(searchResultList);
        //negotiatedSearchResults.setListSlaContract(slatemplates);
        negotiatedSearchResults.setListSlaTemplates(slatemplates);

        return negotiatedSearchResults;
    }

