public static String cleanFilename(String fileName, String defaultName) {
        if (fileName == null || "".equals(fileName)) {
            fileName = defaultName;
        } else {
            fileName = fileName.replaceAll("\\W", "");
            fileName = (fileName.length() > 0) ? fileName : defaultName;
        }
        return fileName;
    }

