        testTensor1.setEntry(0.5d, 0, 0, 0);
        testTensor1.setEntry(1.0d, 0, 0, 0);
        testTensor1.setEntry(2.0d, 1, 0, 1);
        testTensor1.setEntry(3.0d, 0, 2, 2);
        testTensor1.setEntry(3.0d, 1, 2, 2);
        testTensor1.setEntry(4.0d, 3, 3, 2);
