public static void synchronizeFolder(final File tomeeHome, final String src, final String dir) {
        if (src != null && !src.isEmpty()) {
            final File confSrc = new File(src);
            if (confSrc.exists()) {
                final File conf = new File(tomeeHome, dir);
                final Collection<File> files = org.apache.openejb.loader.Files.collect(confSrc, TrueFilter.INSTANCE);
                files.remove(confSrc);
                for (final File f : files) {
                    if (f.equals(confSrc) || f.getName().startsWith(".")) {
                        continue;
                    }

                    final String relativize = relativize(f, confSrc);
                    if (f.isDirectory()) {
                        final String path = dir + '/' + relativize;
                        Files.mkdir(new File(tomeeHome, path));
                        synchronizeFolder(tomeeHome, f.getAbsolutePath(), path);
                    } else {
                        try {
                            final File to = new File(conf, relativize);
                            Files.mkdir(to.getParentFile());
                            org.apache.openejb.loader.IO.copy(f, to);
                        } catch (final Exception e) {
                            LOGGER.log(Level.WARNING, "Ignoring copy of " + f.getAbsolutePath(), e);
                        }
                    }
                }
            } else {
                LOGGER.warning("Can't find " + confSrc.getAbsolutePath());
            }
        }
    }

@Test
    public void synchronizeFolders() throws IOException {
        final File root = new File("target/SetupTest/synchronizeFolders/");
        Files.delete(root); // clean up
        final File source = org.apache.openejb.loader.Files.mkdirs(new File(root, "conf"));
        for (int i = 0; i < 10; i++) {
            final FileWriter w = new FileWriter(new File(source, "file-" + i));
            w.write(Integer.toString(i));
            w.close();
        }

        Setup.synchronizeFolder(root,new File(root, "conf").getAbsolutePath(), "conf-copy");
        final File target = new File(root, "conf-copy");
        assertEquals(10, target.listFiles().length);

        // sub folders
        final File subFolder = org.apache.openejb.loader.Files.mkdirs(new File(source, "conf.d"));
        for (int i = 0; i < 10; i++) {
            final FileWriter w = new FileWriter(new File(subFolder, "file-" + i));
            w.write(Integer.toString(i));
            w.close();
        }

        Setup.synchronizeFolder(root,new File(root, "conf").getAbsolutePath(), "conf-copy2");
        assertEquals(11, new File(root, "conf-copy2").listFiles().length);
        assertEquals(10, new File(root, "conf-copy2/conf.d").listFiles().length);
    }

