public List<String> getLastLines(int lastSize) {
        int size = 0;
        int i = lines.size() - 1;
        while (size < lastSize && i >= 0) {
            size += lines.get(i).length();
            i--;
        }
        return lines.subList(i + 2, lines.size());
    }

