public boolean hasTrailing(final String text) {
		List<String> textList = Arrays.asList(text.split("\\s"));
		Collections.reverse(textList);

		for (String word : textList) {
			word = normalize(word);
			if (stopwords.contains(word)) {
				return true;
			}
			return false;
		}

		return false;
	}

