        assertEquals("HTTP/1.1 200 OK\r\n" +
            "Content-Type:" + contentType + "\r\n" +
            "Content-Length:" + contentLength + "\r\n" +
            "X-Custom-Header:value\r\n" +
            "\r\n", result);

        verifyInteractions(response);
    }

