public boolean isMatch(@NonNull String url) {
        for (String r : regex) {
            String trimUrl = url.split("\\?")[0];
            if (!trimUrl.endsWith("/")) {
                trimUrl = trimUrl + "/";
            }
            if (trimUrl.matches(r)) {
                return true;
            }
        }
        return false;
    }

