	}

public static int parseInt(ByteBuffer buf, byte delimiter) {
    int sign = 1;
    if (buf.get(buf.position()) == (byte)'-') {
      buf.get();
      sign = -1;
    }
    int result = 0;
    for (;;) {
      byte ch = buf.get();
      if (ch == delimiter) {
        break;
      }
      result *= 10;
      result += (byte)ch - (byte)'0';
    }
    return sign * result;
  }

