public AppendRequest buildRequest() {
        return new AppendRequest(
            reqId,
            clientHighWaterMark,
            compileLockRequest(writeLocks),
            compileLockRequest(readLocks),
            compileLockRequest(appendLocks),
            header,
            data,
            Utils.checksum(data)
        );
    }

@Test
    public void test() {
        MockContext context = MockContext.builder()
            .data("good transaction")
            .writeLocks(1, 2, 3)
            .readLocks(4, 5, 6)
            .appendLocks(7, 8, 9)
            .build();

        TransactionBuilderImpl builder = new TransactionBuilderImpl(new ReqId(111, 222, 333, 444), 999);

        context.execute(builder);

        AppendRequest request = builder.buildRequest();

        assertEquals(new ReqId(111, 222, 333, 444), request.reqId);
        assertEquals(999, request.clientHighWaterMark);

        assertEquals("good transaction", new String(request.data, StandardCharsets.UTF_8));

        int[] expectedWriteLockRequest = new int[]{
            MockContext.makeLock(1).hashCode(),
            MockContext.makeLock(2).hashCode(),
            MockContext.makeLock(3).hashCode()
        };

        int[] expectedReadLockRequest = new int[]{
            MockContext.makeLock(4).hashCode(),
            MockContext.makeLock(5).hashCode(),
            MockContext.makeLock(6).hashCode()
        };

        int[] expectedAppendLockRequest = new int[]{
            MockContext.makeLock(7).hashCode(),
            MockContext.makeLock(8).hashCode(),
            MockContext.makeLock(9).hashCode()
        };

        assertArrayEquals(expectedWriteLockRequest, request.writeLockRequest);
        assertArrayEquals(expectedReadLockRequest, request.readLockRequest);
        assertArrayEquals(expectedAppendLockRequest, request.appendLockRequest);
    }

public PushNotificationFuture<SimpleApnsPushNotification, PushNotificationResponse<SimpleApnsPushNotification>> sendPushNotificationAsync(final String pushtoken) {

        LOGGER.debug("Sending Push notification for key: {}", pushtoken);

        final ApnsPayloadBuilder payloadBuilder = new ApnsPayloadBuilder();
        payloadBuilder.setAlertBody(EMPTY_PUSH_JSON_STRING);

        final String payload = payloadBuilder.buildWithDefaultMaximumLength();
        final String token = TokenUtil.sanitizeTokenString(pushtoken);
        Assert.state(!this.topics.isEmpty(), "APNS topic is required for sending a push notification");
        String topic = null;
        if (!this.topics.isEmpty()) {
            topic = this.topics.iterator().next();
            if (this.topics.size() > 1) {
                LOGGER.warn("Multiple APNS topics detected, using {} (first value out of {} available) for sending a push notification", topic, this.topics.size());
            }
        }
        SimpleApnsPushNotification pushNotification = new SimpleApnsPushNotification(token, topic, payload);
        LOGGER.debug("Send Push notification for key: {}", pushtoken);
        return client.sendNotification(pushNotification);
    }

