public static boolean bboxIsValid( String bbox )
    {
        if ( bbox == null || bbox.trim().isEmpty() )
        {
            return false;
        }

        Matcher matcher = BBOX_PATTERN.matcher( bbox );

        if ( !matcher.matches() )
        {
            return false;
        }

        double minLng = Double.parseDouble( matcher.group( 1 ) );
        double minLat = Double.parseDouble( matcher.group( 4 ) );
        double maxLng = Double.parseDouble( matcher.group( 7 ) );
        double maxLat = Double.parseDouble( matcher.group( 10 ) );

        if ( minLng < -180d || minLng > 180d || maxLng < -180d || maxLng > 180d )
        {
            return false;
        }

        if ( minLat < -90d || minLat > 90d || maxLat < -90d || maxLat > 90d )
        {
            return false;
        }

        return true;
    }

@Test
    public void testBboxIsValid()
    {
        assertTrue( bboxIsValid( "-13.2682125,7.3721619,-10.4261178,9.904012" ) );
        assertTrue( bboxIsValid( "12.26821,-23.3721,13.4261,-21.904" ) );
        assertTrue( bboxIsValid( "4,-23.37,5,-24.904" ) );
        assertTrue( bboxIsValid( "2.23, -23.37, 5.22, -24.90" ) );
        assertTrue( bboxIsValid( "-179.234,-89.342,178.323,88.135" ) );

        assertFalse( bboxIsValid( "[12.23,14.41,34.12,12.45]" ) );
        assertFalse( bboxIsValid( "22,23,14,41,34,11,11,41" ) );
        assertFalse( bboxIsValid( "22,23.14,41.34,11.11,41" ) );
        assertFalse( bboxIsValid( "-181.234,-89.342,178.323,88.135" ) );
        assertFalse( bboxIsValid( "-179.234,-92.342,178.323,88.135" ) );
        assertFalse( bboxIsValid( "-179.234,-89.342,185.323,88.135" ) );
        assertFalse( bboxIsValid( "-179.234,-89.342,178.323,94.135" ) );
    }

public static List<BaseDimensionalItemObject> slice( final WebOptions options,
        List<BaseDimensionalItemObject> dimensionalItems )
    {
        state( options.getPage() > 0, "Current page must be greater than zero." );
        state( options.getPageSize() > 0, "Page size must be greater than zero." );

        if ( options.hasPaging() && isNotEmpty( dimensionalItems ) )
        {
            // Pagination input
            final int currentPage = options.getPage();
            final int totalOfElements = dimensionalItems.size();
            final int maxElementsPerPage = options.getPageSize();

            final Pager pager = new Pager( currentPage, totalOfElements, maxElementsPerPage );

            final int currentElementIndex = pager.getOffset();
            final boolean hasMorePages = (totalOfElements - currentElementIndex) > pager.getPageSize();

            if ( hasMorePages )
            {
                final int nextElementsWindow = pager.getPageSize() * pager.getPage();
                dimensionalItems = dimensionalItems.subList( currentElementIndex, nextElementsWindow );
            }
            else
            {
                // This is the last page
                dimensionalItems = dimensionalItems.subList( pager.getOffset(), totalOfElements );
            }
        }

        return dimensionalItems;
    }

