        .isPrimitiveType("void");
    paramsChecker = methodsChecker.hasParameters("a", "b");
    paramsChecker.whereFirst().hasType().isPrimitiveType("int");
    paramsChecker.andNext().hasType().isPrimitiveType("int");

    // check m4;
