public CompletionStage<T> doOrGet(final Supplier<CompletionStage<T>> action) {
    CompletableFuture<T> newFuture;
    do {
      final CompletionStage<T> oldFuture = this.current.get();
      if (oldFuture != null) {
        return oldFuture;
      }
    } while (!this.current.compareAndSet(null, newFuture = new CompletableFuture<>()));

    final CompletableFuture<T> finalRef = newFuture;
    return action
        .get()
        .whenComplete(
            (t, ex) -> {
              this.current.set(null);
              if (ex != null) {
                finalRef.completeExceptionally(ex);
              } else {
                finalRef.complete(t);
              }
            });
  }

@Test
  public void testNullify() {
    final AsyncFunnel<Integer> c = new AsyncFunnel<>();
    for (int k = 0; k < 5; k++) {
      final int finalK = k;
      final CompletionStage<Integer> second = c.doOrGet(() -> {
        final CompletableFuture<Integer> result = new CompletableFuture<>();
        if (finalK % 2 == 0) {
          result.complete(finalK);
        } else {
          result.completeExceptionally(new TestException(finalK));
        }
        return result;
      });
      int j;
      try {
        j = second.toCompletableFuture().join();
      } catch (final CompletionException e) {
        j = ((TestException) e.getCause()).get();
      }
      Assert.assertEquals(j, k);
    }
  }

