        assertFalse(v.isInSphere(v.copy().addX(5.0), -4.0));
        assertTrue(v.isInSphere(v.copy().addX(5.0), -5.0));
        assertTrue(v.isInSphere(v.copy().addX(5.0), -6.0));
    }

