public static NumberList create(Map<String, Object> numbers) {
        LinkedHashMap<String, Long> values = new LinkedHashMap<String, Long>(numbers.size());
        for (Entry<String, Object> k : numbers.entrySet()) {
            Object v = k.getValue();
            if (v instanceof Number) {
                values.put(k.getKey(), ((Number) v).longValue());
            } else {
                values.put(k.getKey(), Long.valueOf(String.valueOf(v)));
            }
        }

        return new NumberList(values);
    }

@Test
    public void testCreate() {
        NumberList nl = NumberList.create(values);
        System.out.println(nl);
        assertEquals(Long.valueOf(10), nl.get("0"));
        assertEquals(Long.valueOf(50), nl.get("25"));
        assertEquals(Long.valueOf(100), nl.get("50"));
        assertEquals(Long.valueOf(250), nl.get("75"));
        assertEquals(Long.valueOf(500), nl.get("99"));
    }

public Observable<EurekaInstance> getInstanceEvents(String appName) {
        return eurekaClient.forApplication(appName)
                .map(new Func1<ChangeNotification<InstanceInfo>, EurekaInstance>() {
                    @Override
                    public EurekaInstance call(ChangeNotification<InstanceInfo> notification) {
                        try {
                            return EurekaInstance.from(notification);
                        } catch (Exception e) {
                            logger.warn("Error parsing notification from eurekaClient {}", notification);
                        }
                        return null;
                    }
                }).filter(new Func1<EurekaInstance, Boolean>() {
                    @Override
                    public Boolean call(EurekaInstance eurekaInstance) {
                        return eurekaInstance != null;
                    }
                });
    }

@Test
    public void testMultipleInstances() {
        EurekaInstance a = EurekaInstance.from(new ChangeNotification<>(ChangeNotification.Kind.Add, upInstanceInfo1));
        EurekaInstance b = EurekaInstance.from(new ChangeNotification<>(ChangeNotification.Kind.Delete, upInstanceInfo1));
        EurekaInstance c = EurekaInstance.from(new ChangeNotification<>(ChangeNotification.Kind.Add, upInstanceInfo2));

        Assert.assertEquals(EurekaInstance.Status.UP, a.getStatus());
        Assert.assertEquals(EurekaInstance.Status.DOWN, b.getStatus());
        Assert.assertEquals(EurekaInstance.Status.UP, c.getStatus());

        TestSubscriber<EurekaInstance> ts = new TestSubscriber<>();

        testEurekaClient.register(upInstanceInfo1);
        testEurekaClient.unregister(upInstanceInfo1);
        testEurekaClient.register(upInstanceInfo2);

        eurekaInstanceDiscovery.getInstanceEvents("API").subscribe(ts);

        ts.assertReceivedOnNext(Arrays.asList(a, b, c));
    }

