protected AggregatedJudgement getAggregatedJudgment(
      Double finalCanaryScore, Double marginalThreshold, Double passThreshold) {
    boolean didPassThresholds;
    String msg;
    if (marginalThreshold == null && passThreshold == null) {
      didPassThresholds = true;
      msg = "No score thresholds were specified.";
    } else if (marginalThreshold != null && finalCanaryScore <= marginalThreshold) {
      didPassThresholds = false;
      msg =
          String.format(
              "Final canary score %s is not above the marginal score threshold.", finalCanaryScore);
    } else if (passThreshold == null) {
      didPassThresholds = true;
      msg = "No pass score threshold was specified.";
    } else if (finalCanaryScore < passThreshold) {
      didPassThresholds = false;
      msg =
          String.format(
              "Final canary score %s is below the pass score threshold.", finalCanaryScore);
    } else {
      didPassThresholds = true;
      msg =
          String.format(
              "Final canary score %s met or exceeded the pass score threshold.", finalCanaryScore);
    }
    return new AggregatedJudgement(didPassThresholds, msg);
  }

