    public void testIf3() {
        Expression t = Parser.parse("$if3(%artist%, %title%, %albumArtist%, unknown)");

        s.getTrackData().setTagFieldValues(FieldKey.ARTIST, "artist");
        assertEquals("artist", t.eval(s));
