public static byte[] appendCRC(final byte[] bytes) {
        final int len = bytes.length;
        final byte[] outputBytes = new byte[len + 1];

        System.arraycopy(bytes, 0, outputBytes, 0, len);
        outputBytes[len] = computeCRC(bytes);

        return outputBytes;
    }

