        "access-control-allow-origin", "http://foobar.com",
        "access-control-allow-methods", "POST",
        "access-control-allow-headers", "Content-Type, Content-Encoding"
      )
    );
  }

public static int read(final LexerStream in_stream) throws IOException, LexerException
    {
        int next = in_stream.peek();
        if (next == -1) {
            throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Unexpected end of input stream when inside escape sequence");
        }
        if (next != '\\') {
            throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Not an escape sequence");
        }

        int result; // int instead of 'char' to support higher-value utf-32

        in_stream.read(); // backslash '\' char

        // Consume next, as char after escape will always lex as part of escape
        // or result in error
        int cur = in_stream.read();
        next = in_stream.peek();
        switch (cur)
        {
            case '\'':
                result = '\'';
                break;
            case '\"':
                result = '\"';
                break;
            case '?':
                result = '?';
//                return "\\?"; // Literal question mark
                break;
            case '\\':
                result = '\\';
                break;
            case '0':
                result = '\0';
                break;
            case 'a':
                result = 0x07; // '\a', BEL alert
                break;
            case 'b':
                result = '\b'; // Backspace
                break;
            case 'f':
                result = '\f'; // Form feed
                break;
            case 'n':
                result = '\n';
                break;
            case 'r':
                result = '\r';
                break;
            case 't':
                result = '\t';
                break;
            case 'v':
                result = 0x0B; // '\v', Vertical tab
                break;
            case 'x':
                //TODO: refactor commonality
                // 8 bit unicode character, read next two chars as hex
                result = 0;
                for (int i = 0; i < 2; i++) {
                    if (next == -1) {
                        throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Unexpected end of stream");
                    }
                    try {
                        int n = Integer.parseInt(String.valueOf((char)next), 16);
                        result = (16 * result) + n;
                    } catch (NumberFormatException e) {
                        throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Invalid character in literal: "+next, e);
                    }

                    in_stream.read();
                    next = in_stream.peek();
                }

                break;
            case 'u':
                // 16 bit unicode character
                // read next four chars, as 2 bytes of literal
                result = 0;
                for (int i = 0; i < 4; i++) {
                    if (next == -1) {
                        throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Unexpected end of stream");
                    }
                    try {
                        int n = Integer.parseInt(String.valueOf((char)next), 16);
                        result = (16 * result) + n;
                    } catch (NumberFormatException e) {
                        throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Invalid character in literal: "+next, e);
                    }

                    in_stream.read();
                    next = in_stream.peek();
                }

                break;
            case 'U':
                // 32 bit unicode character
                // read next eight chars, as 4 bytes of literal
                result = 0;
                for (int i = 0; i < 8; i++) {
                    if (next == -1) {
                        throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Unexpected end of stream");
                    }
                    try {
                        int n = Integer.parseInt(String.valueOf((char)next), 16);
                        result = (16 * result) + n;
                    } catch (NumberFormatException e) {
                        throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Invalid character in literal: "+next, e);
                    }

                    in_stream.read();
                    next = in_stream.peek();
                }

                break;

            case '&':
                // HTML named character entity
                StringBuilder entity = new StringBuilder();
                entity.append((char)cur);
                while (true)
                {
                    if (next == -1) {
                        throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Unexpected end of stream");
                    }

                    if (next == ';') {
                        entity.append((char)in_stream.read());
                        break;
                    }

                    if (Character.isLetter(next)) {
                        entity.append((char)in_stream.read());
                    } else {
                        throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Unexpected character found in named entity: "+next);
                    }

                    next = in_stream.peek();
                }

                if (entity.length() < 1) {
                    throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Empty named character entity encountered");
                }

                String val = StringEscapeUtils.unescapeHtml4(entity.toString());
                result = Character.codePointAt(val, 0);
                break;

            default:
                if (!is_oct(cur)) {
                    throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Unrecognized escape sequence: "+next);
                }

                result = Integer.parseInt(String.valueOf((char)cur), 8);

                int cnt = 1;
                while (is_oct(next) && cnt < 3) {
                    // maximum of three octal digits
                    cnt++;

                    try {
                        int n = Integer.parseInt(String.valueOf((char)next), 8);
                        result = (8 * result) + n;
                    } catch (NumberFormatException e) {
                        throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Invalid character in octal literal: "+next, e);
                    }

                    in_stream.read();
                    next = in_stream.peek();
                }
                break;
        }

        return result;
    }

@Test
    public void escape() throws Exception {
        String str = "\\'" +  // \'
                     "\\\"" + // \"
                     "\\?" +  // \?
                     "\\\\" + // \\
                     "\\a" +  // \a
                     "\\b" +  // \b
                     "\\f" +  // \f
                     "\\n" +  // \n
                     "\\r" +  // \r
                     "\\t" +  // \t
                     "\\v" +  // \v
                     "\\0" +  // \0
                     "";

        LexerStream ls = new LexerStream(new StringReader(str));

        assertEquals('\'', (char)LexEscape.read(ls));
        assertEquals('"', (char)LexEscape.read(ls));
        assertEquals('?', (char)LexEscape.read(ls));
        assertEquals('\\', (char)LexEscape.read(ls));
        assertEquals(0x07, LexEscape.read(ls));
        assertEquals('\b', (char)LexEscape.read(ls));
        assertEquals('\f', (char)LexEscape.read(ls));
        assertEquals('\n', (char)LexEscape.read(ls));
        assertEquals('\r', (char)LexEscape.read(ls));
        assertEquals('\t', (char)LexEscape.read(ls));
        assertEquals(0x0B, LexEscape.read(ls));
        assertEquals(0x00, LexEscape.read(ls));
    }

public Token read() throws IOException, LexerException
    {
        int start_index = in_stream.getPosition();
        int start_line = in_stream.getLine();
        int start_col = in_stream.getCol();

        int next = in_stream.peek();
        if (next == -1) {
            throw new LexerException(start_line, start_col, "Unexpected end of input stream when parsing delimited string literal");
        }
        if (next != 'q') {
            throw new LexerException(start_line, start_col, "Not a delimited string literal");
        }

        in_stream.read();
        next = in_stream.peek();
        if (next != '"') {
            throw new LexerException(start_line, start_col, "Not a delimited string literal");
        }
        in_stream.read(); // consume opening quote
        next = in_stream.peek();


        boolean is_identifier = false;
        boolean is_nesting = false;
        int nests = 0;

        StringBuilder delimiter = new StringBuilder();



        if (is_nesting_open(next)) {
            is_nesting = true;
            delimiter.append(Character.toChars(in_stream.read()));
            //TODO: support multi-bracket delimiters like "{{ foo }}"?
        }
        else if (Character.isLetter(next) || next == '_') {
            //TODO: use actual identifier lexing logic
            is_identifier = true;

            delimiter.append(Character.toChars(in_stream.read()));
            next = in_stream.peek();
            while (Character.isLetterOrDigit(next) || next == '_') {
                delimiter.append(Character.toChars(in_stream.read()));
                next = in_stream.peek();
            }
            if (next != '\n') {
                throw new LexerException(in_stream.getLine(), in_stream.getCol(), "String delimiter must be followed by newline");
            }

            in_stream.read(); // consume newline
        }
        else {
            // non-identifier, non-nesting, just single char
            delimiter.append(Character.toChars(in_stream.read()));
        }
        next = in_stream.peek();


        String start_delim = delimiter.toString();
        String end_delim;
        if (is_identifier) {
            end_delim = start_delim;
        }
        else {
            end_delim = String.valueOf((char)valid_close(start_delim.charAt(0)));
        }


        StringBuilder result = new StringBuilder();

        while (next != -1) {

            if (next == '\n' && is_identifier) {
                // whether end delimiter or not, newline is part of string
                result.append((char)in_stream.read());
                next = in_stream.peek();

                // see if the delimiter is sitting on the stream
                StringBuilder sb = new StringBuilder();
                for (char c : end_delim.toCharArray()) {
                    if (next == -1) {
                        throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Unexpected end of stream in delimited string literal");
                    } else if (next != c) {
                        break;
                    }
                    sb.append(Character.toChars(in_stream.read()));
                    next = in_stream.peek();
                }
                if (next == '"' && sb.toString().equals(end_delim)) {
                    in_stream.read();
                    break; // end of string
                }

                // false alarm
                result.append(sb);
            }
            else if (is_nesting && next == start_delim.charAt(0)) {
                nests++;
            }
            else if (next == end_delim.charAt(0)) {
                nests--;
                if (nests < 0) {
                    // look for close followed by quote
                    if (in_stream.peek(2) == '"') {
                        in_stream.read();
                        in_stream.read();
                        break;
                    } else {
                        throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Improperly delimited string");
                    }
                }
            }

            // not the end
            result.append(Character.toChars(in_stream.read()));
            next = in_stream.peek();
        }

        if (next == -1) {
            throw new LexerException(in_stream.getLine(), in_stream.getCol(), "Unexpected end of stream in delimited string literal");
        }

        return factory.create(TokenType.LiteralUtf8,
                              start_index,
                              start_line,
                              start_col,
                              in_stream.getPosition(),
                              in_stream.getLine(),
                              in_stream.getCol(),
                              result.toString());
    }

