public static Object eval(String s) {

        String func = FN(s);
        s = s.replaceFirst(func, "");
        String[] params = {};
        if (s.length() >= 2) {
            String param = s.substring(1, s.lastIndexOf(")"));
            params = param.split(RX, -1);
        }
        return String.valueOf(EXE(func, params));
    }

