    assertEquals(new Vector3(2 * invLength, 1 * invLength, 3 * invLength), vec2);

    vec1.normalizeLocal();
    assertEquals(new Vector3(2 * invLength, 1 * invLength, 3 * invLength), vec1);

    vec1.zero();
    vec1.normalize(vec2);
    assertEquals(vec1, vec2);

    // ensure no exception thrown
    vec1.normalizeLocal();
    vec1.normalize(null);
  }

