    assertEquals(new Vector3(0.5, -1 / 3., 0.5), vec4B);

    vec1.divideLocal(0.5, 0.5, 0.5);
    assertEquals(new Vector3(2, -2, 4), vec1);

    vec1.divideLocal(vec2);
    assertEquals(new Vector3(2, 2, 2), vec1);
  }

