        {
            List<String> l = ccb.subList(2, 4);
            assertEquals(2, l.size());
            assertEquals("e3", l.get(0));
            assertEquals("e2", l.get(1));
        }

        ccb.add(3L, "e6"); // idx 0; other will scroll up

