public static String join(final Enum<? extends Enum>[] array, final String on) {
    if (array == null || array.length < 1) {
      return "";
    }

    final StringBuilder sb = new StringBuilder();
    for (int i = 0, l = array.length; i < l; ++i) {
      sb.append(array[i].toString());
      if (i < l - 1) {
        sb.append(on);
      }
    }

    return sb.toString();
  }

