protected void wipeDirectory(File rootDirectory) {
        File[] listFiles = rootDirectory.listFiles();

        if ( listFiles == null ) return;

        for (File file: listFiles)
        {
            if (file.isDirectory()) {
                wipeDirectory(file);
            }
            file.delete();
        }
    }

