@Override
    public Serializable execute(final TaskHandlerActionContext<PrincipalActionContext> inActionContext)
    {
        ActivityDTO inActivityDTO = ((PostActivityRequest) inActionContext.getActionContext().getParams())
                .getActivityDTO();
        ActivityDTO persistedActivityDTO;
        Activity newActivity = convertDTOToActivity(inActivityDTO, inActionContext.getUserActionRequests());
        List<UserActionRequest> queueRequests = new ArrayList<UserActionRequest>();

        String actorAccountName = inActionContext.getActionContext().getPrincipal().getAccountId();

        newActivity.setPostedTime(new Date());
        newActivity.setActorId(actorAccountName);
        newActivity.setActorType(EntityType.PERSON);

        long actorId = 0;
        long destinationId = 0;
        EntityType destinationType;

        // Persist to long term storage.
        insertMapper.execute(new PersistenceRequest<Activity>(newActivity));
        insertMapper.flush();

        // Force the cache to load the activityDTO in from the db.
        List<ActivityDTO> activityResults = activitiesMapper.execute(Arrays.asList(newActivity.getId()));
        persistedActivityDTO = activityResults.get(0);
        actorId = persistedActivityDTO.getActor().getId();
        destinationId = persistedActivityDTO.getDestinationStream().getDestinationEntityId();
        destinationType = persistedActivityDTO.getDestinationStream().getType();

        // add activity to destination entity streams
        updateStreamsByActorMapper.execute(persistedActivityDTO);

        // Insert the comment that was posted with a shared post.
        if (inActivityDTO.getFirstComment() != null && inActivityDTO.getVerb().equals(ActivityVerb.SHARE))
        {
            insertCommentDAO.execute(new InsertActivityCommentRequest(actorId, persistedActivityDTO.getId(),
                    inActivityDTO.getFirstComment().getBody()));
        }

        RequestType requestType = null;

        // Sends notifications for new personal stream posts.
        if (destinationType == EntityType.PERSON)
        {
            requestType = RequestType.POST_PERSON_STREAM;
        }
        // Sends notifications for new group stream posts.
        else if (destinationType == EntityType.GROUP)
        {
            requestType = RequestType.POST_GROUP_STREAM;
        }

        // Setup the queued requests.
        if (requestType != null)
        {
            CreateNotificationsRequest notificationRequest = new ActivityNotificationsRequest(requestType, actorId,
                    destinationId, persistedActivityDTO.getEntityId());
            queueRequests
                    .add(new UserActionRequest(CreateNotificationsRequest.ACTION_NAME, null, notificationRequest));
        }
        // TODO: fix this so activityDTO fields related to specific user
        // are not saved in cache.

        queueRequests.add(new UserActionRequest("postActivityAsyncAction", null, new PostActivityRequest(
                persistedActivityDTO)));

        inActionContext.getUserActionRequests().addAll(queueRequests);

        PersonModelView person = getPersonModelViewByAccountIdMapper.execute(actorAccountName);

        // execute filter strategies.
        for (ActivityFilter filter : filters)
        {
            filter.filter(Collections.singletonList(persistedActivityDTO), person);
        }

        return persistedActivityDTO;
    }

@Test
    public void testSuccessfulShareWithLink()
    {
        final String url = "http://foo.com";

        final ActivityDTO currentActivity = PostActivityTestHelpers.buildActivityDTO(
                PostActivityTestHelpers.DestinationStreamTestState.VALID, false, testComment, DESTINATION_ID);
        currentActivity.getBaseObjectProperties().put("targetUrl", url);

        final List<ActivityDTO> activityResults = new ArrayList<ActivityDTO>();
        activityResults.add(currentActivity);

        final PostActivityRequest request = new PostActivityRequest(currentActivity);

        final Principal currentPrincipal = new DefaultPrincipal(ACCOUNT_ID, OPENSOCIAL_ID, USER_ID);

        final SharedResource sr = new SharedResource();

        final String cacheSuffix = "SOMETHING";
        final String expectedCacheKey = CacheKeys.SHARED_RESOURCE_BY_UNIQUE_KEY + cacheSuffix;

        context.checking(new Expectations()
        {
            {
                oneOf(recipientRetrieverMock).getStreamScope(currentActivity);

                oneOf(recipientRetrieverMock).isDestinationStreamPublic(currentActivity);

                oneOf(activityInsertMapperMock).execute(with(any(PersistenceRequest.class)));

                oneOf(activityInsertMapperMock).flush();

                oneOf(activitiesMapperMock).execute(with(any(List.class)));
                will(returnValue(activityResults));

                oneOf(updateStreamsByActorMapperMock).execute(currentActivity);

                oneOf(findOrInsertSharedResourceMapper).execute(with(any(SharedResourceRequest.class)));
                will(returnValue(sr));

                oneOf(getPersonModelViewByAccountIdMapper).execute(ACCOUNT_ID);
                will(returnValue(person));

                oneOf(filter).filter(with(any(List.class)), with(person));

                oneOf(sharedResourceCacheKeySuffixTransformer).transform(url);
                will(returnValue(cacheSuffix));

                oneOf(cache).delete(expectedCacheKey);
            }
        });

        TaskHandlerActionContext<PrincipalActionContext> currentTaskHandlerActionContext = TestContextCreator
                .createTaskHandlerContextWithPrincipal(request, currentPrincipal);
        sut.execute(currentTaskHandlerActionContext);

        Assert.assertEquals(3, currentTaskHandlerActionContext.getUserActionRequests().size());

        // make sure all of the actions are kicked off
        boolean postActivityAsyncActionFound = false;
        boolean createNotificationsActionFound = false;
        boolean deleteCacheKeysActionFound = false;

        for (UserActionRequest req : currentTaskHandlerActionContext.getUserActionRequests())
        {
            if (req.getActionKey().equals("postActivityAsyncAction"))
            {
                postActivityAsyncActionFound = true;
            }
            else if (req.getActionKey().equals("createNotificationsAction"))
            {
                createNotificationsActionFound = true;
            }
            else if (req.getActionKey().equals("deleteCacheKeysAction"))
            {
                deleteCacheKeysActionFound = true;
                Set<String> params = (Set<String>) req.getParams();
                Assert.assertEquals(1, params.size());
                for (String s : params)
                {
                    Assert.assertEquals(expectedCacheKey, s);
                }
            }
        }

        Assert.assertTrue(postActivityAsyncActionFound);
        Assert.assertTrue(createNotificationsActionFound);
        Assert.assertTrue(deleteCacheKeysActionFound);

        context.assertIsSatisfied();
    }

