@Nullable
    public T get() {
        synchronized (lock) {
            T item = queue.poll();
            if (item != null) {
                activeCount++; // poll decreases, this fixes
                LOG.v("GET - Reusing recycled item.", this);
                return item;
            }

            if (isEmpty()) {
                LOG.v("GET - Returning null. Too much items requested.", this);
                return null;
            }

            activeCount++;
            LOG.v("GET - Creating a new item.", this);
            return factory.create();
        }
    }

