public static synchronized <T, E> T getKeyByValue(Map<T, E> map, E value) {
		Preconditions.checkNotNull(map, "The map cannot be null");

		for (Entry<T, E> entry : map.entrySet()) {
			if (Objects.equals(value, entry.getValue())) {
				return entry.getKey();
			}
		}
		return null;
	}

