		assertEquals((Integer) 1, CollectionUtils.getKeyByValue(map, 1));
		assertEquals((Integer) 2, CollectionUtils.getKeyByValue(map, 4));
		assertEquals((Integer) 3, CollectionUtils.getKeyByValue(map, 9));
		assertEquals((Integer) 4, CollectionUtils.getKeyByValue(map, 16));
		assertEquals(null, CollectionUtils.getKeyByValue(map, 5));
	}

public static <T extends Comparable<T>> T findMostPopularElement(
			List<T> list) {
		Preconditions.checkNotNull(list, "The list cannot be null");

		Collections.sort(list);

		T previous = list.get(0);
		T popular = list.get(0);
		int count = 1;
		int maxCount = 1;

		for (int i = 1; i < list.size(); i++) {
			if (list.get(i) == previous)
				count++;
			else {
				if (count > maxCount) {
					popular = list.get(i - 1);
					maxCount = count;
				}
				previous = list.get(i);
				count = 1;
			}
		}

		return count > maxCount ? list.get(list.size() - 1) : popular;
	}

