public TickCounter(TickHandler tickHandler, int maxTicks,
			int tickDuration) {
		this(tickHandler, maxTicks, tickDuration, 0);
	}

@Test
	public void testTickCounter() {
		int maxTicks = 75;
		int tickDuration = 30;
		int deltaMultiplier = 5;

		t = new TickCounter(new TickHandler() {
			@Override
			public void onTick() {
				tickCount++;
			}

			@Override
			public int getDeltaMultiplier() {
				return deltaMultiplier;
			}
		}, maxTicks, tickDuration);

		long startTime = System.currentTimeMillis();

		while (!t.update()) {
			// wait
		}

		long duration = System.currentTimeMillis() - startTime;

		// Normale Tests
		assertEquals(tickCount, t.getTickCount());
		assertEquals(maxTicks, t.getTickCount());
		assertEquals(maxTicks * tickDuration / deltaMultiplier, duration);

		// Keine weiteren Ticks nach max_tick
		assertEquals(false, t.update());
		assertEquals(tickCount, t.getTickCount());
		assertEquals(maxTicks, t.getTickCount());

		// Reset
		t.reset();
		tickCount = 0;
		while (!t.update()) {
			// wait
		}
		assertEquals(tickCount, t.getTickCount());
	}

public static <K, V extends Comparable<? super V>> Map<K, V> sortByValue(
			Map<K, V> map) {
		Preconditions.checkNotNull(map, "The map cannot be null");

		List<Entry<K, V>> list = new ArrayList<>(map.entrySet());
		list.sort(Entry.comparingByValue());

		Map<K, V> result = new LinkedHashMap<>();
		for (Entry<K, V> entry : list) {
			result.put(entry.getKey(), entry.getValue());
		}

		return result;
	}

@Test
	public void testSortByValue() {
		Map<Integer, Integer> map = new HashMap<>();
		map.put(1, 16);
		map.put(2, 8);
		map.put(3, 9);
		map.put(4, 5);
		map.put(5, 15);

		map = CollectionUtils.sortByValue(map);

		Integer[] tmp = map.keySet().toArray(new Integer[5]);

		assertEquals((Integer) 1, tmp[4]);
		assertEquals((Integer) 5, tmp[3]);
		assertEquals((Integer) 3, tmp[2]);
		assertEquals((Integer) 2, tmp[1]);
		assertEquals((Integer) 4, tmp[0]);
	}

