                Arrays.asList(LOCALE_EN_US, LOCALE_FR_FR),
                new LanguageMatchingAlgorithm(),
                ANY_PREFERENCE
        );

        // When
        Locale resolvedLocale = sut.resolve(LOCALE_IT_IT);

        // Then
        Assert.assertEquals(LOCALE_IT_IT, resolvedLocale);
    }

