@Test
  public void testNonStrict() {
    Date d = new Date(A_DATE);
    nonStrict(d, "2011-7-14T23:22:49.478Z", 5); // omit leading zero
    nonStrict(d, "2011-007-14T23:22:49.478Z", 5); // extra leading zero
    nonStrict(d, "2011/07/14T23:22:49.478Z", 4); // non-standard delimiters
    nonStrict(d, "2011-07-14T19:22:49.478-04:00?", 29); // extra character at end
    nonStrict(d, "2011-07-15T23:22:49.478+24:00", 25); // too large timezone offset
    nonStrict(d, "2011-07-14T08:52:49.478-14:30", 28); // too large timezone offset
    nonStrict(d, "2011-06-44T23:22:49.478Z", 9); // wrap the days field
    nonStrict(d, "2011-07-13T47:22:49.478Z", 12); // wrap the hours field
    nonStrict(d, "2011-07-14T22:82:49.478Z", 15); // wrap the minutes field

    d = DateTime.parse("2011-07-14T23:22:29.478Z");
    nonStrict(d, "2011-07-14T23:21:89.478Z", 18); // wrap the seconds field

    d = DateTime.parse("2011-07-15T00:00:15Z");
    nonStrict(d, "2011-07-14T24:00:15Z", 18); // past midnight
  }

public static KnxTelegram decode(byte knxMessage[]) {
		/* Receive the bytecode and decode it in a knxMessage */

		// String readMessage = new String();
		// readMessage = KnxEncoder.getInfoFromMessage(message);
		// return readMessage;

		/*
		 * KNX packet structure:
		 * http://de.wikipedia.org/wiki/Europ%C3%A4ischer_Installationsbus
		 *
		 * knxmessage[]: 0) control 1-2) source; // device which provides its
		 * state 3-4) destination; // can be both group (managed) or single
		 * (unmanaged) 5) DRL (Destination-adress-flag, Routing-counter,
		 * LENGTH(data)) 6) TPCI/APCI 7) Data/ACPI (command or state; there are
		 * 15 different command types) following bytes) data
		 */

		// check if telegram valid (minimum 9 bytes)
		if (knxMessage.length < 9)
			return null;

		KnxTelegram telegram = new KnxTelegram(knxMessage);
		// telegram.setSourceByte(new byte[] { knxMessage[1], knxMessage[2] });
		// telegram.setDestByte(new byte[] { knxMessage[3], knxMessage[4] });
		// telegram.setDrlByte(knxMessage[5]);

		// try {
		// int dataLength = KnxEncoder.extractPayloadLength(knxMessage[5]);
		// byte[] data = new byte[dataLength];
		// System.arraycopy(knxMessage, 7, data, 0, dataLength);
		// telegram.setDataByte(data);
		// } catch (IndexOutOfBoundsException ex) {
		// return null;
		// }

		// If the length of the byte array doesn't match with data length field
		// discard this telegram!
		if (!telegram.telegramDatalengthIsCorrect)
			return null;

		return telegram;
	}

@Test
	public void dataLengthTest() {
		byte[] message = new byte[] { (byte) 0xbc, 0x0d, 0, 0, 9, 1, 3, 0, (byte) 0x80, (byte) 0x12, (byte) 0x13 };
		assertTrue(
				"KnxEncoder.decode(new byte[] {(byte) 0xbc, 0x0d, 0, 0, 9, 1, 3, 0, (byte) 0x80, (byte) 0x12, (byte) 0x13 }).telegramDatalengthIsCorrect is "
						+ KnxEncoder.decode(message).telegramDatalengthIsCorrect + "; but should be true",
				KnxEncoder.decode(message).telegramDatalengthIsCorrect == true);
		byte[] message2 = new byte[] { (byte) 0xbc, 0x0d, 0, 0, 9, 1, 4, 0, (byte) 0x80, (byte) 0x12, (byte) 0x13 };
		assertTrue(
				"KnxEncoder.decode(new byte[] {(byte) 0xbc, 0x0d, 0, 0, 9, 1, 4, 0, (byte) 0x80, (byte) 0x12, (byte) 0x13 }) is "
						+ KnxEncoder.decode(message2) + "; but should be NULL",
				KnxEncoder.decode(message2) == null);
		byte[] message3 = new byte[] { (byte) 0xbc, 0x0d, 0, 0, 9, 1, 3, 0, (byte) 0x80, (byte) 0x12, (byte) 0x13,
				(byte) 0xAE };
		assertTrue(
				"KnxEncoder.decode(new byte[] {(byte) 0xbc, 0x0d, 0, 0, 9, 1, 3, 0, (byte) 0x80, (byte) 0x12, (byte) 0x13, (byte) 0xAE }) is "
						+ KnxEncoder.decode(message3) + "; but should be NULL",
				KnxEncoder.decode(message3) == null);
	}

