public static int[] deltaEncode(int[] intArray) {
		int[] out = new int[intArray.length];
		System.arraycopy(intArray, 0, out, 0, intArray.length);
		for (int i = out.length-1; i > 0; i--) {
			out[i] = out[i] - out[i-1];
		}
		return out;
	}

