                System.out.flush();
                System.err.println();
                System.err.println(e.asString());
                if (options.verbose()) {
                    System.err.println();
                    e.printStackTrace();
                }
            } catch (UncheckedIOException | IOException e) {
                System.out.flush();
                System.err.println();
                System.err.println("I/O error: " + e.getMessage());
                if (options.verbose()) {
                    System.err.println();
                    e.printStackTrace();
                }
            }
        } catch (Exception e) {
            System.out.flush();
            System.err.println();
            System.err.println("Unchecked exception: " + e.getMessage());
            if (options.verbose()) {
                System.err.println();
                e.printStackTrace();
            }
        }
        exit(1);
    }

