static boolean differenceGreaterThan(Instant preexistingExecutionTime, Instant potentiallyNewExecutionTime, Duration delta) {
        final Duration difference = Duration.between(preexistingExecutionTime, potentiallyNewExecutionTime).abs();
        return difference.toMillis() > delta.toMillis();
    }

@Test
    void test_differenceGreaterThan() {
        assertTrue(differenceGreaterThan(clock.now(), clock.now().minusSeconds(10), Duration.ofSeconds(1)));
        assertTrue(differenceGreaterThan(clock.now(), clock.now().plusSeconds(10), Duration.ofSeconds(1)));

        assertFalse(differenceGreaterThan(clock.now(), clock.now().minusSeconds(10), Duration.ofSeconds(11)));
        assertFalse(differenceGreaterThan(clock.now(), clock.now().plusSeconds(10), Duration.ofSeconds(11)));
    }

public void wakeOrSkipNextWait() {
        // Take early lock to avoid race-conditions. Lock is also taken in wake() (lock is re-entrant)
        synchronized (lock) {
            final boolean awoken = wake();
            if (!awoken) {
                LOG.debug("Waiter not waiting, instructing to skip next wait.");
                this.skipNextWait = true;
            }
        }
    }

@Test
