public void add(Schema schema) {
		for (Iterator<Schema> it = schemas.iterator(); it.hasNext();) {
			Schema oriSchema = it.next();
			if (oriSchema.contains(schema)) {
				return;
			} else if (schema.contains(oriSchema)) {
				it.remove();
			}
		}
		schemas.add(schema);
	}

