            }
        };
        context.children = Collections.singletonList(content);

        Token start = new CommonToken(1, "Start");
        Token stop = new CommonToken(2, "Stop");

        context.start = null;
        context.stop = null;
        assertEquals("Content", AntlrUtils.getSourceText(context));

        context.start = start;
        context.stop = null;
        assertEquals("Content", AntlrUtils.getSourceText(context));

        context.start = null;
        context.stop = stop;
        assertEquals("Content", AntlrUtils.getSourceText(context));
    }

