public DlgpWriter write(Directive d) throws IOException {
		switch (d.getType()) {
		case UNA:
			this.write("@una");
			break;
		case BASE:
			if(!d.getValue().toString().isEmpty()) {
				this.base  = d.getValue().toString();
				this.write("@base ");
				this.write('<');
				this.write(encode(this.base));
				this.write('>');
			}
			break;
		case TOP:
			if (d.getValue() instanceof Predicate) {
				this.top = (Predicate) d.getValue();
			} else {
				this.top = new Predicate(d.getValue().toString(), 1);
			}
			this.write("@top ");
			this.writePredicate(this.top);
			break;
		case COMMENT:
			this.write("%% ");
			this.write(d.getValue());
			break;
		}
		this.write("\n");
		return this;
	}

@Test
	public void writeURIForbiddenChars() throws IOException {
		Predicate p = new Predicate(new DefaultURI("/< >\"{}|^`\\/"), 1);


		ByteArrayOutputStream os = new ByteArrayOutputStream();
		DlgpWriter writer = new DlgpWriter(os);

		writer.write(new DefaultAtom(p, cst));
		writer.flush();

		String s = new String(os.toByteArray(),"UTF-8");
		writer.close();

		System.out.println(s);
		Assert.assertEquals("</\\u003c\\u0020\\u003e\\u0022\\u007b\\u007d\\u007c\\u005e\\u0060\\u005c/>(<A>).\n", s);
	}

