public static PcapHandle openOffline(String filePath) throws PcapNativeException {
    if (filePath == null) {
      StringBuilder sb = new StringBuilder();
      sb.append("filePath: ").append(filePath);
      throw new NullPointerException(sb.toString());
    }

    PcapErrbuf errbuf = new PcapErrbuf();
    Pointer handle = NativeMappings.pcap_open_offline(filePath, errbuf);

    if (handle == null || errbuf.length() != 0) {
      throw new PcapNativeException(errbuf.toString());
    }

    return new PcapHandle(handle, TimestampPrecision.MICRO);
  }

@Test
  public void testOpenOfflineWithTimestampPrecision() throws Exception {
    if (!Boolean.getBoolean(Constants.ENABLE_TIMESTAMP_PRECISION_TESTS_KEY)) {
      return;
    }

    PcapHandle phNano =
        Pcaps.openOffline(
            "src/test/resources/org/pcap4j/core/"
                + "PcapsTest.testOpenOfflineWithTimestampPrecision.pcap",
            TimestampPrecision.NANO);
    phNano.getNextRawPacket();
    assertEquals(1434220771517L, phNano.getTimestamp().getTime());
    assertEquals(517995677, phNano.getTimestamp().getNanos());
    phNano.close();

    PcapHandle phMicro =
        Pcaps.openOffline(
            "src/test/resources/org/pcap4j/core/"
                + "PcapsTest.testOpenOfflineWithTimestampPrecision.pcap",
            TimestampPrecision.MICRO);
    phMicro.getNextRawPacket();
    System.out.println(phMicro.getTimestamp().getTime());
    System.out.println(phMicro.getTimestamp().getNanos());
    assertEquals(1434220771517L, phMicro.getTimestamp().getTime());
    assertEquals(517995000, phMicro.getTimestamp().getNanos());
    phMicro.close();
  }

public static int getCollectionSize( String range, int collectionSize )
    {
        int min = Integer.parseInt( range.split( "-" )[0] );
        int max = Integer.parseInt( range.split( "-" )[1] );
        if ( min == 0 && max == 0 )
        {
            return 0;
        }
        if ( min > collectionSize )
        {
            min = collectionSize;
        }
        if ( max > collectionSize )
        {
            max = collectionSize;
        }
        return min == max ? min : ints().rangeClosed( min, max ).get() - 1;
    }

