final public static SeverityLevel decodeSeverity(final VType value)
    {
        final Alarm alarm = Alarm.alarmOf(value);
        if (alarm == null) // Can this really happen?
            return SeverityLevel.OK;
        switch (alarm.getSeverity())
        {
        case NONE:
            return SeverityLevel.OK;
        case MINOR:
            return SeverityLevel.MINOR;
        case MAJOR:
            return SeverityLevel.MAJOR;
        case INVALID:
            return SeverityLevel.INVALID;
        default:
            return SeverityLevel.UNDEFINED;
        }
    }

@Test
    public void decodeSeverity() {

        assertEquals(SeverityLevel.INVALID, SeverityLevelHelper.decodeSeverity(null));

        VInt intValue = VInt.of(7, Alarm.disconnected(), Time.now(), Display.none());
        SeverityLevel severityLevel = SeverityLevelHelper.decodeSeverity(intValue);
        assertEquals(SeverityLevel.INVALID, severityLevel);

        intValue = VInt.of(7, Alarm.none(), Time.now(), Display.none());
        severityLevel = SeverityLevelHelper.decodeSeverity(intValue);
        assertEquals(SeverityLevel.OK, severityLevel);

        intValue = VInt.of(7, Alarm.lolo(), Time.now(), Display.none());
        severityLevel = SeverityLevelHelper.decodeSeverity(intValue);
        assertEquals(SeverityLevel.MAJOR, severityLevel);

        intValue = VInt.of(7, Alarm.hihi(), Time.now(), Display.none());
        severityLevel = SeverityLevelHelper.decodeSeverity(intValue);
        assertEquals(SeverityLevel.MAJOR, severityLevel);

        intValue = VInt.of(7, Alarm.low(), Time.now(), Display.none());
        severityLevel = SeverityLevelHelper.decodeSeverity(intValue);
        assertEquals(SeverityLevel.MINOR, severityLevel);

        intValue = VInt.of(7, Alarm.high(), Time.now(), Display.none());
        severityLevel = SeverityLevelHelper.decodeSeverity(intValue);
        assertEquals(SeverityLevel.MINOR, severityLevel);

    }

public static String format(final VType value, final FormatOption option,
                                int precision, final boolean show_units)
    {

        precision = actualPrecision(value, precision);

        if (value == null)
            return "<null>";

        // Check roughly in order of likelyhood:
        // We mostly expect numbers, then strings, then enum.
        // For the arrays, handling any of them is expensive,
        // so there the order of checking doesn't much matter.
        if (value instanceof VNumber)
        {
            final VNumber number = (VNumber) value;
            final String text = formatNumber(number.getValue(), number.getDisplay(), option, precision);
            if (show_units  &&  !number.getDisplay().getUnit().isEmpty())
                return text + " " + number.getDisplay().getUnit();
            return text;
        }
        else if (value instanceof VString)
            return ((VString)value).getValue();
        else if (value instanceof VEnum)
            return formatEnum((VEnum) value, option);
        else if (value instanceof VBoolean)
            return formatBoolean((VBoolean)value);
        else if (value instanceof VNumberArray)
        {
            final VNumberArray array = (VNumberArray) value;
            if (option == FormatOption.STRING)
                return LongString.fromArray(array);
            final ListNumber data = array.getData();
            if (data.size() <= 0)
                return "[]";
            final StringBuilder buf = new StringBuilder("[");
            buf.append(formatNumber(data.getDouble(0), array.getDisplay(), option, precision));
            final int show = Math.min(data.size(), Preferences.max_array_formatting);
            for (int i=1; i<show; ++i)
            {
                buf.append(", ");
                buf.append(formatNumber(data.getDouble(i), array.getDisplay(), option, precision));
            }
            if (data.size() > show)
                buf.append(", ...");
            buf.append("]");
            if (show_units  &&  !array.getDisplay().getUnit().isEmpty())
                buf.append(" ").append(array.getDisplay().getUnit());
            return buf.toString();
        }
        else if (value instanceof VEnumArray)
        {
            final List<String> labels = ((VEnumArray)value).getDisplay().getChoices();
            final StringBuilder buf = new StringBuilder("[");
            for (int i=0; i<labels.size(); ++i)
            {
                if (i > 0)
                    buf.append(", ");
                buf.append(labels.get(i));
            }
            buf.append("]");
            return buf.toString();
        }
        else if (value instanceof VStringArray)
            return StringList.join(((VStringArray)value).getData());
        else if (value instanceof VImage)
        {
            final VImage image = (VImage) value;
            return "VImage(" + image.getWidth() + " x " + image.getHeight() + ")";
        }
        else if (value instanceof VTable)
            return formatTable((VTable) value);

        return "<" + value.getClass().getName() + ">";
    }

@Test
    public void testDecimal() throws Exception
    {
        VType number = VDouble.of(3.16, Alarm.none(), Time.now(), display);

        assertThat(fmt.format(3.16), equalTo("3.16"));

        String text = FormatOptionHandler.format(number, FormatOption.DEFAULT, -1, true);
        System.out.println(text);
        assertThat(text, equalTo("3.160 V"));

        text = FormatOptionHandler.format(number, FormatOption.DEFAULT, -1, false);
        System.out.println(text);
        assertThat(text, equalTo("3.160"));

        text = FormatOptionHandler.format(number, FormatOption.DECIMAL, 4, true);
        System.out.println(text);
        assertThat(text, equalTo("3.1600 V"));

        text = FormatOptionHandler.format(number, FormatOption.DECIMAL, 1, true);
        System.out.println(text);
        assertThat(text, equalTo("3.2 V"));

        // For running in debugger: Repeated use of precision 4 should use cached format
        text = FormatOptionHandler.format(number, FormatOption.DECIMAL, 4, true);
        System.out.println(text);
        assertThat(text, equalTo("3.1600 V"));
    }

