public boolean isNull(RexNode expr) {
    switch (expr.getKind()) {
    case LITERAL:
      return ((RexLiteral) expr).getValue2() == null;
    case LOCAL_REF:
      RexLocalRef inputRef = (RexLocalRef) expr;
      return isNull(exprs.get(inputRef.index));
    case CAST:
      return isNull(((RexCall) expr).operands.get(0));
    default:
      return false;
    }
  }

