public void increment(String uri) throws InterruptedException {
        Long oldCount, newCount;
        int waitTime = 1;
        while (true) {
            oldCount = visitCount.get(uri);
            LOGGER.info("oldCount:{}", oldCount);
            if (oldCount == null) {
                if (visitCount.putIfAbsent(uri, 1L) == null) {
                    LOGGER.info("finish init");
                    break;
                }
            } else {
                newCount = oldCount + 1;
                if (visitCount.replace(uri, oldCount, newCount)) {
                    LOGGER.info("add one :{}", newCount);
                    break;
                }
                LOGGER.info("newCount:{},waitTime:{}", newCount, waitTime);
                TimeUnit.MICROSECONDS.sleep(waitTime++);
            }

        }

    }

@Test
    public void incrementTest() throws Exception {
        String uri = "http://localhost:8080/user/1";
        VisitCounter visitCounter = new VisitCounter();

        int size = 10000;
        CountDownLatch countDownLatch = new CountDownLatch(size);
        ExecutorService executorService = new ThreadPoolExecutor(3,
                20,
                5,
                TimeUnit.MINUTES,
                new ArrayBlockingQueue<Runnable>(2000),
                new DefaultThreadFactory(),
                new ThreadPoolExecutor.CallerRunsPolicy()//在部分任务都在新线程中进行的，因为maximumPoolSize比较小，队列长度不够深
        );

        for (int i = 0; i < size; i++) {
            executorService.execute(new Runnable() {
                @Override
                public void run() {
                    try {
                        visitCounter.increment(uri);
                        countDownLatch.countDown();
                    } catch (InterruptedException e) {
                        LOGGER.warn(e.getMessage(), e);
                    }
                }
            });
        }

        countDownLatch.await();

        assertThat((long) size, is(visitCounter.get(uri)));
    }

