public boolean bracketMatch(String bracketSource) {
        if (StringUtils.isBlank(bracketSource)) {
            return false;
        }
        char[] charArray = bracketSource.toCharArray();
        Stack<Character> stack = new Stack<>();
        for (char next : charArray) {
            /**
             * public synchronized E peek() {
             *    int len = size();
             *      if (len == 0)
             *        throw new EmptyStackException();
             */
            if (stack.isEmpty()) {
                if (patternMatch.get(next) == null) {
                    // when empty,the next must be left bracket!
                    return false;
                }
                stack.push(next);
                continue;
            }

            Character lastItem = stack.peek();
            if (Objects.equals(next, patternMatch.get(lastItem))) {
                stack.pop();
            } else {
                stack.push(next);
            }
        }
        return stack.isEmpty();
    }

@Test
    public void bracketMatch() {
        StackDemoExam demoExam = new StackDemoExam();
        String demo1 = "()[]{}";
        boolean result = demoExam.bracketMatch(demo1);
        assertThat(result).isTrue();
        System.out.println(result);

        demo1 = "()[()]{[]}";
        result = demoExam.bracketMatch(demo1);
        assertThat(result).isTrue();
        System.out.println(result);
        demo1 = "()";
        result = demoExam.bracketMatch(demo1);
        assertThat(result).isTrue();
        System.out.println(result);
        String demo2 = "([)]";
        result = demoExam.bracketMatch(demo2);
        assertThat(result).isFalse();
        System.out.println(result);
        demo2 = "(]";
        result = demoExam.bracketMatch(demo2);
        assertThat(result).isFalse();
        System.out.println(result);
    }

