        resultIdx = searchExam.binarySearch(Arrays.asList(1, 2, 3, 5, 4), 4);
        assertThat(resultIdx).isEqualTo(3);
        resultIdx = searchExam.binarySearch(Arrays.asList(1, 2, 3, 5, 6), 4);
        assertThat(resultIdx).isEqualTo(-1);
    }

