public void removeRelation(String fieldName, PersistentResource removeResource) {
        Object relation = getValueUnchecked(fieldName);
        Object original = relation;
        Object modified = null;

        if (relation instanceof Collection) {
            original = copyCollection((Collection) relation);
        }

        if (relation instanceof Collection && removeResource != null) {
            modified = CollectionUtils.disjunction(
                    (Collection) relation,
                    Collections.singleton(removeResource.getObject())
            );
        }

        checkFieldAwareDeferPermissions(UpdatePermission.class, fieldName, modified, original);

        if (relation instanceof Collection) {
            if (removeResource == null || !((Collection) relation).contains(removeResource.getObject())) {

                //Nothing to do
                return;
            }
            delFromCollection((Collection) relation, fieldName, removeResource, false);
        } else {
            if (relation == null || removeResource == null || !relation.equals(removeResource.getObject())) {
                //Nothing to do
                return;
            }
            this.nullValue(fieldName, removeResource);
        }

        if (hasInverseRelation(fieldName)) {
            deleteInverseRelation(fieldName, removeResource.getObject());
            removeResource.markDirty();
        }

        if (!Objects.equals(original, modified)) {
            this.markDirty();
        }

        RelationshipType type = getRelationshipType(fieldName);
        if (type.isToOne()) {
            //hook for updateToOneRelation
            transaction.updateToOneRelation(transaction, obj, fieldName, null, requestScope);
        } else {
            //hook for updateToManyRelation
            transaction.updateToManyRelation(transaction, obj, fieldName,
                    new LinkedHashSet<>(), Sets.newHashSet(removeResource.getObject()), requestScope);
        }
    }

@Test()
    public void testRemoveToManyRelationSuccess() {
        Child child = newChild(1);
        Parent parent1 = newParent(1, child);
        Parent parent2 = newParent(2, child);
        Parent parent3 = newParent(3, child);
        child.setParents(Sets.newHashSet(parent1, parent2, parent3));

        DataStoreTransaction tx = mock(DataStoreTransaction.class);
        User goodUser = new User(1);
        RequestScope goodScope = buildRequestScope(tx, goodUser);
        PersistentResource<Child> childResource = new PersistentResource<>(child, null, "1", goodScope);
        PersistentResource<Object> removeResource = new PersistentResource<>(parent1, null, "1", goodScope);
        childResource.removeRelation("parents", removeResource);

        assertEquals(2, child.getParents().size(), "The many-2-many relationship should be cleared");
        assertEquals(0, parent1.getChildren().size(), "The many-2-many inverse relationship should be cleared");
        assertEquals(1, parent3.getChildren().size(), "The many-2-many inverse relationship should not be cleared");
        assertEquals(1, parent3.getChildren().size(), "The many-2-many inverse relationship should not be cleared");

        goodScope.saveOrCreateObjects();
        verify(tx, times(1)).save(child, goodScope);
        verify(tx, times(1)).save(parent1, goodScope);
        verify(tx, never()).save(parent2, goodScope);
        verify(tx, never()).save(parent3, goodScope);
    }

@Override
    public FilterExpression parseGlobalExpression(String path, MultivaluedMap<String, String> filterParams)
            throws ParseException {
        if (filterParams.size() != 1) {
            throw new ParseException(SINGLE_PARAMETER_ONLY);
        }

        MultivaluedMap.Entry<String, List<String>> entry = CollectionUtils.get(filterParams, 0);
        String queryParamName = entry.getKey();

        if (!"filter".equals(queryParamName)) {
            throw new ParseException(INVALID_QUERY_PARAMETER + queryParamName);
        }
        List<String> queryParamValues = entry.getValue();

        if (queryParamValues.size() != 1) {
            throw new ParseException(SINGLE_PARAMETER_ONLY);
        }

        String queryParamValue = queryParamValues.get(0);

        /*
         * Extract the last collection in the URL.
         */
        String normalizedPath = JsonApiParser.normalizePath(path);
        String[] pathComponents = normalizedPath.split("/");
        String lastPathComponent = pathComponents.length > 0 ? pathComponents[pathComponents.length - 1] : "";

        /*
         * TODO - create a visitor which extracts the type/class of the last path component.
         * This works today by virtue that global filter expressions are only used for root collections
         * and NOT nested associations.
         */
        Class entityType = dictionary.getEntityClass(lastPathComponent);
        if (entityType == null) {
            throw new ParseException("No such collection: " + lastPathComponent);
        }

        return parseFilterExpression(queryParamValue, entityType, true);
    }

