static void writeCanonicalString(
      ClientRequestContext ctx, RequestHeaders headers, HttpData payload, ByteBuf result) {
    // HTTPRequestMethod + '\n' +
    ByteBufUtil.writeUtf8(result, ctx.method().name());
    result.writeByte('\n');

    // CanonicalURI + '\n' +
    // TODO: make this more efficient
    ByteBufUtil.writeUtf8(result,
        ctx.path().replace("*", "%2A").replace(",", "%2C").replace(":", "%3A"));
    result.writeByte('\n');

    // CanonicalQueryString + '\n' +
    String query = ctx.query();
    if (query != null) {
      ByteBufUtil.writeUtf8(result, query);
    }
    result.writeByte('\n');

    // CanonicalHeaders + '\n' +
    ByteBuf signedHeaders = ctx.alloc().buffer();

    writeCanonicalHeaderValue(HOST, host(headers, ctx), signedHeaders, result);
    try {
      for (AsciiString canonicalHeader : OTHER_CANONICAL_HEADERS) {
        String value = headers.get(canonicalHeader);
        if (value != null) {
          writeCanonicalHeaderValue(canonicalHeader, value, signedHeaders, result);
        }
      }
      result.writeByte('\n'); // end headers

      // SignedHeaders + '\n' +
      signedHeaders.readByte(); // throw away the first semicolon
      result.writeBytes(signedHeaders);
    } finally {
      signedHeaders.release();
    }
    result.writeByte('\n');

    // HexEncode(Hash(Payload))
    if (!payload.isEmpty()) {
      ByteBufUtil.writeUtf8(result, ByteBufUtil.hexDump(sha256(payload)));
    } else {
      ByteBufUtil.writeUtf8(result, EMPTY_STRING_HASH);
    }
  }

@Test public void canonicalString_colonsInPath() {
    AggregatedHttpRequest request = AggregatedHttpRequest.of(RequestHeaders.builder(HttpMethod.GET,
        "/_cluster/health/zipkin:span-*")
        .set(AWSSignatureVersion4.X_AMZ_DATE, "20170830T143137Z")
        .build()
    );
    ClientRequestContext ctx = ClientRequestContext.builder(request.toHttpRequest())
        .endpoint(Endpoint.of(
            "search-zipkin53-mhdyquzbwwzwvln6phfzr3mmdi.ap-southeast-1.es.amazonaws.com"))
        .build();

    ByteBuf result = Unpooled.buffer();

    writeCanonicalString(ctx, request.headers(), request.content(), result);

    // Ensure that the canonical string encodes commas with %2C
    assertThat(result.toString(UTF_8)).isEqualTo(""
        + "GET\n"
        + "/_cluster/health/zipkin%3Aspan-%2A\n"
        + "\n"
        + "host:search-zipkin53-mhdyquzbwwzwvln6phfzr3mmdi.ap-southeast-1.es.amazonaws.com\n"
        + "x-amz-date:20170830T143137Z\n"
