public Optional<String> resolveExecutor(final int blockId) {
    final String ownerId = blockOwnerArray.get(blockId);
    if (ownerId.equals(localExecutorId)) {
      return Optional.empty();
    } else {
      return Optional.of(ownerId);
    }
  }

@Test
  public void testMultipleOwnershipCaches() throws InjectionException {
    final int numTotalBlocks = 1024;
    final int numExecutors = 4;

    final Map<String, OwnershipCache> ownershipCaches = newOwnershipCaches(numExecutors, numTotalBlocks);

    for (int blockId = 0; blockId < numTotalBlocks; blockId++) {

      // This is the memory store id that is answered at the first time.
      // It is for checking all ownershipCaches give the same answer.
      // null means that memory store id for the block has not been found yet
      String firstAnswer = null;

      boolean localStoreFound = false;

      // check all ownershipCaches give same answer
      for (final Map.Entry<String, OwnershipCache> entry : ownershipCaches.entrySet()) {
        final String localExecutorId = entry.getKey();
        final OwnershipCache ownershipCache = entry.getValue();

        final Optional<String> executorId = ownershipCache.resolveExecutor(blockId);

        final String targetExecutorId;
        // OwnershipCache.resolveEval(blockId) returns empty when the MemoryStore owns the block locally
        if (!executorId.isPresent()) {
          assertFalse("Block should belong to only one store", localStoreFound);
          localStoreFound = true;

          targetExecutorId = localExecutorId;
        } else {
          targetExecutorId = executorId.get();
        }

        if (firstAnswer == null) {
          firstAnswer = targetExecutorId; // it's set by the first OwnershipCache's answer
        } else {
          assertEquals("Ownership caches should give the same memory store id for the same block",
              firstAnswer, targetExecutorId);
        }
      }
    }
  }

@Test
  public void testRemoteAccess() throws TableNotExistException, InterruptedException, NetworkException {
    final TableComponents<String, Integer, Integer> tableComponents = tables.getTableComponents(TABLE_ID);
    final KVUSerializer<String, Integer, Integer> kvuSerializer = tableComponents.getSerializer();
    final StreamingCodec<String> keyCodec = kvuSerializer.getKeyCodec();
    final StreamingCodec<Integer> valueCodec = kvuSerializer.getValueCodec();

    // we can know whether the access has been finished using 'replyLatch'
    final ResettingCountDownLatch replyLatch = new ResettingCountDownLatch(1);
    // and can get the result through 'reply'
    final AtomicReference<Integer> reply = new AtomicReference<>();

    doAnswer(invocation -> {
      final Object[] arguments = invocation.getArguments();
      final String destId = (String) arguments[0];
      final long opId = (long) arguments[1];
      final DataValue dataValue = (DataValue) arguments[3];
      final Integer value = dataValue == null ? null : valueCodec.decode(dataValue.getValue().array());
      final boolean isSuccess = (boolean) arguments[4];

      if (!isSuccess || !destId.equals(ORIG_EXECUTOR_ID)) {
        fail(String.format("Operation with id %d is failed", opId));
      }

      reply.set(value);
      replyLatch.countDown();

      LOG.log(Level.FINE, "Access result. opId: {0}, value: {1}, destId: {2}",
          new Object[]{opId, value, destId});
      return null;
    }).when(mockMsgSender).sendTableAccessResMsg(anyString(), anyLong(), anyString(), anyObject(), anyBoolean());

    final String key = "key";
    final Integer value = 1;

    final Pair<DataKey, DataValue> dataPair = getDataPair(key, value, keyCodec, valueCodec);

    // 1. put value
    final AtomicInteger opIdCounter = new AtomicInteger(0);
    final TableAccessReqMsg putMsg = TableAccessReqMsg.newBuilder()
        .setOrigId(ORIG_EXECUTOR_ID)
        .setOpType(OpType.PUT)
        .setTableId(TABLE_ID)
        .setDataKey(dataPair.getKey())
        .setDataValue(dataPair.getValue())
        .build();

    remoteAccessOpHandler.onTableAccessReqMsg(opIdCounter.getAndIncrement(), putMsg);
    replyLatch.awaitAndReset(1); // replyLatch must have been released while the event was handle
    assertEquals(null, reply.get());

    // 2. get value to confirm that put request has been done successfully
    final TableAccessReqMsg getMsg = TableAccessReqMsg.newBuilder()
        .setOrigId(ORIG_EXECUTOR_ID)
        .setOpType(OpType.GET)
        .setTableId(TABLE_ID)
        .setDataKey(dataPair.getKey())
        .setDataValue(null)
        .build();

    remoteAccessOpHandler.onTableAccessReqMsg(opIdCounter.getAndIncrement(), getMsg);
    replyLatch.awaitAndReset(1); // replyLatch must have been released while the event was handle
    assertEquals(value, reply.get());

    // 3. update value based on the value put by the first request
    final TableAccessReqMsg updateMsg = TableAccessReqMsg.newBuilder()
        .setOrigId(ORIG_EXECUTOR_ID)
        .setOpType(OpType.UPDATE)
        .setTableId(TABLE_ID)
        .setDataKey(dataPair.getKey())
        .setDataValue(dataPair.getValue())
        .build();

    remoteAccessOpHandler.onTableAccessReqMsg(opIdCounter.getAndIncrement(), updateMsg);
    replyLatch.awaitAndReset(1); // replyLatch must have been released while the event was handled
    assertEquals(Integer.valueOf(value + value), reply.get());

    // 4. check that putIfAbsent request is ignored when there exists the associated value
    final TableAccessReqMsg putIfAbsentMsg = TableAccessReqMsg.newBuilder()
        .setOrigId(ORIG_EXECUTOR_ID)
        .setOpType(OpType.PUT_IF_ABSENT)
        .setTableId(TABLE_ID)
        .setDataKey(dataPair.getKey())
        .setDataValue(dataPair.getValue())
        .build();

    remoteAccessOpHandler.onTableAccessReqMsg(opIdCounter.getAndIncrement(), putIfAbsentMsg);
    replyLatch.awaitAndReset(1); // replyLatch must have been released while the event was handle
    assertEquals(Integer.valueOf(value + value), reply.get()); // putIfAbsent cannot overwrite value

    // 5. get value to confirm that value does not change by putIfAbsent request
    remoteAccessOpHandler.onTableAccessReqMsg(opIdCounter.getAndIncrement(), getMsg);
    replyLatch.awaitAndReset(1); // replyLatch must have been released while the event was handle
    assertEquals(Integer.valueOf(value + value), reply.get());

    // 6. remove value
    final TableAccessReqMsg removeMsg = TableAccessReqMsg.newBuilder()
        .setOrigId(ORIG_EXECUTOR_ID)
        .setOpType(OpType.REMOVE)
        .setTableId(TABLE_ID)
        .setDataKey(dataPair.getKey())
        .setDataValue(null)
        .build();

    remoteAccessOpHandler.onTableAccessReqMsg(opIdCounter.getAndIncrement(), removeMsg);
    replyLatch.awaitAndReset(1); // replyLatch must have been released while the event was handle
    assertEquals(Integer.valueOf(value + value), reply.get());

    // 7. get value to confirm that value has been deleted by remove request
    remoteAccessOpHandler.onTableAccessReqMsg(opIdCounter.getAndIncrement(), getMsg);
    replyLatch.awaitAndReset(1); // replyLatch must have been released while the event was handle
    assertEquals(null, reply.get());

    verify(mockMsgSender, times(7))
        .sendTableAccessResMsg(anyString(), anyLong(), anyString(), anyObject(), anyBoolean());
  }

public static Set<LongRange> getComplement(final LongRange range1, final LongRange range2) {
    final Set<LongRange> complement = new HashSet<>();
    if (!range1.overlapsRange(range2)) {
      complement.add(range1);
      return complement;
    } else {
      final LongRange intersect = getIntersection(range1, range2);
      // If two sections are overlapping, we can divide into three parts: LEFT | CENTER | RIGHT
      // LEFT ([leftEnd (centerLeft-1)] and RIGHT ([(centerRight+1) rightEnd]) if they are not empty.
      final long min1 = range1.getMinimumLong();
      final long max1 = range1.getMaximumLong();
      final long min2 = intersect.getMinimumLong();
      final long max2 = intersect.getMaximumLong();
      final long minMax = Math.min(max1, max2);
      final long maxMin = Math.max(min1, min2);

      final long leftEnd = Math.min(min1, min2);
      final long centerLeft = Math.min(minMax, maxMin);
      final long centerRight = Math.max(minMax, maxMin);
      final long rightEnd = Math.max(max1, max2);

      // Add LEFT only if exists.
      if (leftEnd < centerLeft) {
        final LongRange left = new LongRange(leftEnd, centerLeft - 1);
        complement.add(left);
      }

      // Add RIGHT only if exists.
      if (rightEnd > centerRight) {
        final LongRange right = new LongRange(centerRight + 1, rightEnd);
        complement.add(right);
      }

      return complement;
    }
  }

@Test
  public void testComplement() {
    // [2, 7] - [0, 1] = [2, 7]
    final Set<LongRange> complement1 = LongRangeUtils.getComplement(ORIGINAL, OUTSIDE);
    // The result should be ORIGINAL, and should not contain [0, 1]
    assertEquals(1, complement1.size());
    assertTrue(exists(ORIGINAL, complement1));
    assertFalse(exists(OUTSIDE, complement1));

    // [2, 7] - [2, 3] = [4, 7]
    final Set<LongRange> complement2 = LongRangeUtils.getComplement(ORIGINAL, SAME_EDGE_INSIDE);
    // The result should only consist of [4, 7].
    assertEquals(1, complement2.size());
    assertTrue(exists(new LongRange(4, 7), complement2));
    assertFalse(exists(SAME_EDGE_INSIDE, complement2));

    // [2, 7] - [1, 2] = [3, 7]
    final Set<LongRange> complement3 = LongRangeUtils.getComplement(ORIGINAL, SAME_EDGE_OUTSIDE);
    // The result should only consist of [3, 7].
    assertEquals(1, complement3.size());
    assertTrue(exists(new LongRange(3, 7), complement3));
    assertFalse(exists(SAME_EDGE_OUTSIDE, complement3));

    // [2, 7] - [4, 5] = [2, 3], [6, 7]
    final Set<LongRange> complement4 = LongRangeUtils.getComplement(ORIGINAL, INSIDE);
    assertEquals(2, complement4.size());
    // The result should consist of [2, 3], [6, 7]
    assertTrue(exists(new LongRange(2, 3), complement4));
    assertTrue(exists(new LongRange(6, 7), complement4));
    assertFalse(exists(INSIDE, complement4));
  }

@SuppressWarnings("unchecked")
  void onTableAccessReqMessage(final String srcId, final TableAccessMsg tableAccessMsg) {
    final long opId = tableAccessMsg.getOperationId();
    final TableAccessReqMsg innerMsg = tableAccessMsg.getTableAccessReqMsg();
    final String tableId = innerMsg.getTableId();

    LOG.log(Level.INFO, "The table access request (Table: {0}, opId: {1}, origId: {2}) has failed at {3}." +
            " Will try redirection.", new Object[] {tableId, opId, innerMsg.getOrigId(), srcId});

    try {
      final AllocatedTable table = tableManagerFuture.get().getAllocatedTable(tableId);
      final Injector injector = Tang.Factory.getTang().newInjector(table.getTableConfiguration().getConfiguration());
      final StreamingCodec keyCodec = injector.getNamedInstance(KeyCodec.class);

      final BlockPartitioner blockPartitioner = injector.getInstance(BlockPartitioner.class);
      final int blockId = blockPartitioner.getBlockId(keyCodec.decode(innerMsg.getDataKey().getKey().array()));

      while (true) {
        final String executorIdToSendMsg = table.getOwnerId(blockId);

        LOG.log(Level.INFO, "The table access request (Table: {0}, opId: {1}, origId: {2}) will be redirected to {3}.",
            new Object[] {tableId, opId, innerMsg.getOrigId(), executorIdToSendMsg});

        try {
          messageSenderFuture.get().sendTableAccessReqMsg(executorIdToSendMsg, opId, innerMsg);
          break;
        } catch (NetworkException e) {
          LOG.log(Level.WARNING, "NetworkException while sending a msg. Resend", e);
        }

        LOG.log(Level.INFO, "Wait {0} ms before resending a msg", RESEND_INTERVAL_MS);
        try {
          // may not sleep for RESEND_INTERVAL_MS due to interrupt
          Thread.sleep(RESEND_INTERVAL_MS);
        } catch (final InterruptedException e) {
          LOG.log(Level.FINEST, "Interrupted while waiting for ownership cache to be updated", e);
        }
      }

    } catch (TableNotExistException | InjectionException e) {
      LOG.log(Level.INFO, "Redirection of the table access request has failed.", e);
      throw new RuntimeException(e);
    }
  }

@SuppressWarnings("unchecked")
  @Test
  public void testFallback() throws InjectionException, NetworkException {
    final Codec codec = Tang.Factory.getTang().newInjector().getInstance(SerializableCodec.class);

    // Any operation will give the same results; GET is used here for simplicity.
    final TableAccessReqMsg getMsg = TableAccessReqMsg.newBuilder()
        .setOrigId(NON_OWNER_EXECUTOR_ID)
        .setOpType(OpType.GET)
        .setTableId(TABLE_ID)
        .setDataKey(
            DataKey.newBuilder()
                .setKey(ByteBuffer.wrap(codec.encode(KEY)))
                .build())
        .setDataValue(null)
        .build();

    final TableAccessMsg tableAccessMsg = TableAccessMsg.newBuilder()
        .setType(TableAccessMsgType.TableAccessReqMsg)
        .setOperationId(OP_ID)
        .setTableAccessReqMsg(getMsg)
        .build();

    // Assume that the executor "non-owner" has redirected the message since the executor
    // has no information regarding the table.
    fallbackManager.onTableAccessReqMessage(NON_OWNER_EXECUTOR_ID, tableAccessMsg);

    doAnswer(invocation -> {
      final Object[] arguments = invocation.getArguments();

      final String destId = (String) arguments[0];
      final long opId = (long) arguments[1];
      final TableAccessReqMsg tableAccessReqMsg = (TableAccessReqMsg) arguments[2];

      assertEquals("The original executor is different", NON_OWNER_EXECUTOR_ID, tableAccessReqMsg.getOrigId());
      assertEquals("The destination is different", OWNER_EXECUTOR_ID, destId);
      assertEquals("The op id is different", OP_ID, opId);
      assertEquals("The table id is different", TABLE_ID, tableAccessReqMsg.getTableId());
      return null;
    }).when(msgSender).sendTableAccessReqMsg(anyString(), anyLong(), any(TableAccessReqMsg.class));
  }

@Override
  public boolean removeVertex(final V v) {
    final Set<V> neighbors = adjacent.remove(v);
    if (neighbors != null) {
      inDegrees.remove(v);
      // update inDegrees of neighbor vertices
      // and update rootVertices
      for (final V neighbor : neighbors) {
        final int inDegree = inDegrees.get(neighbor) - 1;
        inDegrees.put(neighbor, inDegree);
        if (inDegree == 0) {
          rootVertices.add(neighbor);
        }
      }
      rootVertices.remove(v);
      numVertices--;
      return true;
    } else {
      LOG.log(Level.WARNING, "The vertex {0} does exists", v);
      return false;
    }
  }

