public static boolean isHexLiteral(String numericLiteral) {
        for (int i = 0; i < numericLiteral.length(); i++) {
            char c = numericLiteral.charAt(i);
            if (c == 'p' || c == 'P') {
                return true;
            }
        }
        return false;
    }

