@Override
    public void execute() {
        //User notification of using an experimental tool
        outStream.println(OpenApiMesseges.EXPERIMENTAL_FEATURE);

        CodeGenerator generator = new CodeGenerator();

        List<String> tag = new ArrayList<>();
        List<String> operation = new ArrayList<>();
        Filter filter = new Filter(tag, operation);
        tag.add("pet");
        operation.add("operation");
        //Check if cli help argument is present
        if (helpFlag) {
            String commandUsageInfo = BLauncherCmd.getCommandUsageInfo(getName());
            outStream.println(commandUsageInfo);
            return;
        }

        //Check if a module name is present
        if (moduleArgs == null || moduleArgs.size() < 2) {
            throw LauncherUtils.createLauncherException(GEN_SERVICE_MODULE_ARGS_REQUIRED);
        } else {
            if (moduleArgs.get(0).trim().isEmpty()) {
                throw LauncherUtils.createLauncherException(GEN_SERVICE_MODULE_REQUIRED);
            } else if (moduleArgs.get(1).trim().isEmpty()) {
                throw LauncherUtils.createLauncherException(GEN_SERVICE_SERVICE_NAME_REQUIRED);
            }
        }

        //Check if an OpenApi definition is provided
        if (argList == null) {
            throw LauncherUtils.createLauncherException("An OpenApi definition file is required to generate the " +
                    "service. \nE.g: ballerina openapi gen-service " + moduleArgs.get(0) + ":"
                    + moduleArgs.get(1) + " <OpenApiContract>");
        }

        final Path projectRoot = ProjectDirs.findProjectRoot(Paths.get(executionPath));
        if (projectRoot == null) {
            throw LauncherUtils.createLauncherException(GEN_SERVICE_PROJECT_ROOT);
        }
        final Path sourceDirectory = projectRoot.resolve("src");
        final Path moduleDirectory = sourceDirectory.resolve(moduleArgs.get(0));
        final Path resourcesDirectory = Paths.get(moduleDirectory + "/resources");
        final Path testsDirectory = Paths.get(moduleDirectory + "/tests");
        final File openApiFile = new File(argList.get(0));
        final String openApiFilePath = openApiFile.getPath();
        Path resourcePath = Paths.get(resourcesDirectory + "/" + openApiFile.getName());
        Path relativeResourcePath = Paths.get("resources", openApiFile.getName());

        //Check provided OpenApi file is a valid and existing one
        if (Files.notExists(Paths.get(openApiFilePath))) {
            throw LauncherUtils.createLauncherException("Could not resolve a valid OpenApi" +
                    " contract in " + openApiFilePath);
        }

        if (Files.notExists(moduleDirectory)) {
            try {
                Files.createDirectory(moduleDirectory);
            } catch (IOException e) {
                throw LauncherUtils.createLauncherException(MODULE_DIRECTORY_EXCEPTION + "\n"
                        + e.getLocalizedMessage());
            }
        }

        File moduleMd = new File(moduleDirectory + "/Module.md");
        if (!moduleMd.exists()) {
            try {
                boolean createMd = true;
                createMd = moduleMd.createNewFile();

                if (!createMd) {
                    throw LauncherUtils.createLauncherException(MODULE_MD_EXCEPTION);
                }
            } catch (IOException e) {
                throw LauncherUtils.createLauncherException(MODULE_MD_EXCEPTION + "\n"
                        + e.getLocalizedMessage());
            }
        }

        // Check for tests folder in ballerina module root
        if (Files.notExists(testsDirectory)) {
            try {
                Files.createDirectory(testsDirectory);
            } catch (IOException e) {
                throw LauncherUtils.createLauncherException(TESTS_DIRECTORY_EXCEPTION + "\n"
                        + e.getLocalizedMessage());
            }
        }

        if (skipBind) {
            try {
                resourcePath = Paths.get(openApiFile.getCanonicalPath());
            } catch (IOException e) {
                throw LauncherUtils.createLauncherException(e.getLocalizedMessage());
            }
        } else {
            // Check for resources folder in ballerina module root
            if (Files.notExists(resourcesDirectory)) {
                try {
                    Files.createDirectory(resourcesDirectory);
                } catch (IOException e) {
                    throw LauncherUtils.createLauncherException(RESOURCE_DIRECTORY_EXCEPTION + "\n"
                            + e.getLocalizedMessage());
                }
            }

            // If OpenAPI contract by the same name doesn't exist in the resource folder continue to copy.
            // Else throw an exception.
            if (Files.notExists(resourcePath)) {
                try {
                    Files.copy(Paths.get(openApiFilePath), resourcePath);
                } catch (IOException e) {
                    throw LauncherUtils.createLauncherException(e.getLocalizedMessage());
                }
            } else {
                throw LauncherUtils.createLauncherException(DEFINITION_EXISTS
                        + " " + resourcesDirectory);
            }
        }

        if (output.isEmpty()) {
            output = executionPath;
        }

        //Set source package for the generated service
        generator.setSrcPackage(moduleArgs.get(0));

        //TODO Fix relative path compiler plugin issue
        //Set relative path for contract path which will be printed on the generated service bal file
        //Path absPath = Paths.get(resourcePath.toString());
        //Path basePath = Paths.get(output);
        //Path pathRelative = basePath.relativize(absPath);

        try {
            generator.generateService(executionPath, resourcePath.toString(), relativeResourcePath.toString(),
                    moduleArgs.get(1), output, filter);
        } catch (IOException | BallerinaOpenApiException e) {
            throw LauncherUtils.createLauncherException("Error occurred when generating service for openapi " +
                    "contract at " + argList.get(0) + ". " + e.getMessage() + ".");
        }
    }

@Test(description = "Test openapi gen-service for successful service generation with inline request body type",
            enabled = false)
    public void testInlineRequestBodyServiceGen() throws IOException {
        Path inlineYaml = RES_DIR.resolve(Paths.get("inline-request-body.yaml"));
        createBalProjectModule(petProject, "inlineModule");
        String[] args = {"inlineModule:inlineservice", inlineYaml.toString()};

        OpenApiGenServiceCmd cmd = new OpenApiGenServiceCmd(printStream, petProject.getBalProjectPath().toString());
        new CommandLine(cmd).parseArgs(args);

        String output = "";
        try {
            cmd.execute();
        } catch (BLauncherException e) {
            output = e.getDetailedMessages().get(0);
        }

        Path expectedServiceFile = RES_DIR.resolve(Paths.get("expected_gen",
                "inline-request-expected.bal"));

        Stream<String> expectedServiceLines = Files.lines(expectedServiceFile);
        String expectedServiceContent = expectedServiceLines.collect(Collectors.joining("\n"));

        if (Files.exists(petProject.getResourcePath().resolve(inlineYaml.getFileName()))
                && Files.exists(petProject.getSrcPath().resolve("inlineModule").resolve("inlineservice.bal"))) {

            Stream<String> serviceLines = Files.lines(petProject.getSrcPath()
                    .resolve("inlineModule").resolve("inlineservice.bal"));
            String generatedService = serviceLines.collect(Collectors.joining("\n"));
            serviceLines.close();

            Pattern pattern = Pattern.compile("\\bcontract\\b: \"(.*?)\"");
            Matcher matcher = pattern.matcher(generatedService);
            matcher.find();

            String contractPath = "contract: " + "\"" + matcher.group(1)  + "\"";
            expectedServiceContent = expectedServiceContent.replaceAll("\\bcontract\\b: \"(.*?)\"",
                    Matcher.quoteReplacement(contractPath));
            expectedServiceLines.close();

            if (expectedServiceContent.trim().equals(generatedService.trim())) {
                Assert.assertTrue(true);
            } else {
                Assert.fail("Expected content and actual generated content is mismatched for: "
                        + inlineYaml.toString());
            }

        } else {
            Assert.fail("Service generation for inline request body type failed.");
        }
    }

public RollingHistogram(Clock clock, StatisticConfig statisticConfig) {
        this.clock = clock;
        this.statisticConfig = statisticConfig;
        int ageBuckets = (int) statisticConfig.getBuckets();
        ringBuffer = new DoubleRecorder[ageBuckets];
        for (int i = 0; i < ageBuckets; i++) {
            ringBuffer[i] = new DoubleRecorder(statisticConfig.getPercentilePrecision());
        }
        this.currentBucket = 0;
        this.lastRotateTimestampMillis = clock.getCurrentTime();
        this.durationBetweenRotatesMillis = statisticConfig.getTimeWindow().toMillis() / ageBuckets;
        intervalHistogram = new DoubleHistogram(statisticConfig.getPercentilePrecision());
        accumulatedHistogram = new DoubleHistogram(statisticConfig.getPercentilePrecision());
    }

@Test
    public void testRollingHistogram() {
        final AtomicInteger currentTime = new AtomicInteger(0);
        Clock clock = mock(Clock.class);
        when(clock.getCurrentTime()).then(invocationOnMock -> currentTime.get());
        Assert.assertEquals(clock.getCurrentTime(), 0);

        double[] percentiles = new double[]{0.0, 0.5, 0.75, 0.9, 0.98, 0.99, 0.999, 1.0};
        RollingHistogram histogram = new RollingHistogram(clock, StatisticConfig.builder()
                .percentiles(percentiles)
                .expiry(Duration.ofSeconds(4)).buckets(4).build());

        histogram.record(10);
        histogram.record(20);
        Snapshot snapshot = histogram.getSnapshot();
        Assert.assertEquals(percentileValue(snapshot, 0.0), 10.0, 1.0);
        Assert.assertEquals(percentileValue(snapshot, 1.0), 20.0, 1.0);
        Assert.assertEquals(snapshot.getMin(), 10.0, 1.0);
        Assert.assertEquals(snapshot.getMax(), 20.0, 1.0);

        currentTime.addAndGet(900);
        Assert.assertEquals(clock.getCurrentTime(), 900);

        histogram.record(30);
        histogram.record(40);

        snapshot = histogram.getSnapshot();
        Assert.assertEquals(percentileValue(snapshot, 0.0), 10.0, 1.0);
        Assert.assertEquals(percentileValue(snapshot, 1.0), 40.0, 1.0);
        Assert.assertEquals(snapshot.getMin(), 10.0, 1.0);
        Assert.assertEquals(snapshot.getMax(), 40.0, 1.0);

        currentTime.addAndGet(99);
        Assert.assertEquals(clock.getCurrentTime(), 999);

        histogram.record(9);
        histogram.record(60);

        snapshot = histogram.getSnapshot();
        Assert.assertEquals(percentileValue(snapshot, 0.0), 9.0, 1.0);
        Assert.assertEquals(percentileValue(snapshot, 1.0), 60.0, 1.0);
        Assert.assertEquals(snapshot.getMin(), 9.0, 1.0);
        Assert.assertEquals(snapshot.getMax(), 60.0, 1.0);

        currentTime.addAndGet(1);
        Assert.assertEquals(clock.getCurrentTime(), 1000);

        histogram.record(12);
        histogram.record(70);
        snapshot = histogram.getSnapshot();
        Assert.assertEquals(percentileValue(snapshot, 0.0), 9.0, 1.0);
        Assert.assertEquals(percentileValue(snapshot, 1.0), 70.0, 1.0);
        Assert.assertEquals(snapshot.getMin(), 9.0, 1.0);
        Assert.assertEquals(snapshot.getMax(), 70.0, 1.0);

        currentTime.addAndGet(1001);
        Assert.assertEquals(clock.getCurrentTime(), 2001);

        histogram.record(13);
        histogram.record(80);

        snapshot = histogram.getSnapshot();
        Assert.assertEquals(snapshot.getMin(), 9.0, 1.0);
        Assert.assertEquals(snapshot.getMax(), 80.0, 1.0);
        Assert.assertEquals(percentileValue(snapshot, 0.0), 9.0, 1.0);
        Assert.assertEquals(percentileValue(snapshot, 1.0), 80.0, 1.0);

        currentTime.addAndGet(1000);
        Assert.assertEquals(clock.getCurrentTime(), 3001);

        snapshot = histogram.getSnapshot();
        Assert.assertEquals(percentileValue(snapshot, 0.0), 9.0, 1.0);
        Assert.assertEquals(percentileValue(snapshot, 1.0), 80.0, 1.0);
        Assert.assertEquals(snapshot.getMin(), 9.0, 1.0);
        Assert.assertEquals(snapshot.getMax(), 80.0, 1.0);

        currentTime.addAndGet(999);
        Assert.assertEquals(clock.getCurrentTime(), 4000);

        snapshot = histogram.getSnapshot();
        Assert.assertEquals(percentileValue(snapshot, 0.0), 12.0, 1.0);
        Assert.assertEquals(percentileValue(snapshot, 1.0), 80.0, 1.0);
        Assert.assertEquals(snapshot.getMin(), 12.0, 1.0);
        Assert.assertEquals(snapshot.getMax(), 80.0, 1.0);

        histogram.record(1);
        histogram.record(200);

        snapshot = histogram.getSnapshot();
        Assert.assertEquals(percentileValue(snapshot, 0.0), 1.0, 1.0);
        Assert.assertEquals(percentileValue(snapshot, 1.0), 200.0, 1.0);
        Assert.assertEquals(snapshot.getMin(), 1.0, 1.0);
        Assert.assertEquals(snapshot.getMax(), 200.0, 1.0);

        currentTime.addAndGet(10000);
        Assert.assertEquals(clock.getCurrentTime(), 14000);

        snapshot = histogram.getSnapshot();
        Assert.assertEquals(percentileValue(snapshot, 0.0), 0.0, 0.0);
        Assert.assertEquals(percentileValue(snapshot, 1.0), 0.0, 0.0);
        Assert.assertEquals(snapshot.getMin(), 0.0, 1.0);
        Assert.assertEquals(snapshot.getMax(), 0.0, 1.0);

        histogram.record(3);

        currentTime.addAndGet(3999);
        Assert.assertEquals(clock.getCurrentTime(), 17999);

        snapshot = histogram.getSnapshot();
        Assert.assertEquals(percentileValue(snapshot, 0.0), 3.0, 1.0);
        Assert.assertEquals(percentileValue(snapshot, 1.0), 3.0, 1.0);
        Assert.assertEquals(snapshot.getMin(), 3.0, 1.0);
        Assert.assertEquals(snapshot.getMax(), 3.0, 1.0);

        currentTime.addAndGet(1);
        Assert.assertEquals(clock.getCurrentTime(), 18000);

        snapshot = histogram.getSnapshot();
        Assert.assertEquals(percentileValue(snapshot, 0.0), 0.0, 0.0);
        Assert.assertEquals(percentileValue(snapshot, 1.0), 0.0, 0.0);
        Assert.assertEquals(snapshot.getMin(), 0.0, 1.0);
        Assert.assertEquals(snapshot.getMax(), 0.0, 1.0);
    }

@Override
    public void execute() {
        // If help flag is given print the help message.
        if (helpFlag) {
            String commandUsageInfo = BLauncherCmd.getCommandUsageInfo(ADD_COMMAND);
            errStream.println(commandUsageInfo);
            return;
        }

        if (list) {
            errStream.println("Available templates:");
            for (String template : getTemplates()) {
                errStream.println("    - " + template);
            }
            // Get templates from balos
            for (String template : getBaloTemplates()) {
                errStream.println("    - " + template);
            }
            return;
        }

        // Check if inside a project repo
        Path projectPath = ProjectDirs.findProjectRoot(userDir);
        if (null == projectPath) {
            CommandUtil.printError(errStream,
                    "not a ballerina project (or any parent up to mount point)\n" +
                            "You should run this command inside a ballerina project", null, false);
            return;
        }

        // Check if an argument is provided
        if (null == argList) {
            CommandUtil.printError(errStream,
                    "The following required arguments were not provided:\n" +
                            "    <module-name>",
                    "ballerina add <module-name> [-t|--template <template-name>]",
                    true);
            return;
        }

        // Check if more then one argument is provided
        if (!(1 == argList.size())) {
            CommandUtil.printError(errStream,
                    "too many arguments.",
                    "ballerina add <project-name>",
                    true);
            return;
        }

        // Check if the provided arg a valid module name
        String moduleName = argList.get(0);
        boolean matches = RepoUtils.validatePkg(moduleName);
        if (!matches) {
            CommandUtil.printError(errStream,
                    "Invalid module name : '" + moduleName + "' :\n" +
                            "Module name can only contain alphanumerics, underscores and periods " +
                            "and the maximum length is 256 characters",
                    null,
                    false);
            return;
        }

        // Check if the module already exists
        if (ProjectDirs.isModuleExist(projectPath, moduleName)) {
            CommandUtil.printError(errStream,
                    "A module already exists with the given name : '" + moduleName + "' :\n" +
                            "Existing module path "
                            + projectPath.resolve(ProjectDirConstants.SOURCE_DIR_NAME).resolve(moduleName),
                    null,
                    false);
            return;
        }

        // Check if the template exists
        if (!getTemplates().contains(template) && findBaloTemplate(template) == null) {
            CommandUtil.printError(errStream,
                    "Template not found, use `ballerina add --list` to view available templates.",
                    null,
                    false);
            return;
        }

        try {
            createModule(projectPath, moduleName, template);
        } catch (ModuleCreateException e) {
            CommandUtil.printError(errStream,
                    "Error occurred while creating module : " + e.getMessage(),
                    null,
                    false);
            return;
        }

        errStream.println("Added new ballerina module at '" + userDir.relativize(projectPath
                .resolve(ProjectDirConstants.SOURCE_DIR_NAME)
                .resolve(moduleName)) + "'");
    }

