public static boolean checkClassAndMethodForPattern(final String juteTest, final String className, final String methofName, final boolean onlyClass) {
    if (className == null || (!onlyClass && methofName == null)) {
      return false;
    }
    if (juteTest == null || juteTest.isEmpty()) {
      return true;
    }
    final String classPattern;
    final String methodPattern;
    final int methodPrefix = juteTest.indexOf('#');
    if (methodPrefix < 0) {
      classPattern = juteTest;
      methodPattern = "*";
    }
    else {
      classPattern = juteTest.substring(0, methodPrefix);
      methodPattern = juteTest.substring(methodPrefix + 1);
    }
    return FilenameUtils.wildcardMatch(className, classPattern) && (onlyClass ? true : FilenameUtils.wildcardMatch(methofName, methodPattern));
  }

@Test
  public void testCheckClassAndMethodForPattern(){
    assertFalse(Utils.checkClassAndMethodForPattern(null, null, null, false));
    assertFalse(Utils.checkClassAndMethodForPattern(null, null, null, true));
    assertFalse(Utils.checkClassAndMethodForPattern(null, null, "", false));
    assertFalse(Utils.checkClassAndMethodForPattern(null, "", null, false));
    assertFalse(Utils.checkClassAndMethodForPattern("", null, null, false));

    assertTrue(Utils.checkClassAndMethodForPattern(null, "", null, true));
    assertTrue(Utils.checkClassAndMethodForPattern(null, "", "", false));
    assertTrue(Utils.checkClassAndMethodForPattern(null, "", "", false));

    assertTrue(Utils.checkClassAndMethodForPattern("com.package.Klazz", "com.package.Klazz", "Some", false));
    assertTrue(Utils.checkClassAndMethodForPattern("com.package.Klazz#*", "com.package.Klazz", "Some", false));
    assertTrue(Utils.checkClassAndMethodForPattern("*", "com.package.Klazz", "Some", false));
    assertTrue(Utils.checkClassAndMethodForPattern("*#*", "com.package.Klazz", "Some", false));
    assertTrue(Utils.checkClassAndMethodForPattern("*#So*", "com.package.Klazz", "Some", false));

    assertFalse(Utils.checkClassAndMethodForPattern("com.package.Klazzz", "com.package.Klazz", "Some", false));
    assertFalse(Utils.checkClassAndMethodForPattern("com.package.Klazz#SomE", "com.package.Klazz", "Some", false));
    assertFalse(Utils.checkClassAndMethodForPattern("com.package.Klazz#Som??", "com.package.Klazz", "Some", false));
  }

public static String toStandardJavaClassName(final String rootPath, final String classFilePath) {
    if (rootPath.length() >= classFilePath.length()) {
      throw new Error("Unexpected situation #112321223 (" + rootPath + " >= " + classFilePath + ')');
    }
    String diff = classFilePath.substring(rootPath.length()).replace('\\', '.').replace('/', '.');
    if (diff.toLowerCase(Locale.ENGLISH).endsWith(".class")) {
      diff = diff.substring(0, diff.length() - ".class".length());
    }
    return diff;
  }

