@Test
    public void testHandleFileSaved() throws IOException {
        File newFolder1 = root.newFolder();
        File catFile = addFileToFolder(newFolder1, "Cat.groovy",
                "class Cat {\n"
                        + "}\n");
        File catChangedFile =
                changedOutput.getRoot().toPath().resolve(newFolder1.getName()).resolve(catFile.getName()).toFile();

        GroovyWorkspaceCompiler compiler = createGroovyWorkspaceCompiler();
        // Compile
        assertEquals(NO_ERRORS, compiler.compile(ImmutableSet.of()));

        // Assert the original file is in the compilation unit
        assertSingleSourceFileUri(catFile, compiler.get().iterator());

        // First change
        compiler.handleFileChanged(catFile.toURI(),
                Lists.newArrayList(new TextDocumentContentChangeEvent(Ranges.createRange(0, 6, 0, 9), 3, "Dog")));
        // Assert file contents
        assertEquals("class Cat {\n}\n", FileUtils.readFileToString(catFile));
        assertEquals("class Dog {\n}\n", FileUtils.readFileToString(catChangedFile));

        // Re-compile
        assertEquals(NO_ERRORS, compiler.compile(ImmutableSet.of()));

        // Assert the changed file is in the compilation unit
        assertSingleSourceFileUri(catChangedFile, compiler.get().iterator());

        // Call handleClose
        compiler.handleFileSaved(catFile.toURI(), Optional.absent());
        // Assert things reloaded
        assertEquals("class Cat {\n}\n", FileUtils.readFileToString(catFile));
        assertEquals("class Cat {\n}\n", FileUtils.readFileToString(catChangedFile));

        // Re-compile
        assertEquals(NO_ERRORS, compiler.compile(ImmutableSet.of()));

        // Assert new symbols persist
        // Assert the original file is in the compilation unit
        assertSingleSourceFileUri(catChangedFile, compiler.get().iterator());
    }

@Override
    public CompletableFuture<InitializeResult> initialize(InitializeParams params) {
        logger.debug("Initializing Groovy Language Server");
        workspaceRoot = Paths.get(Optional.ofNullable(params.getRootUri())
                .map(URI::create)
                .map(URI::normalize)
                .orElseGet(() -> Optional.ofNullable(params.getRootPath())
                        .map(Paths::get)
                        .map(Path::toAbsolutePath)
                        .map(Path::normalize)
                        .orElseThrow(() ->
                                new IllegalArgumentException("Either rootUri or rootPath must be set")).toUri()));
        logger.debug("Resolved workspace root: {}", workspaceRoot);

        CompletionOptions completionOptions = new CompletionOptions(false, ImmutableList.of("."));
        ServerCapabilities serverCapabilities = new ServerCapabilities();
        serverCapabilities.setCompletionProvider(completionOptions);
        serverCapabilities.setTextDocumentSync(TextDocumentSyncKind.Incremental);
        serverCapabilities.setDocumentSymbolProvider(true);
        serverCapabilities.setWorkspaceSymbolProvider(true);
        serverCapabilities.setDocumentSymbolProvider(true);
        serverCapabilities.setReferencesProvider(true);
        serverCapabilities.setDefinitionProvider(true);
        InitializeResult initializeResult = new InitializeResult(serverCapabilities);

        targetDirectory = Files.createTempDir().toPath();
        changedFilesDirectory = Files.createTempDir().toPath();

        GroovyWorkspaceCompiler compiler =
                GroovyWorkspaceCompiler.of(targetDirectory, workspaceRoot, changedFilesDirectory);
        TreeParser parser =
                GroovyTreeParser.of(compiler, workspaceRoot,
                        new WorkspaceUriSupplier(workspaceRoot, changedFilesDirectory));
        DefaultCompilerWrapper groovycWrapper = new DefaultCompilerWrapper(compiler, parser);
        state.setCompilerWrapper(groovycWrapper);

        return CompletableFuture.completedFuture(initializeResult);
    }

