        Pattern pattern = getQueryPattern(query);
        return indexer.getFileSymbols().values().stream().flatMap(Collection::stream)
                .filter(symbol -> pattern.matcher(symbol.getName()).matches())
                .collect(Collectors.toSet());
    }

