@Test
    public void sourceCodeLinePositions() throws Exception {
        TemplateParser parser = createParser();
        File f = findTemplate("rocker/parser/PosInFile.rocker.html");

        TemplateModel model = parser.parse(f);

        Comment firstComment = model.getUnit(0, Comment.class);
        Assert.assertEquals(1, firstComment.getSourceRef().getBegin().getLineNumber());
        Assert.assertEquals(1, firstComment.getSourceRef().getBegin().getPosInLine());
        Assert.assertEquals(0, firstComment.getSourceRef().getBegin().getPosInFile());
        Assert.assertEquals(5, firstComment.getSourceRef().getCharLength());

        // euro char and whitespace
        PlainText plainText = model.getUnit(1, PlainText.class);
        //log.info("plain text [{}]", StringEscapeUtils.escapeJava(plainText.getText()));
        Assert.assertEquals(1, plainText.getSourceRef().getBegin().getLineNumber());
        Assert.assertEquals(6, plainText.getSourceRef().getBegin().getPosInLine());
        Assert.assertEquals(5, plainText.getSourceRef().getBegin().getPosInFile());

        // length is actually number of chars not bytes!
        // stupid ANTLR treats newlines differently on each platform... not preserving
        // what is actually in the underlying template file (annoying)
        // http://www.antlr3.org/pipermail/stringtemplate-interest/2012-October/004013.html
        // so on nix this will be 7, but on windows it'll be 11
        int charLength = plainText.getSourceRef().getCharLength();
        Assert.assertTrue((charLength == 7 || charLength == 11));

        Assert.assertEquals("\n\n\u20AC\n\n  ", plainText.getText());

        // @title in file
        ValueExpression valueExpr = model.getUnit(2, ValueExpression.class);
        //log.info("value expr [{}]", StringEscapeUtils.escapeJava(valueExpr.getSourceRef().getText()));
        Assert.assertEquals(5, valueExpr.getSourceRef().getBegin().getLineNumber());
        Assert.assertEquals(3, valueExpr.getSourceRef().getBegin().getPosInLine());

        // again, stupid ANTLR and newlines (adding \r's when they don't exist)
        int posInFile = valueExpr.getSourceRef().getBegin().getPosInFile();
        Assert.assertTrue(posInFile == 12 || posInFile == 16);

        Assert.assertEquals(6, valueExpr.getSourceRef().getCharLength());
    }

static public ForStatement parse(String statement) throws TokenException
    {
        if (!statement.startsWith("(")) {
            throw new TokenException("For block does not start with parenthese");
        }

        if (!statement.endsWith(")")) {
            throw new TokenException("For block does not end with parenthese");
        }

        // chomp parentheses
        statement = statement.substring(1, statement.length() - 1);

        if (statement.contains(";")) {
            String[] generalParts = statement.split(";");
            if (generalParts.length != 3) {
                throw new TokenException("For block has invalid general form [e.g. for (initialization; termination; increment) {]");
            }

            List<String> parts = new ArrayList<>();
            for (String s : generalParts) {
                parts.add(s.trim());
            }

            return new ForStatement(parts);
        }

        if (statement.contains(":")) {
            String[] enhancedParts = statement.split(":");
            if (enhancedParts.length != 2) {
                throw new TokenException("For block has invalid enhanced form [e.g. for (item : items) {]");
            }

            String argsPart = enhancedParts[0].trim();

            // verify its not an empty string
            if (argsPart.equals("")) {
                throw new TokenException("For block with enhanced form contains an empty string for arguments part (e.g. for (arg : list)");
            }

            // a single argument does not need parenthese
            boolean hasParenthese = false;

            if (argsPart.startsWith("(")) {
                if (!argsPart.endsWith(")")) {
                    throw new TokenException("For block with enhanced form contains invalid arguments section (closing parenthese not found)");
                }
                hasParenthese = true;

                // strip starting/closing parenthese
                argsPart = argsPart.substring(1, argsPart.length() - 1);
            }

            // parse underlying arguments
            List<JavaVariable> arguments = null;
            try {
                arguments = JavaVariable.parseList(argsPart);
            } catch (TokenException e) {
                throw new TokenException(e.getMessage());
            }

            // anything of more than 1 argument requires parenthese
            if (arguments.size() > 1 && !hasParenthese) {
                throw new TokenException("For block with enhanced form contains invalid arguments section (more than 1 argument must be enclosed with parenthese e.g. (k,v))");
            }

            // at most 3 arguments supported
            if (arguments.size() > 3) {
                throw new TokenException("For block with enhanced form contains " + arguments.size() + " arguments (at most 3 supported)");
            }

            String valuePart = enhancedParts[1].trim();

            // verify its not an empty string
            if (valuePart.equals("")) {
                throw new TokenException("For block with enhanced form contains an empty string for value part (e.g. for (item : value)");
            }

            return new ForStatement(arguments, valuePart.trim());
        }

        throw new TokenException("For block appears to be invalid (neither general or enhanced form detected)");
    }

@Test
    public void startAndEndingParenthese() throws Exception {

        try {
            // missing starting parenthese
            ForStatement.parse("int x = 0; x < users.size(); x++");
            Assert.fail("Expected exception");
        } catch (TokenException e) {
            // expected
        }

        try {
            // missing ending parenthese
            ForStatement.parse("  (int x = 0; x < users.size(); x++");
            Assert.fail("Expected exception");
        } catch (TokenException e) {
            // expected
        }

        try {
            // neither form detected
            ForStatement.parse("( )");
            Assert.fail("Expected exception");
        } catch (TokenException e) {
            // expected
        }
    }

public static <T extends SpecificRecord, K, Q> AvroBase<T, K> createAvroBase(Module module, Class<? extends AvroBase> clazz, final AvroFormat format) throws AvroBaseException {
