public void registerClasses(Kryo kryo) {

    String classesString = System.getProperty(KITE_AVRO_CLASSES);

    if (classesString == null || classesString.isEmpty()) {
      LOGGER.info("No Avro classes set in property {}.", KITE_AVRO_CLASSES);
    } else {

      LOGGER.info("Registring Avro classes {}.", classesString);

      String[] classes = classesString.split(",");

      for(String className: classes) {

        Class cls = null;
        try {
          cls = Thread.currentThread().getContextClassLoader().loadClass(className);
        } catch (ClassNotFoundException e) {
          throw new AppException(e);
        }

        kryo.register(cls, new KryoAvroSerializer(cls));
      }
    }
  }

@Test
  public void testRegistrator() {

    System.setProperty(KryoAvroRegistrator.KITE_AVRO_CLASSES, SmallEvent.class.getName());

    Kryo kryo = new Kryo();

    new KryoAvroRegistrator().registerClasses(kryo);

    Serializer serializer = kryo.getSerializer(SmallEvent.class);

    Assert.assertNotNull(serializer);

    Output output = new Output(1024);

    SmallEvent testEvent = SmallEvent.newBuilder()
        .setUserId(1)
        .setSessionId("123")
        .build();

    kryo.writeObject(output, testEvent);

    byte [] bytes = output.toBytes();

    Input input = new Input(bytes);

    SmallEvent result = kryo.readObject(input, SmallEvent.class);

    Assert.assertEquals(testEvent, result);
  }

@VisibleForTesting
  static final String qualifyUri(Configuration conf, String uriTemplate) {

    // Create a URI that doesn't include the initial view: or dataset: prefix
    // and excludes the parameters.
    URI baseURI = URI.create(uriTemplate.substring(uriTemplate.indexOf(':') + 1, uriTemplate.indexOf('?')));

    // We only need to qualify hive URIs that
    // are not already qualified with a host,
    // when there is a Hive metastore URI configured.
    if (!"hive".equals(baseURI.getScheme()) ||
        baseURI.getHost() != null ||
        conf.get(HIVE_METASTORE_URIS) == null) {

      return uriTemplate;
    }

    String[] uris = conf.get(HIVE_METASTORE_URIS).split(",");

    if (uris.length == 0) {
      return uriTemplate;
    }

    URI hiveUri = URI.create(uris[0]);

    String host = hiveUri.getHost();
    int port = hiveUri.getPort();

    // Recreate a template this is qualified with host and port information.
    String prefix = uriTemplate.startsWith("dataset") ? "dataset:hive:" :
        "view:hive:";

    String rest = uriTemplate.substring(prefix.length());

    return prefix + "//" + host + ":" + port + "/" + rest;
  }

@Test
  public void testQualifyHiveUri() {
    String template = "view:hive:example/events" +
        "?year=${YEAR}&month=${MONTH}&day=${DAY}&hour=${HOUR}&minute=${MINUTE}";

    Configuration conf = new Configuration();
    conf.set("hive.metastore.uris", "thrift://examplehost:1234");

    String qualified = OozieScheduling.qualifyUri(conf, template);

    assertEquals("view:hive://examplehost:1234/example/events?year=${YEAR}" +
        "&month=${MONTH}&day=${DAY}&hour=${HOUR}&minute=${MINUTE}",
        qualified);
  }

@VisibleForTesting
  static final String qualifyUri(Configuration conf, String uriTemplate) {

    // Create a URI that doesn't include the initial view: or dataset: prefix
    // and excludes the parameters.
    URI baseURI = URI.create(uriTemplate.substring(uriTemplate.indexOf(':') + 1, uriTemplate.indexOf('?')));

    // We only need to qualify hive URIs that
    // are not already qualified with a host,
    // when there is a Hive metastore URI configured.
    if (!"hive".equals(baseURI.getScheme()) ||
        baseURI.getHost() != null ||
        conf.get(HIVE_METASTORE_URIS) == null) {

      return uriTemplate;
    }

    String[] uris = conf.get(HIVE_METASTORE_URIS).split(",");

    if (uris.length == 0) {
      return uriTemplate;
    }

    URI hiveUri = URI.create(uris[0]);

    String host = hiveUri.getHost();
    int port = hiveUri.getPort();

    // Recreate a template this is qualified with host and port information.
    String prefix = uriTemplate.startsWith("dataset") ? "dataset:hive:" :
        "view:hive:";

    String rest = uriTemplate.substring(prefix.length());

    return prefix + "//" + host + ":" + port + "/" + rest;
  }

