public static LocalTime getDicomTime(String time) {
        if (StringUtil.hasText(time)) {
            try {
                return LocalTime.parse(time.trim(), DICOM_TIME);
            } catch (Exception e) {
                try {
                    StringBuilder buf = new StringBuilder(8);
                    // Try to fix old format HH:MM:SS.frac (prior DICOM3.0)
                    time.chars().filter(i -> ':' != (char) i).forEachOrdered(i -> buf.append((char) i));
                    return LocalTime.parse(buf.toString().trim(), DICOM_TIME);
                } catch (Exception e1) {
                    LOGGER.error("Parse DICOM time", e1); //$NON-NLS-1$
                }
            }
        }
        return null;
    }

@Test
    public void testGetDicomTime() throws Exception {
        LocalTime time = TagD.getDicomTime("070907.0705 "); //$NON-NLS-1$
        assertEquals(LocalTime.of(7, 9, 7, 70_500_000), time);

        time = TagD.getDicomTime("10"); //$NON-NLS-1$
        assertEquals(LocalTime.of(10, 0), time);

        time = TagD.getDicomTime("1010"); //$NON-NLS-1$
        assertEquals(LocalTime.of(10, 10), time);

        time = TagD.getDicomTime("021 "); //$NON-NLS-1$
        assertEquals(null, time);

        // Does not support leap second:
        // http://stackoverflow.com/questions/30984599/how-does-the-oracle-java-jvm-know-a-leap-second-is-occurring
        // time = TagUtil.getDicomTime("235960");
        // assertEquals(LocalTime.of(23, 59, 60), time);

        time = TagD.getDicomTime("07:09:07.0705 "); //$NON-NLS-1$
        assertEquals(LocalTime.of(7, 9, 7, 70_500_000), time);
    }

public static String getStringFromDicomElement(Attributes dicom, int tag) {
        if (dicom == null || !dicom.containsValue(tag)) {
            return null;
        }

        String[] s = dicom.getStrings(tag);
        if (s == null || s.length == 0) {
            return null;
        }
        if (s.length == 1) {
            return s[0];
        }
        StringBuilder sb = new StringBuilder(s[0]);
        for (int i = 1; i < s.length; i++) {
            sb.append("\\" + s[i]); //$NON-NLS-1$
        }
        return sb.toString();
    }

