public char getNext(){
		if(index == chars.length()) return '\0';
		char ret = chars.charAt(index);
		if(ret <= '\1'){
			if(ret == '\0'){
				return ret;
			} else{
				int i = chars.charAt(index + 1);
				i += chars.charAt(index + 2) << 16;
				index = i;
				ret = chars.charAt(index);
			}
		}
		index++;
		return ret;
	}

