    interfaceBuilder.addParametrizedMethodAnnotation(
        eq("getStringList"), eq("Returns"), eq("arrayStringProperty"));

    interfaceBuilder.addParametrizedMethodAnnotation(
        eq("getStringList"), eq("ReturnTypeParameter"), eq("{String.class}"));

