@Test
    public void testSchema() throws Exception {
        // No type
        Over func = new Over();
        Schema in = Schema.generateNestedSchema(DataType.BAG, DataType.INTEGER);
        Schema out = func.outputSchema(in);
        assertEquals("{{NULL}}", out.toString());

        // chararray
        func = new Over("chararray");
        in = Schema.generateNestedSchema(DataType.BAG, DataType.INTEGER);
        out = func.outputSchema(in);
        assertEquals("{org.apache.pig.piggybank.evaluation.over_1: {result: chararray}}", out.toString());

        // int
        func = new Over("Int");
        in = Schema.generateNestedSchema(DataType.BAG, DataType.INTEGER);
        out = func.outputSchema(in);
        assertEquals("{org.apache.pig.piggybank.evaluation.over_2: {result: int}}", out.toString());

        // double
        func = new Over("DOUBLE");
        in = Schema.generateNestedSchema(DataType.BAG, DataType.INTEGER);
        out = func.outputSchema(in);
        assertEquals("{org.apache.pig.piggybank.evaluation.over_3: {result: double}}", out.toString());

        // named 
        func = new Over("bob:chararray");
        in = Schema.generateNestedSchema(DataType.BAG, DataType.INTEGER);
        out = func.outputSchema(in);
        assertEquals("{org.apache.pig.piggybank.evaluation.over_4: {bob: chararray}}", out.toString());
    }

public Map<String,String> getPeers() {
    Map<String,String> peers = new HashMap<>();

    // Get the defined peers and what ReplicaSystem impl they're using
    for (Entry<String,String> property : context.getConfiguration()
        .getAllPropertiesWithPrefix(Property.REPLICATION_PEERS).entrySet()) {
      String key = property.getKey();
      // Filter out cruft that we don't want
      if (!key.startsWith(Property.REPLICATION_PEER_USER.getKey())
          && !key.startsWith(Property.REPLICATION_PEER_PASSWORD.getKey())
          && !key.startsWith(Property.REPLICATION_PEER_KEYTAB.getKey())) {
        String peerName = property.getKey().substring(Property.REPLICATION_PEERS.getKey().length());
        Entry<String,String> entry;
        try {
          entry = factory.parseReplicaSystemConfiguration(property.getValue());
        } catch (Exception e) {
          log.warn("Could not instantiate ReplicaSystem for {} with configuration {}",
              property.getKey(), property.getValue(), e);
          continue;
        }

        peers.put(peerName, entry.getKey());
      }
    }

    return peers;
  }

