@Test
    public void testRemove() {
        ConcurrentPooledLinkedList<Integer> l = new ConcurrentPooledLinkedList<>(10000);
        for (int i = 0; i < 10000; i++) {
            l.addFirst(i);
        }
        l.iter();
        CountDownLatch latch = new CountDownLatch(1000);
        Thread[] removeThread = createAndStartThreads(new Runnable() {
            @Override
            public void run() {
                latch.countDown();
                try {
                    latch.await();
                } catch (InterruptedException e) {
                    throw new RuntimeException(e);
                }
                for (int i = 0; i < 10; i++) {
                    l.lock.lockWrite();
                    l.next();
                    l.remove();
                    l.lock.unlockWrite();
                }
            }
        }, 500);
        Thread[] removeLastThread = createAndStartThreads(new Runnable() {
            @Override
            public void run() {
                latch.countDown();
                try {
                    latch.await();
                } catch (InterruptedException e) {
                    throw new RuntimeException(e);
                }
                for (int i = 0; i < 10; i++) {
                    l.removeLast();
                }
            }
        }, 500);
        joinAll(removeThread, removeLastThread);
        assertEquals(0, l.size());
    }

