public static <A> void union(StringBuilder b, Iterable<A> xs, Effect2<A, StringBuilder> singleSql, boolean unionAll)
    {
        String joinClause = unionAll ? " UNION ALL " : " UNION ";
        for (A x : xs)
        {
            b.append("( ");
            singleSql.f(x, b);
            b.append(" )");
            b.append(joinClause);
        }

        int replaceIdx = b.length() - joinClause.length();
        if (replaceIdx < 1)
        {
            return;
        }
        b.replace(replaceIdx, b.length(), "");
    }

@Test
    public void union()
    {
        StringBuilder result = SqlStringUtils.<String>union(list(), (x, b) -> b.append("hi " + x), true);
        assertThat(result.toString(), is(""));

        result = SqlStringUtils.union(list("a"), (x, b) -> b.append("hi " + x), true);
        assertThat(result.toString(), is("( hi a )"));

        result = SqlStringUtils.union(list("a", "b", "c"), (x, b) -> b.append("hi " + x), false);
        assertThat(result.toString(), is("( hi a ) UNION ( hi b ) UNION ( hi c )"));

        result = SqlStringUtils.union(list("x", "y"), (x, b) -> b.append("hi " + x), true);
        assertThat(result.toString(), is("( hi x ) UNION ALL ( hi y )"));

    }

@Override
    public void close() {
        if (config.getBoolean(REPORTER_ENABLED)) {
            executor.submit(this);
        }
        executor.shutdown();
        try {
            // A 20 second timeout should be enough to finish the remaining tasks.
            if (executor.awaitTermination(20, TimeUnit.SECONDS)) {
                log.debug("Executor was shut down successfully.");
            } else {
                log.error("Timed out before executor was shut down! It's possible some metrics data were not sent out!");
            }
        } catch (InterruptedException e) {
