@Override
    public Map<String, Double> getActiveColumnsByToTV(String columnName, Interval interval,
                                                      int resultSize, boolean withBots) {

        EntityManager entityManager = entityManagerFactory.createEntityManager();
        CriteriaBuilder cb = entityManager.getCriteriaBuilder();
        CriteriaQuery<Tuple> query = cb.createTupleQuery();

        Root<T> from = query.from(type);

        ParameterExpression<DateTime> startDateParam = cb.parameter(DateTime.class);
        ParameterExpression<DateTime> endDateParam = cb.parameter(DateTime.class);
        Expression<Double> occurrences = from.get("occurrences").as(Double.class);

        // create total query
        Subquery<Long> totalQuery = query.subquery(Long.class);
        Root<T> totalFrom = totalQuery.from(type);
        totalQuery.select(cb.sum(totalFrom.get("occurrences")));
        Path<DateTime> totalMentionTime = totalFrom.get("mentionTime");

        List<Predicate> wherePredicates = Lists.newArrayListWithCapacity(3);
        wherePredicates.add(cb.greaterThanOrEqualTo(totalMentionTime, startDateParam));
        wherePredicates.add(cb.lessThan(totalMentionTime, endDateParam));
        if (!withBots) {
            wherePredicates.add(cb.equal(totalFrom.get("bot"), withBots));
        }
        totalQuery.where(wherePredicates.toArray(new Predicate[wherePredicates.size()]));

        // occurrences / total occurrences
        Expression<Double> ratio = cb.quot(cb.sum(occurrences), totalQuery).as(Double.class);

        Path<String> columnPath = from.get(columnName);
        query.multiselect(columnPath, ratio);
        Path<DateTime> mentionTime = from.get("mentionTime");

        wherePredicates = Lists.newArrayListWithCapacity(4);
        wherePredicates.add(cb.greaterThanOrEqualTo(mentionTime, startDateParam));
        wherePredicates.add(cb.lessThan(mentionTime, endDateParam));
        wherePredicates.add(cb.isNotNull(columnPath));
        if (!withBots) {
            wherePredicates.add(cb.equal(from.get("bot"), withBots));
        }

        query.where(wherePredicates.toArray(new Predicate[wherePredicates.size()]));
        query.groupBy(columnPath);
        query.orderBy(cb.desc(ratio));

        try {
            List<Tuple> resultList = entityManager.createQuery(query)
                                                  .setMaxResults(resultSize)
                                                  .setParameter(startDateParam, interval.getStart())
                                                  .setParameter(endDateParam, interval.getEnd())
                                                  .getResultList();
            // linked hashmap to preserve order
            Map<String, Double> result = Maps.newLinkedHashMap();
            for (Tuple tuple : resultList) {
                result.put(tuple.get(columnPath), tuple.get(ratio));
            }
            return result;
        } finally {
            closeEntityManager(entityManager);
        }
    }

@Test
    public void testGetActiveColumnsByToTV() throws Exception {
        DateTime end = DateTime.now();
        DateTime start = end.minusDays(1);

        underTest.persistValue(new EmojiEntity("u1", "r1", start.plusMillis(1), "a", 1, true));
        underTest.persistValue(new EmojiEntity("u1", "r2", start.plusMillis(2), "b", 1, false));
        underTest.persistValue(new EmojiEntity("u2", "r3", start.plusMillis(3), "c", 1, false));
        underTest.persistValue(new EmojiEntity("u1", "r4", start.plusMillis(4), "d", 1, false));
        underTest.persistValue(new EmojiEntity("u1", "r4", start.plusMillis(5), "e", 1, false));
        underTest.persistValue(new EmojiEntity("u1", "r5", start.plusMillis(6), "f", 1, false));
        underTest.persistValue(new EmojiEntity("u1", "r5", start.plusMillis(7), "g", 1, false));
        underTest.persistValue(new EmojiEntity("u1", "r5", start.plusMillis(8), "h", 1, false));

        Interval interval = new Interval(start, end);

        Map<String, Double> result = underTest.getActiveColumnsByToTV("roomName", interval, 100,
                                                                      true);
        assertEquals(5, result.size());
        assertEquals(0.375, result.get("r5").doubleValue(), 0);
        assertEquals(0.25, result.get("r4").doubleValue(), 0);
        assertEquals(0.125, result.get("r3").doubleValue(), 0);
        assertEquals(0.125, result.get("r2").doubleValue(), 0);
        assertEquals(0.125, result.get("r1").doubleValue(), 0);

        // check that they're in descending order
        double previousValue = Double.MIN_VALUE;
        for (double value : result.values()) {
            assertTrue(Double.compare(value, previousValue) > 0);
        }

        // exclude bots
        result = underTest.getActiveColumnsByToTV("roomName", interval, 100, false);
        assertEquals(4, result.size());
        assertEquals(0.428, result.get("r5").doubleValue(), 0.001);
        assertEquals(0.285, result.get("r4").doubleValue(), 0.001);
        assertEquals(0.142, result.get("r3").doubleValue(), 0.001);
        assertEquals(0.142, result.get("r2").doubleValue(), 0.001);

        // check with a smaller interval
        interval = new Interval(start.plusMillis(2), start.plusMillis(6));
        result = underTest.getActiveColumnsByToTV("roomName", interval, 100, true);
        assertEquals(3, result.size());
        Map.Entry<String, Double> firstEntry = result.entrySet().iterator().next();
        assertEquals("r4", firstEntry.getKey());
        assertEquals(0.5, firstEntry.getValue().doubleValue(), 0);
    }

