            if (p1 == null) {
                return -1;
            } else if (p2 == null) {
                return 1;
            } else {
                int depth1 = PathUtils.getDepth(p1);
                int depth2 = PathUtils.getDepth(p2);
                return (depth1 == depth2) ? p1.compareTo(p2) : Ints.compare(depth1, depth2);
            }
        }
    }

