      fail();
    } catch ( final NullPointerException ex ) {}
    try {
      WildcardFileFilter.checkRegionMatches( null, 1, "ABC" );
      fail();
    } catch ( final NullPointerException ex ) {}
    try {
      WildcardFileFilter.checkRegionMatches( null, 1, null );
      fail();
    } catch ( final NullPointerException ex ) {}
  }

