public StringRef trim() {
		int start = offset;
		int end = start + length;
		String str = refStr;

		while ((start < end) && (str.charAt(start) <= ' ')) {
			start++;
		}
		while ((start < end) && (str.charAt(end - 1) <= ' ')) {
			end--;
		}
		if ((start > offset) || (end < offset + length)) {
			return subString(str, start, end);
		}
		return this;
	}

