    assertEquals(2, a.getPage());

    a.dataProvided(TestItem.range(20, 30));

    assertEquals("p.20", a.get(20).toString());
    assertEquals("p.29", a.get(29).toString());
    assertNull(a.get(19));
    assertNull(a.get(30));
