private static byte[] encryptDecrypt(byte[] content, Key key, int mode)
			throws CryptoException {
		try {
			Cipher cipher = Cipher.getInstance("RSA");
			cipher.init(mode, key);
			return cipher.doFinal(content);
		} catch (Exception e) {
			throw new CryptoException("error decrypting with RSA: "
					+ e.getMessage());
		}
	}

@Test
	public void testEncryptDecrypt() throws CryptoException {
		KeyManager keyManager = KeyManager.getInstance();
		keyManager.generateKeyPair();

		byte[] content = new byte[] { 'a', 'b', 'c' };
		byte[] encrypted = RSAEncryption.encrypt(content,
				keyManager.getPublicKey());
		byte[] decrypted = RSAEncryption.decrypt(encrypted,
				keyManager.getPrivateKey());

		assertFalse(Arrays.equals(content, encrypted));
		assertArrayEquals(content, decrypted);
	}

public static BigDecimal fromVon(String number, Unit unit) {
        return fromVon(new BigDecimal(number), unit);
    }

@Test
    public void testFromWei() {
        assertThat(Convert.fromVon("21000000000000", Convert.Unit.VON),
                is(new BigDecimal("21000000000000")));
        assertThat(Convert.fromVon("21000000000000", Convert.Unit.KVON),
                is(new BigDecimal("21000000000")));
        assertThat(Convert.fromVon("21000000000000", Convert.Unit.MVON),
                is(new BigDecimal("21000000")));
        assertThat(Convert.fromVon("21000000000000", Convert.Unit.GVON),
                is(new BigDecimal("21000")));
        assertThat(Convert.fromVon("21000000000000", Convert.Unit.MICROLAT),
                is(new BigDecimal("21")));
        assertThat(Convert.fromVon("21000000000000", Convert.Unit.MILLILAT),
                is(new BigDecimal("0.021")));
        assertThat(Convert.fromVon("21000000000000", Convert.Unit.LAT),
                is(new BigDecimal("0.000021")));
        assertThat(Convert.fromVon("21000000000000", Convert.Unit.KLAT),
                is(new BigDecimal("0.000000021")));
        assertThat(Convert.fromVon("21000000000000", Convert.Unit.MLAT),
                is(new BigDecimal("0.000000000021")));
        assertThat(Convert.fromVon("21000000000000", Convert.Unit.GLAT),
                is(new BigDecimal("0.000000000000021")));
    }

public int run(String[] args) throws Exception {
        if (args.length != 2) {
            System.err.printf("Usage: %s [generic options] <input> <output>\n", getClass().getSimpleName());
            ToolRunner.printGenericCommandUsage(System.err);  //打印命令行应使用的参数信息
            return -1;
        }

        Job job = new Job(getConf(), "Max temperature");  //Job对象指定作业执行规范，用于控制整个作业的运行，并设置作业的名称,不设置的默认情况下作业名称是JAR文件名
        job.setJarByClass(getClass());  //不必明确指定jar文件的名称，在setJarByClass()方法中传递一个类即可，Hadoop利用这个类查找包含它的jar文件

        FileInputFormat.addInputPath(job, new Path(args[0]));  //定义输入数据的路径，多路径输入可以多次调用该方法
        FileOutputFormat.setOutputPath(job, new Path(args[1]));  //指定输出路径，指定的是reduce()函数输出文件的写入目录运行作业前输出目录不应该存在，否则会报错并拒绝运行作业

        job.setMapperClass(MaxTemperatureMapper.class);  //指定要使用的map类
        job.setCombinerClass(MaxTemperatureReducer.class);  //指定要使用的combiner类
        job.setReducerClass(MaxTemperatureReducer.class);  //指定要使用的reduce类

        job.setOutputKeyClass(Text.class);  //设置reduce()函数输出的键类型
        job.setOutputValueClass(IntWritable.class);  //设置reduce()函数输出的值类型

        return job.waitForCompletion(true) ? 0 : 1;  //提交作业并等待执行完成，具有一个唯一的标识用于指示是否已生成详细输出，标识为true时作业把其进度信息写到控制台，将true或false转换成程序退出代码0或1
    }

