                    return Integer.parseInt(numberFormatted);
                }
            } else {
                if (str.contains(".")) { // double
                    return Double.parseDouble(str);
                } else { // int
                    return Integer.parseInt(str);
                }
            }
        }
        throw new RuntimeException("To_Number function - wrong argument type: " + arg);
    }

