static ByteBuffer directBufferFor(long address, long offset, long len, boolean readOnly)
    {
        if (len > Integer.MAX_VALUE || len < 0L)
            throw new IllegalArgumentException();
        try
        {
            ByteBuffer bb = (ByteBuffer) unsafe.allocateInstance(readOnly ? DIRECT_BYTE_BUFFER_CLASS_R : DIRECT_BYTE_BUFFER_CLASS);
            unsafe.putLong(bb, DIRECT_BYTE_BUFFER_ADDRESS_OFFSET, address + offset);
            unsafe.putInt(bb, DIRECT_BYTE_BUFFER_CAPACITY_OFFSET, (int) len);
            unsafe.putInt(bb, DIRECT_BYTE_BUFFER_LIMIT_OFFSET, (int) len);
            bb.order(ByteOrder.BIG_ENDIAN);
            return bb;
        }
        catch (Error e)
        {
            throw e;
        }
        catch (Throwable t)
        {
            throw new RuntimeException(t);
        }
    }

@Test
    public void testDirectBufferFor() throws Exception
    {
        fillRandom();

        ByteBuffer buf = Uns.directBufferFor(((DirectBuffer) directBuffer).address(), 0, directBuffer.capacity(), false);

        for (int i = 0; i < CAPACITY; i++)
        {
            byte b = buf.get();
            byte d = directBuffer.get();
            assertEquals(b, d);

            assertEquals(buf.position(), directBuffer.position());
            assertEquals(buf.limit(), directBuffer.limit());
            assertEquals(buf.remaining(), directBuffer.remaining());
            assertEquals(buf.capacity(), directBuffer.capacity());
        }

        buf.clear();
        directBuffer.clear();

        while (buf.remaining() >= 8)
        {
            long b = buf.getLong();
            long d = directBuffer.getLong();
            assertEquals(b, d);

            assertEquals(buf.position(), directBuffer.position());
            assertEquals(buf.remaining(), directBuffer.remaining());
        }

        while (buf.remaining() >= 4)
        {
            int b = buf.getInt();
            int d = directBuffer.getInt();
            assertEquals(b, d);

            assertEquals(buf.position(), directBuffer.position());
            assertEquals(buf.remaining(), directBuffer.remaining());
        }

        for (int i = 0; i < CAPACITY; i++)
        {
            byte b = buf.get(i);
            byte d = directBuffer.get(i);
            assertEquals(b, d);

            if (i >= CAPACITY - 1)
                continue;

            char bufChar = buf.getChar(i);
            char dirChar = directBuffer.getChar(i);
            short bufShort = buf.getShort(i);
            short dirShort = directBuffer.getShort(i);

            assertEquals(bufChar, dirChar);
            assertEquals(bufShort, dirShort);

            if (i >= CAPACITY - 3)
                continue;

            int bufInt = buf.getInt(i);
            int dirInt = directBuffer.getInt(i);
            float bufFloat = buf.getFloat(i);
            float dirFloat = directBuffer.getFloat(i);

            assertEquals(bufInt, dirInt);
            assertEquals(bufFloat, dirFloat);

            if (i >= CAPACITY - 7)
                continue;

            long bufLong = buf.getLong(i);
            long dirLong = directBuffer.getLong(i);
            double bufDouble = buf.getDouble(i);
            double dirDouble = directBuffer.getDouble(i);

            assertEquals(bufLong, dirLong);
            assertEquals(bufDouble, dirDouble);
        }
    }

public static long printHeapHistogram(PrintStream out, int _maxLines) {
    long _totalBytes = 0;
    boolean _partial = false;
    try {
      Process proc = Runtime.getRuntime().exec(new String[]{
        getJmapExcutable(),
        "-histo",
        Long.toString(Utils.getPid())});
      InputStream in = proc.getInputStream();
      LineNumberReader r = new LineNumberReader(new InputStreamReader(in));
      String s;
      ByteArrayOutputStream buffer = new ByteArrayOutputStream();
      PrintStream ps = new PrintStream(buffer);
      while ((s = r.readLine()) != null) {
        if ( s.startsWith("Total")) {
          ps.println(s);
          String[] sa = s.split("\\s+");
          _totalBytes = Long.parseLong(sa[2]);
        } else if (r.getLineNumber() <= _maxLines) {
          ps.println(s);
        } else {
          if (!_partial) {
            ps.println("[ ... truncated ... ]");
          }
          _partial = true;
        }
      }
      r.close();
      in.close();
      ps.close();
      byte[] _histoOuptut = buffer.toByteArray();
      buffer = new ByteArrayOutputStream();
      ps = new PrintStream(buffer);
      ps.println("[Heap Histogram Live Objects] used=" + _totalBytes);
      ps.write(_histoOuptut);
      ps.println();
      ps.close();
      out.write(buffer.toByteArray());
    } catch (Exception ex) {
      System.err.println("ForcedGcMemoryProfiler: error attaching / reading histogram");
      ex.printStackTrace();
    }
    return _totalBytes;
  }

