            if (commandLine != null) {
                MavenArgsParser args = MavenArgsParser.parse(commandLine);
                Optional<String> p_arg = args.get(MavenArgsParser.ARG.P);
                if (p_arg.isPresent()) {
                    profiles = p_arg.get().split(",");
                }
                profilesDiscovered = true;
            }
        }

        return profiles;
    }

