@Override
    public boolean add(final Edge e) {
        checkNonNullEdgeObject(e);

        EdgeImpl edge = (EdgeImpl) e;
        if (allowReferences || edge.storeId == EdgeStore.NULL_ID) {
            //checkIdDoesntExist(edge.getLongId());
            if (dictionary.containsKey(edge.getLongId())) {
                return false;
            }
            checkSourceTargets(edge);

            boolean directed = edge.isDirected();
            NodeImpl source = edge.source;
            NodeImpl target = edge.target;

            incrementVersion();

            if (garbageSize > 0) {
                for (int i = 0; i < blocksCount; i++) {
                    EdgeBlock edgeBlock = blocks[i];
                    if (edgeBlock.hasGarbage()) {
                        edgeBlock.set(edge);
                        garbageSize--;
                        dictionary.put(edge.getLongId(), edge.storeId);
                        break;
                    }
                }
            } else {
                ensureCapacity(1);
                currentBlock.add(edge);
                dictionary.put(edge.getLongId(), edge.storeId);
            }

            insertOutEdge(edge);
            insertInEdge(edge);

            source.outDegree++;
            target.inDegree++;

            if (directed && !edge.isSelfLoop()) {
                EdgeImpl mutual = getMutual(edge);
                if (mutual != null) {
                    edge.setMutual(true);
                    mutual.setMutual(true);
                    source.mutualDegree++;
                    target.mutualDegree++;
                    mutualEdgesSize++;
                }
            }

            if (!directed) {
                undirectedSize++;
            }

            size++;
            return true;
        } else if (isValidIndex(edge.storeId) && get(edge.storeId) == edge) {
            return false;
        } else {
            throw new IllegalArgumentException("The edge already belongs to another store");
        }
    }

