@Override
    public double measure(Vector<Double> x, Vector<Double> y) {
        int n, j;
        double xt, yt;

        double sumX = 0.0;
        double sumX2 = 0.0;
        double sumY = 0.0;
        double sumY2 = 0.0;
        double sumXY = 0.0;
        //number of non-zero elements
        n = 0;
        for (j = 0; j < x.size(); j++) {
            if ((!Double.isNaN(x.get(j))) && (!Double.isNaN(y.get(j)))) {
                xt = x.get(j);
                yt = y.get(j);

                sumXY += xt * yt;
                sumX += xt;
                sumX2 += xt * xt;
                sumY += yt;
                sumY2 += yt * yt;
                n++;
            }
        }

        double meanX = sumX / n;
        double meanY = sumY / n;
        sumXY -= meanY * sumX;
        sumX2 -= meanX * sumX;
        sumY2 -= meanY * sumY;

        return correlation(n, sumXY, sumX2, sumY2);
    }

