public static boolean avroSchemaCollectionContains(
      final KijiSchemaTable schemaTable,
      final Collection<AvroSchema> schemaCollection,
      final AvroSchema element
  ) throws IOException {
    for (AvroSchema schema : schemaCollection) {
      if (avroSchemaEquals(schemaTable, schema, element)) {
        return true;
      }
    }
    // If none match, return false.
    return false;
  }

@Test
  public void testAvroSchemaListContains() throws IOException {
    final KijiSchemaTable schemaTable = getKiji().getSchemaTable();

    final long stringUID = schemaTable.getOrCreateSchemaId(STRING_SCHEMA);
    final long intUID = schemaTable.getOrCreateSchemaId(INT_SCHEMA);
    final String stringJSON = STRING_SCHEMA.toString();
    final String intJSON = INT_SCHEMA.toString();

    final AvroSchema stringUIDAS = AvroSchema.newBuilder().setUid(stringUID).build();
    final AvroSchema stringJSONAS = AvroSchema.newBuilder().setJson(stringJSON).build();
    final AvroSchema intUIDAS = AvroSchema.newBuilder().setUid(intUID).build();
    final AvroSchema intJSONAS = AvroSchema.newBuilder().setJson(intJSON).build();

    final List<AvroSchema> stringList = Lists.newArrayList(stringJSONAS, stringUIDAS);
    final List<AvroSchema> intList = Lists.newArrayList(intJSONAS, intUIDAS);
    final List<AvroSchema> bothList = Lists.newArrayList(stringJSONAS, intUIDAS);

    assertTrue(AvroUtils.avroSchemaCollectionContains(schemaTable, stringList, stringJSONAS));
    assertTrue(AvroUtils.avroSchemaCollectionContains(schemaTable, stringList, stringUIDAS));
    assertFalse(AvroUtils.avroSchemaCollectionContains(schemaTable, stringList, intUIDAS));
    assertTrue(AvroUtils.avroSchemaCollectionContains(schemaTable, intList, intJSONAS));
    assertTrue(AvroUtils.avroSchemaCollectionContains(schemaTable, intList, intUIDAS));
    assertFalse(AvroUtils.avroSchemaCollectionContains(schemaTable, intList, stringUIDAS));
    assertTrue(AvroUtils.avroSchemaCollectionContains(schemaTable, bothList, stringJSONAS));
    assertTrue(AvroUtils.avroSchemaCollectionContains(schemaTable, bothList, intUIDAS));
  }

public static KijiRowKeyComponents fromComponents(Object... components) {
    Preconditions.checkNotNull(components);
    Preconditions.checkArgument(components.length > 0);
    Preconditions.checkNotNull(components[0], "First component cannot be null.");

    // Some of these checks will be redundant when the KijiRowKeyComponents is converted
    // into an EntityId, but putting them here helps the user see them at the time of creation.
    if (components[0] instanceof byte[]) {
      Preconditions.checkArgument(components.length == 1, "byte[] only valid as sole component.");
      // We need to make a deep copy of the byte[] to ensure that a later mutation to the original
      // byte[] doesn't confuse hash codes, etc.
      byte[] original = (byte[])components[0];
      return new KijiRowKeyComponents(new Object[]{Arrays.copyOf(original, original.length)});
    } else {
      boolean seenNull = false;
      for (int i = 0; i < components.length; i++) {
        if (seenNull) {
          Preconditions.checkArgument(
              components[i] == null,
              "Kiji Row Keys cannot contain have a non-null component after a null component");
        } else {
          Object part = components[i];
          if (part == null) {
            seenNull = true;
          } else {
            Preconditions.checkArgument(
                (part instanceof String) || (part instanceof Integer) || (part instanceof Long),
                "Components must be of type String, Integer, or Long.");
          }
        }
      }
    }

    // Pass in a copy rather than the actual array, just in case the user called us with an
    // Object[], which would make components mutable.
    return new KijiRowKeyComponents(Arrays.copyOf(components, components.length));
  }

@Test
  public void testFormattedCompare() {
    List<KijiRowKeyComponents> sorted = ImmutableList.of(
        KijiRowKeyComponents.fromComponents("a", null, null),
        KijiRowKeyComponents.fromComponents("a", 123, 456L),
        KijiRowKeyComponents.fromComponents("a", 456, null));

    List<KijiRowKeyComponents> shuffled = Lists.newArrayList(sorted);
    Collections.shuffle(shuffled);
    Collections.sort(shuffled);

    Assert.assertEquals(sorted, shuffled);
  }

