public Object convertToTypedObject(Object source, Type type)
			throws ClassNotFoundException, IllegalAccessException,
			NoSuchFieldException, InstantiationException {
		LOGGER.debug("convertToTypedObject(source = {}, type = {})", source,
				type);

		if (type instanceof PrimitiveType) {
			LOGGER.debug("Type is a Primitive Type");
			return source;
		} else if (type instanceof ListType) {
			LOGGER.debug("Type is a List Type");

			ListType listType = (ListType) type;
			Object[] components = (Object[]) source;

			List<Object> list = new ArrayList<Object>();

			for (Object component : components) {
				list.add(convertToTypedObject(component,
						listType.getElementType()));
			}
			return list;
		} else if (type instanceof RecordType) {
			LOGGER.debug("Type is a Record(Map) Type");

			RecordType recordType = (RecordType) type;

			Class<?> recordClass = classLoader.loadClass(recordType);
			Map<String, Object> map = new HashMap<String, Object>();

			for (Entry<String, Type> entry : recordType.getFieldTypes()
					.entrySet()) {
				Object fieldValue = recordClass.getField(entry.getKey()).get(
						source);
				map.put(entry.getKey(),
						convertToTypedObject(fieldValue, entry.getValue()));
			}
			return map;
		}
		LOGGER.error("Type is invalid");
		throw new InstantiationException();
	}

