        a.addAssociation(Aras.HAS_FORENAME, new SNText("Fred"));
        b.addAssociation(Aras.HAS_FORENAME, new SNText("Ted"));
        c.addAssociation(Aras.HAS_NAME_PART, new SNText("M."));

        o.addAssociation(Aras.HAS_FORENAME, new SNText("Ed"));
