public static long estimatedSizeOf(Statement statement) {
        Value object = statement.getObject();
        Resource context = statement.getContext();
        long result = STATEMENT_OVERHEAD
                + 2 * URI_BNODE_OVERHEAD // subject, predicate
                + OBJ_REF // reference to the statement
                + StringSizeEstimator.estimatedSizeOf(statement.getSubject().stringValue())
                + StringSizeEstimator.estimatedSizeOf(statement.getPredicate().stringValue());

        // object
        if (object instanceof Literal) {
            Literal literal = (Literal) object;
            result += LITERAL_OVERHEAD + StringSizeEstimator.estimatedSizeOf(literal.stringValue());
            if (literal.getLanguage() != null) {
                result += StringSizeEstimator.estimatedSizeOf(literal.getLanguage());
            }
            if (literal.getDatatype() != null) {
                result += URI_BNODE_OVERHEAD + StringSizeEstimator.estimatedSizeOf(literal.getDatatype().stringValue());
            }
        } else {
            result += URI_BNODE_OVERHEAD + StringSizeEstimator.estimatedSizeOf(object.stringValue());
        }

        // context
        if (context != null) {
            result += URI_BNODE_OVERHEAD + StringSizeEstimator.estimatedSizeOf(context.stringValue());
        }

        return result;
    }

@Test
    public void estimatedSizeOfWithoutLiteral() throws Exception {
        // Arrange
        Statement statement = VALUE_FACTORY.createStatement(
                VALUE_FACTORY.createBNode("http://a"),
                VALUE_FACTORY.createURI("http://b"),
                VALUE_FACTORY.createURI("http://c"),
                VALUE_FACTORY.createURI("http://d"));

        // Act
        long size = StatementSizeEstimator.estimatedSizeOf(statement);

        // Assert
        long stringsSize = 4 * StringSizeEstimator.estimatedSizeOf("http://a");
        long minOverhead = 5 * 8 + 9 * 4 + 4 * 8; // objects + object references + int fields
        long maxOverhead = 5 * 16 + 9 * 8 + 4 * 8;
        assertTrue(size <= maxOverhead + stringsSize);
        assertTrue(size >= minOverhead + stringsSize);
    }

String renameType(Type type) {
        if (type == null) {
            return null;
        }

        if (type.getSort() == Type.OBJECT) {
            String in = type.getInternalName();
            return "L" + renameInternalType(in) + ";";
        } else if (type.getSort() == Type.ARRAY) {
            StringBuilder sb = new StringBuilder();
            for (int n = type.getDimensions(); n > 0; n--) {
                sb.append('[');
            }
            sb.append(renameType(type.getElementType()));
            return sb.toString();
        }
        return type.getDescriptor();
    }

