    while (true) {
      if (isShutdown) {
        log.info("Is shut down, giving up and returning null");
        return null;
      }

      try {
        T returnObj = callable.call();
        return new RetryResult<>(returnObj, retryCount);
      } catch (Exception e) {
        handleException(retryEndTime, e, reporter, retryCounter);
      }
    }
  }

