public void checkFreeTierBillingUsage() {
    // retrieve the costs stored in the DB from the last time this was run
    final Map<DbUser, Double> previousUserCosts = workspaceFreeTierUsageDao.getUserCostMap();

    // retrieve current workspace costs from BigQuery and store in the DB
    final Map<DbWorkspace, Double> workspaceCosts = getFreeTierWorkspaceCostsFromBQ();
    workspaceCosts.forEach(workspaceFreeTierUsageDao::updateCost);

    // sum current workspace costs by workspace creator
    final Map<DbUser, Double> userCosts =
        workspaceCosts.entrySet().stream()
            .collect(
                Collectors.groupingBy(
                    e -> e.getKey().getCreator(), Collectors.summingDouble(Entry::getValue)));

    // check cost and time thresholds for the relevant users

    // collect previously-expired and currently-expired users by cost and time
    // for users which are expired: alert only if they were not expired previously
    // for users which are not yet expired:
    //    check for intermediate thresholds and alert, possibly for both cost and time

    final Set<DbUser> previouslyExpiredUsers = getExpiredUsersFromDb();

    final Set<DbUser> expiredUsers =
        userCosts.entrySet().stream()
            .filter(e -> costAboveLimit(e.getKey(), e.getValue()))
            .map(Entry::getKey)
            .collect(Collectors.toSet());

    final Set<DbUser> newlyExpiredUsers = Sets.difference(expiredUsers, previouslyExpiredUsers);
    for (final DbUser user : newlyExpiredUsers) {
      try {
        mailService.alertUserFreeTierExpiration(user);
      } catch (final MessagingException e) {
        logger.log(Level.WARNING, e.getMessage());
      }
      updateFreeTierWorkspacesStatus(user, BillingStatus.INACTIVE);
    }

    final Set<DbUser> usersWithNonNullRegistration =
        userDao.findByFirstRegistrationCompletionTimeNotNull();
    final Set<DbUser> usersToThresholdCheck =
        Sets.difference(usersWithNonNullRegistration, expiredUsers);

    sendAlertsForCostThresholds(usersToThresholdCheck, previousUserCosts, userCosts);
  }

@Test
  public void checkFreeTierBillingUsage_exceedsDollarThresholds() throws MessagingException {
    final double limit = 100.0;
    final double costUnderThreshold = 49.5;

    double threshold = 0.5;
    double costOverThreshold = 50.5;
    double remaining = limit - costOverThreshold;

    workbenchConfig.billing.defaultFreeCreditsDollarLimit = limit;

    final DbUser user = createUser(SINGLE_WORKSPACE_TEST_USER);
    createWorkspace(user, SINGLE_WORKSPACE_TEST_PROJECT);

    // set an arbitrary registration time

    final Instant registrationTime = START_INSTANT.minus(Period.ofDays(100));
    user.setFirstRegistrationCompletionTime(Timestamp.from(registrationTime));
    userDao.save(user);

    // check that we have not alerted before the threshold

    doReturn(mockBQTableSingleResult(costUnderThreshold)).when(bigQueryService).executeQuery(any());
    freeTierBillingService.checkFreeTierBillingUsage();
    verifyZeroInteractions(mailService);

    // check that we alert for the 50% threshold

    doReturn(mockBQTableSingleResult(costOverThreshold)).when(bigQueryService).executeQuery(any());
    freeTierBillingService.checkFreeTierBillingUsage();
    verify(mailService)
        .alertUserFreeTierDollarThreshold(
            eq(user), eq(threshold), eq(costOverThreshold), eq(remaining));

    // check that we do not alert twice for the 50% threshold

    doReturn(mockBQTableSingleResult(costOverThreshold)).when(bigQueryService).executeQuery(any());
    freeTierBillingService.checkFreeTierBillingUsage();
    verifyZeroInteractions(mailService);

    // check that we alert for the 75% threshold

    threshold = 0.75;
    costOverThreshold = 75.3;
    remaining = limit - costOverThreshold;

    doReturn(mockBQTableSingleResult(costOverThreshold)).when(bigQueryService).executeQuery(any());
    freeTierBillingService.checkFreeTierBillingUsage();
    verify(mailService)
        .alertUserFreeTierDollarThreshold(
            eq(user), eq(threshold), eq(costOverThreshold), eq(remaining));

    // check that we do not alert twice for the 75% threshold

    doReturn(mockBQTableSingleResult(costOverThreshold)).when(bigQueryService).executeQuery(any());
    freeTierBillingService.checkFreeTierBillingUsage();
    verifyZeroInteractions(mailService);

    // check that we alert for expiration when we hit 100%

    final double costToTriggerExpiration = 100.01;

    doReturn(mockBQTableSingleResult(costToTriggerExpiration))
        .when(bigQueryService)
        .executeQuery(any());
    freeTierBillingService.checkFreeTierBillingUsage();
    verify(mailService).alertUserFreeTierExpiration(eq(user));

    // check that we do not alert twice for 100%

    doReturn(mockBQTableSingleResult(costToTriggerExpiration))
        .when(bigQueryService)
        .executeQuery(any());
    freeTierBillingService.checkFreeTierBillingUsage();
    verifyZeroInteractions(mailService);
  }

