public boolean contains(String source, String subStr){

	char [] sub = subStr.toCharArray();
	original = source.toCharArray();
	int count = 0;
	int j = 0;
	for(int i = 0; i < original.length; i ++){
	   if(count == sub.length){
	   	   break;
	   }
	   if(j < sub.length )
	   {
			if(original[i] == sub[j]){
		       count++;
			   j++;

			}
			else{
			count = 0;
			j = 0;
			}

		}	
	}

	return count == sub.length?true:false;	

}

