@Override
    public int randomInteger(final int lower, final int upper) {
        satisfies(lower <= upper, "the upper bound must be equal to or greater than the lower bound");

        if (lower == upper) {
            return lower;
        }

        int diff = upper - lower;
        if (diff >= 0 && diff != Integer.MAX_VALUE) {
            return (lower + random.nextInt(diff + 1));
        }
        int i;
        do {
            i = random.nextInt();
        } while (i < lower || i > upper);
        return i;
    }

@Test
    public void returnsSingleIntegerValueWhenLowerAndUpperBoundAreEqual() {
        assertThat(randomValues.randomInteger(1, 1))
                .isEqualTo(1);

        assertThat(randomValues.randomInteger(0, 0))
                .isEqualTo(0);

        assertThat(randomValues.randomInteger(Integer.MIN_VALUE, Integer.MIN_VALUE))
                .isEqualTo(Integer.MIN_VALUE);

        assertThat(randomValues.randomInteger(Integer.MAX_VALUE, Integer.MAX_VALUE))
                .isEqualTo(Integer.MAX_VALUE);
    }

static DelegateType findDelegateTypeInDelegateConfigs(String className, Map<DelegateType, List<String>> delegateConfig, LandMatcher matcher) {
        for (Map.Entry<DelegateType, List<String>> entry : delegateConfig.entrySet()) {
