        // exact on drawing time (friday)
        currentDate = ZonedDateTime.of(2017, 4, 7, 19, 0,0, 0, ZoneId.of("Europe/Paris"));
        expected = ZonedDateTime.of(2017, 4, 14, 20, 0,
                0, 0, ZoneId.of("Europe/Paris"));
        assertThat(euroJackpotLottery.getNextDrawing(currentDate, null), is(expected));

        // one day before drawing
        currentDate = ZonedDateTime.of(2017, 4, 6, 16, 0,0, 0, ZoneId.of("Europe/Paris"));
