public static List<String> parseNestList(String str) {
        NestListState state = NestListState.START;
        ArrayList<String> list = new ArrayList<>();
        field.setLength(0);
        int quoteCount_InParentheses = 0;
        int leftNotMatchCount_InParentheses = 0;
        boolean outMostIsFunction = false;


        for (char c : str.toCharArray()) {
            switch (state) {
                case START:
                    if (c == whitespace) {
                        // ignore, stay at START state
                    } else if (c == separator) {
                        list.add("");
                    } else if (c == quote) {
                        field.setLength(0);
                        state = NestListState.QUOTE;
                    } else if (c == leftParentheses) {
                        field.setLength(0);
                        outMostIsFunction = false;
                        leftNotMatchCount_InParentheses = 1;
                        quoteCount_InParentheses = 0;
                        state = NestListState.IN_PARENTHESES;
                    } else {
                        field.setLength(0);
                        field.append(c);
                        state = NestListState.NO_QUOTE;
                    }
                    break;

                case NO_QUOTE:
                    if (c == separator) {
                        list.add(field.toString());
                        state = NestListState.START;
                    } else if (c == leftParentheses) {
                        field.append(c);
                        outMostIsFunction = true;
                        leftNotMatchCount_InParentheses = 1;
                        quoteCount_InParentheses = 0;
                        state = NestListState.IN_PARENTHESES;
                    } else {
                        field.append(c);
                    }
                    break;

                case QUOTE:
                    if (c == quote) {
                        state = NestListState.QUOTE2;
                    } else {
                        field.append(c);
                    }
                    break;

                case QUOTE2:
                    if (c == separator) {
                        list.add(field.toString());
                        state = NestListState.START;
                    } else if (c == quote) {
                        field.append(quote);
                        state = NestListState.QUOTE;
                    } else {
                        field.append(c);
                        state = NestListState.NO_QUOTE;
                    }
                    break;
                case IN_PARENTHESES:
                    if (c == quote) {
                        quoteCount_InParentheses++;
                    }

                    if (quoteCount_InParentheses % 2 == 1) { //在转义符号中
                        field.append(c);
                    } else if (c == leftParentheses) {
                        leftNotMatchCount_InParentheses++;
                        field.append(c);
                    } else if (c == rightParentheses) {
                        leftNotMatchCount_InParentheses--;
                        if (leftNotMatchCount_InParentheses > 0 || outMostIsFunction) {
                            field.append(c);
                        }
                        if (leftNotMatchCount_InParentheses == 0) {
                            state = NestListState.PARENTHESES_OK;
                        }
                    } else {
                        field.append(c);
                    }
                    break;
                case PARENTHESES_OK:
                    if (c == whitespace) {
                        // ignore, stay at START state
                    } else if (c == separator) {
                        list.add(field.toString());
                        state = NestListState.START;
                    } else {
                        throw new RuntimeException("最外层的()之后应该是空格和逗号");
                    }

                    break;
            }
        }

        switch (state) {
            case START: //注意这里和CSVParser的不同，这里最后一个分隔符后面如果没有符号，就不算
                break;
            default:
                list.add(field.toString());
                break;
        }
        list.trimToSize();
        return list;
    }

public static List<List<String>> parse(String source) {
        ArrayList<List<String>> result = new ArrayList<>();
        ArrayList<String> record = new ArrayList<>();
        State state = State.START;

        field.setLength(0);

        for (int i = 0; i < source.length(); i++) {
            char c = source.charAt(i);

            switch (state) {
                case START:
                    switch (c) {
                        case comma:
                            record.add("");
                            break;
                        case quote:
                            field.setLength(0);
                            state = State.QUOTE;
                            break;
                        case cr:
                            field.setLength(0);
                            state = State.CR;
                            break;
                        default:
                            field.setLength(0);
                            field.append(c);
                            state = State.NO_QUOTE;
                            break;
                    }
                    break;

                case NO_QUOTE:
                    switch (c) {
                        case comma:
                            addField(record, field);
                            state = State.START;
                            break;
                        case cr:
                            state = State.CR;
                            break;
                        default:
                            field.append(c);
                            break;
                    }
                    break;

                case QUOTE:
                    switch (c) {
                        case quote:
                            state = State.QUOTE2;
                            break;
                        default:
                            field.append(c);
                            break;
                    }
                    break;

                case QUOTE2:
                    switch (c) {
                        case comma:
                            addField(record, field);
                            state = State.START;
                            break;
                        case quote:
                            field.append(quote);
                            state = State.QUOTE;
                            break;
                        case cr:
                            state = State.CR;
                            break;
                        default:
                            field.append(c); //忽略了"，
                            state = State.NO_QUOTE;
                            break;
                    }
                    break;

                case CR:
                    switch (c) {
                        case comma:
                            field.append(cr);
                            addField(record, field);
                            state = State.START;
                            break;
                        case lf:
                            addField(record, field);
                            addRecord(result, record);

                            record = new ArrayList<>(record.size()); //优化下存储
                            state = State.START;
                            break;
                        default:
                            field.append(cr);
                            field.append(c);
                            state = State.NO_QUOTE;
                            break;
                    }
                    break;
            }
        }

        switch (state) {
            case START:
                if (!record.isEmpty()) {
                    record.add("");
                    addRecord(result, record);
                }
                break;
            case CR:
                field.append(cr);
                addField(record, field);
                addRecord(result, record);
                break;
            default:
                addField(record, field);
                addRecord(result, record);
                break;
        }

        result.trimToSize();
        return result;
    }

