public String concatenateStrings(String delimiter, String... parts) {
    if (parts == null) {
      return "";
    }
    if (delimiter == null) {
      delimiter = "";
    }

    return Stream.<String> of(parts)
        .map(StringUtility::emptyIfNull)
        .collect(Collectors.joining(delimiter));
  }

