public static INDArray padWithEdge(INDArray src, int len) {
        int channel = src.size(0);
        int height = src.size(1);
        int width = src.size(2);
        INDArray dst = Nd4j.zeros(channel, height + len * 2, width + len * 2);

        for (int h = 0; h < dst.size(1); h++) {
            for (int w = 0; w < dst.size(2); w++) {
                for (int c = 0; c < channel; c++) {
                    if (w < len || h < len || w > width - len - 1 || h > height - len - 1) {
                        dst.putScalar(new int[] {c, h, w}, src.getFloat(new int[] {
                                c,
                                min(max(h, len) - len, height - 1),
                                min(max(w, len) - len, width - 1)
                        }));
                    } else {
                        dst.putScalar(new int[] {c, h, w}, src.getFloat(new int[] {c, h - len, w - len}));
                    }
                }
            }
        }
        return dst;
    }

@Test
    public void testPad() {
        INDArray from = Nd4j.create(new double[] {
                1, 2, 3, 4, 5, 6, 7, 8},
                new int[] {2, 2, 2});
        INDArray res = padWithEdge(from, 1);

        assertThat(res.getInt(0, 0, 0), is(1));
        assertThat(res.getInt(0, 0, 1), is(1));
        assertThat(res.getInt(0, 0, 2), is(2));
        assertThat(res.getInt(0, 0, 3), is(2));
        assertThat(res.getInt(0, 1, 0), is(1));
        assertThat(res.getInt(0, 1, 1), is(1));
        assertThat(res.getInt(0, 1, 2), is(2));
        assertThat(res.getInt(0, 1, 3), is(2));
        assertThat(res.getInt(0, 2, 0), is(3));
        assertThat(res.getInt(0, 2, 1), is(3));
        assertThat(res.getInt(0, 2, 2), is(4));
        assertThat(res.getInt(0, 2, 3), is(4));
        assertThat(res.getInt(0, 3, 0), is(3));
        assertThat(res.getInt(0, 3, 1), is(3));
        assertThat(res.getInt(0, 3, 2), is(4));
        assertThat(res.getInt(0, 3, 3), is(4));
    }

public static void convolveFft(double[][] src, double[][] kernel, double[][] dst) {

        int h = nearestPowerOf2(src.length);
        int w = nearestPowerOf2(src[0].length) * 2;

        double[][] rSrc = createArray2d(h, w, (q, p) -> (q >= src.length || p >= src[0].length) ? 0.0 : src[q][p]);
        double[][] rK = createArray2d(h, w, (q, p) -> (q >= kernel.length || p >= kernel[0].length) ? 0.0 : kernel[q][p]);

        DoubleFFT_2D fft = new DoubleFFT_2D(h, w / 2);
        fft.realForwardFull(rSrc);
        fft.realForwardFull(rK);

        double[][] mul = new double[h][w];
        for (int q = 0; q < rSrc.length; q++) {
            for (int p = 0; p < rSrc[0].length; p += 2) {
                mul[q][p] = rSrc[q][p] * rK[q][p] - rSrc[q][p + 1] * rK[q][p + 1];
                mul[q][p + 1] = rSrc[q][p + 1] * rK[q][p] + rSrc[q][p] * rK[q][p + 1];
            }
        }

        fft.complexInverse(mul, true);

        for (int q = 0; q < dst.length; q++) {
            for (int p = 0; p < dst[0].length; p++) {
                dst[q][p] += mul[q + (kernel.length + 1) / 2][(p + (kernel[0].length + 1) / 2) * 2];
            }
        }
    }

@Test
    public void testConvFft() {
        double[][] src = new double[][] {{1, 2, 3, 4}, {4, 5, 6, 7}, {7, 8, 9, 10}};
        double[][] kernel = new double[][] {{1, 1}, {1, 1}};
        double[][] dst = new double[2][2];
        convolveFft(src, kernel, dst);
        System.out.println(Arrays.toString(dst[0]));
        System.out.println(Arrays.toString(dst[1]));
    }

