	    			isUpdateNeeded = true;
//	    			throw new IncorrectPasswdException();
	    		}
	    	}
    	}
    	//
    	User user = null;
		try {
			user = ldapAuthenticationService.authenticate(loginName, passwd);
		} catch (Exception e) {
			throw new IncorrectPasswdException();
		}
    	if(user != null) {
