				if (c == '}') {
					if (builder.length() > 0) {
						handler.handleParam(builder.toString());
						builder.setLength(0);
					}
					state = State.OutsideParam;
				}
				else {
					builder.append(c);
				}
				break;
			}
			case OutsideParam: {
				if (c == '{') {
					if (builder.length() > 0) {
						handler.handleText(builder.toString());
						builder.setLength(0);
					}
					state = State.InsideParam;
				}
				else {
					builder.append(c);
				}
				break;
			}
			}
		}
		if (builder.length() > 0) {
			switch (state) {
			case InsideParam:
				handler.handleParam(builder.toString());
				break;
			case OutsideParam:
				handler.handleText(builder.toString());
				break;
			}
		}
	}

