public static <T> CloseableIterator<T> autoClose(final CloseableIterator<? extends T> iterator) {
        requireNonNull(iterator);
        return new CloseableIterator<T>() {
            private boolean closed = false;

            @Override
            public void close() {
                if (closed)
                    return;

                closed = true;
                iterator.close();
            }

            @Override
            public boolean hasNext() {
                try {
                    if (closed)
                        return false;
                    if (!iterator.hasNext()) {
                        closeQuietly();
                        return false;
                    }
                    return true;
                } catch (RuntimeException re) {
                    closeQuietly();
                    throw re;
                }
            }

            @Override
            public T next() {
                if (!closed) {
                    try {
                        return iterator.next();
                    } catch (RuntimeException re) {
                        closeQuietly();
                        throw re;
                    }
                }
                throw new NoSuchElementException();
            }

            @Override
            public void remove() {
                if (!closed) {
                    try {
                        iterator.remove();
                    } catch (RuntimeException re) {
                        closeQuietly();
                        throw re;
                    }
                }
                throw new IllegalStateException();
            }
        };
    }

@Test
    public void testAutoClose() {
        MockIterator<Integer> iterator = testIterator();
        CloseableIterator<Integer> closeableIterator = autoClose(iterator);
        closeableIterator.close();
        assertTrue(iterator.isClosed());

        //if consumed close
        iterator = testIterator();
        closeableIterator = autoClose(iterator);
        Iterators.size(closeableIterator);
        assertTrue(iterator.isClosed());

        //if exception thrown
        iterator = testExceptionThrowingIterator();
        closeableIterator = autoClose(iterator);
        try {
            closeableIterator.next();
            fail();
        } catch (RuntimeException ignored) {
        }
        assertTrue(iterator.isClosed());

        iterator = testIterator();
        closeableIterator = autoClose(iterator);
        closeableIterator.close();
        try {
            closeableIterator.next();
        } catch (NoSuchElementException ignored) {
        }
        assertTrue(iterator.isClosed());

        iterator = testExceptionThrowingIterator();
        closeableIterator = autoClose(iterator);
        try {
            closeableIterator.remove();
            fail();
        } catch (RuntimeException ignored) {
        }
        assertTrue(iterator.isClosed());

        iterator = testIterator();
        closeableIterator = autoClose(iterator);
        closeableIterator.close();
        try {
            closeableIterator.remove();
        } catch (IllegalStateException ignored) {
        }
        assertTrue(iterator.isClosed());
    }

