                Map<ResourceId, List<ResourceId>> dependencyMap = resolveDependency(resources);
                updateIrdInstance(cfg, resources, dependencyMap, rwx);
            }
        } catch (Exception e) {
            cleanupIrdInstance(cfg, rwx);
        }
    }

