@Override
    public int findTokenEnd(CharSequence text, int cursor) {
        // base case: empty string
        int length = text.length();
        if (length == 0) {
            return 0;
        }

        // iterate forward until we get a space, a new line or the end of the string
        char separator = getDefaultSeparator();
        for (int i = cursor; i < length; i++) {
            char charAt = text.charAt(i);
            if (charAt == separator || charAt == NEW_LINE) {
                return i == 0 ? 0 : i - 1;
            }
        }

        return length;
    }

public static String stripPrefixHandle(char handle, @Nullable CharSequence text) {
        if (TextUtils.isEmpty(text)) {
            return "";
        }
        return text.charAt(0) == handle ? text.toString().substring(1) : text.toString();
    }

