@Override
    public CharSequence terminateToken(CharSequence text) {
        int i = text.length();
        char separator = getDefaultSeparator();

        // the text is empty or already has a trailing space
        if (i == 0 || (i > 0 && text.charAt(i - 1) == separator)) {
            return text;
        }

        // append a trailing space to the string
        if (text instanceof Spanned) {
            SpannableString sp = new SpannableString(text + String.valueOf(separator));
            TextUtils.copySpansFrom((Spanned) text, 0, text.length(), Object.class, sp, 0);
            return sp;
        } else {
            return text + String.valueOf(separator);
        }
    }

@Test
    public void terminateToken() throws Exception {
        MatcherAssert.assertThat(tokenizer.terminateToken(""), is("")); // empty string stays same
        MatcherAssert.assertThat(tokenizer.terminateToken(" "), is(" ")); // don't add spaces
        MatcherAssert.assertThat(tokenizer.terminateToken("test "), is("test ")); // don't add spaces
        MatcherAssert.assertThat(tokenizer.terminateToken("test"), is("test ")); // add spaces
    }

@Override
    public int findTokenStart(CharSequence text, int cursor) {
        // base case: empty string
        if (text.length() == 0) {
            return 0;
        }

        // iterate back until we find the prefix
        char separator = getDefaultSeparator();
        for (int i = cursor - 1; i >= 0; i--) {
            if (matchesPrefix(text, i)) {
                char charAt; // consider separator or new line as a token start
                if (i == 0 || (charAt = text.charAt(i - 1)) == separator || charAt == NEW_LINE) {
                    return i;
                }
            }
        }

        return cursor;
    }

