public String html(String s) {
        if (s == null) {
            return null;
        }
        final int l = s.length();
        final StringBuffer sb = new StringBuffer(l);
        for (int i = 0; i < l; i++) {
            final char ch = s.charAt(i);
            switch (ch) {
                case '&':
                    sb.append("&amp;");
                    break;
                case '<':
                    sb.append("&lt;");
                    break;
                case '>':
                    sb.append("&gt;");
                    break;
                case '"':
                    sb.append("&#34;");
                    break;
                case '\'':
                    sb.append("&#39;");
                    break;
                default:
                    sb.append(ch);
            }
        }
        return sb.toString();
    }

