@Test
    public void redundantSavingShouldFail() {
        Container c = new Container("c1");
        DatabaseConnection databaseConnection = new DatabaseConnection();
        String exceptionString = "";
        Exception ex = null;

        try {
            databaseConnection.saveContainer(c);
        } catch (Exception e) {
            ex = e;
            exceptionString = e.getMessage();
        }

        assert (ex == null);
        assert (exceptionString.equals(""));

        try {
            databaseConnection.saveContainer(c);
        } catch (Exception e) {
            ex = e;
            exceptionString = e.getMessage();
        }

        assert (ex != null);
        assert (exceptionString.equals("element already saved"));
    }

public String anserFor(int number) {

        String answer = "";

        if(isDivisibleBy(number,3)){
            answer += "Fizz";
        }

        if(isDivisibleBy(number, 5)){
            answer += "Buzz";
        }

        return answer.isEmpty() ? String.valueOf(number) : answer;
    }

